import{J as e,M as t,Y as n,q as r}from"./DjneNb1u.js";import{t as i}from"./HclGiUj8.js";var a=[`en`,`tl`,`pa`,`fr`,`es`,`ar`,`zh-Hant`,`zh-Hans`,`de`,`hi`,`vi`,`ko`,`ur`,`pl`,`uk`,`ru`,`so`,`crk`,`pdt`],o={en:{native:`English`,english:`English`,htmlLang:`en`,dir:`ltr`},tl:{native:`Tagalog`,english:`Tagalog`,htmlLang:`tl`,dir:`ltr`},pa:{native:`ਪੰਜਾਬੀ`,english:`Punjabi`,htmlLang:`pa`,dir:`ltr`},fr:{native:`Français`,english:`French (Canadian)`,htmlLang:`fr-CA`,dir:`ltr`},es:{native:`Español`,english:`Spanish`,htmlLang:`es`,dir:`ltr`},ar:{native:`العربية`,english:`Arabic`,htmlLang:`ar`,dir:`rtl`},"zh-Hant":{native:`繁體中文`,english:`Chinese (Traditional)`,htmlLang:`zh-Hant`,dir:`ltr`},"zh-Hans":{native:`简体中文`,english:`Chinese (Simplified)`,htmlLang:`zh-Hans`,dir:`ltr`},de:{native:`Deutsch`,english:`German`,htmlLang:`de`,dir:`ltr`},hi:{native:`हिन्दी`,english:`Hindi`,htmlLang:`hi`,dir:`ltr`},vi:{native:`Tiếng Việt`,english:`Vietnamese`,htmlLang:`vi`,dir:`ltr`},ko:{native:`한국어`,english:`Korean`,htmlLang:`ko`,dir:`ltr`},ur:{native:`اردو`,english:`Urdu`,htmlLang:`ur`,dir:`rtl`},pl:{native:`Polski`,english:`Polish`,htmlLang:`pl`,dir:`ltr`},uk:{native:`Українська`,english:`Ukrainian`,htmlLang:`uk`,dir:`ltr`},ru:{native:`Русский`,english:`Russian`,htmlLang:`ru`,dir:`ltr`},so:{native:`Soomaali`,english:`Somali`,htmlLang:`so`,dir:`ltr`},crk:{native:`ᓀᐦᐃᔭᐍᐏᐣ`,english:`Plains Cree`,htmlLang:`crk`,dir:`ltr`},pdt:{native:`Plautdietsch`,english:`Plautdietsch (Mennonite Low German)`,htmlLang:`pdt`,dir:`ltr`}},s=`audit_lang`,c=`lang`;function l(e){return!!e&&a.includes(e)}function u(e){let t=e.toLowerCase();if(t.startsWith(`zh`))return t.includes(`hant`)||t.startsWith(`zh-hk`)||t.startsWith(`zh-tw`)||t.startsWith(`zh-mo`)?`zh-Hant`:`zh-Hans`;let n=t.split(`-`)[0];return l(n)?n:null}function d(){let e=new URL(window.location.href).searchParams.get(c);if(l(e))return e;try{let e=localStorage.getItem(s);if(l(e))return e}catch{}let t=navigator.languages??[navigator.language];for(let e of t){let t=u(e);if(t)return t}return`en`}var f={tl:()=>i(()=>import(`./Exe5GWJ1.js`),[],import.meta.url),pa:()=>i(()=>import(`./DMNhRMzA.js`),[],import.meta.url),fr:()=>i(()=>import(`./CWemuRJX.js`),[],import.meta.url),es:()=>i(()=>import(`./BylWCwzd.js`),[],import.meta.url),ar:()=>i(()=>import(`./CtQpgiji.js`),[],import.meta.url),"zh-Hant":()=>i(()=>import(`./Dxq9YnVe.js`),[],import.meta.url),"zh-Hans":()=>i(()=>import(`./CSTLWQgB.js`),[],import.meta.url),de:()=>i(()=>import(`./DIipMZND.js`),[],import.meta.url),hi:()=>i(()=>import(`./BGYsbWU9.js`),[],import.meta.url),vi:()=>i(()=>import(`./qVD9NVvd.js`),[],import.meta.url),ko:()=>i(()=>import(`./BWBDeGvb.js`),[],import.meta.url),ur:()=>i(()=>import(`./D93yw4yi.js`),[],import.meta.url),pl:()=>i(()=>import(`./BGI4jGJh.js`),[],import.meta.url),uk:()=>i(()=>import(`./BSFYBkKp.js`),[],import.meta.url),ru:()=>i(()=>import(`./C_h0oSce.js`),[],import.meta.url),so:()=>i(()=>import(`./Caqpmjrs.js`),[],import.meta.url),crk:()=>i(()=>import(`./CUSxDYcO.js`),[],import.meta.url),pdt:()=>i(()=>import(`./y-ICYiWC.js`),[],import.meta.url)},p={},m=e(0);function h(){return t(m)}function g(e){return p[e]}async function _(e){if(e===`en`||p[e])return;let t=f[e];if(t)try{p[e]=(await t()).default,n(m)}catch{}}var v=e(`en`);{let e=d();r(v,e,!0),_(e);let t=new URL(window.location.href);t.searchParams.get(c)!==e&&(t.searchParams.set(c,e),window.history.replaceState({},``,t.toString()))}function y(e){if(!l(e))return;r(v,e,!0),_(e);try{localStorage.setItem(s,e)}catch{}let t=new URL(window.location.href);t.searchParams.set(c,e),window.history.replaceState({},``,t.toString())}var b={get current(){return t(v)}},x={selector:{label:`Choose language`},verdict:{headline:`Alberta is redrawing its electoral map.`,p_what:`Every so often the province redraws its ridings — the local areas that each elect one MLA. Where the lines fall decides who you vote with, and who represents you in the legislature.`,p_split:`This time, the panel doing the redraw split. It produced two competing maps — and this audit tests both of them.`,p_question:`We tested both maps for one question: is either one shaped to favour a party — even if no one set out to do that?`,p_answer:`One of the two is. The other looks normal.`,p_howfar:`A computer drew 1.01 million legal versions of the map at random. One of the two real maps is more one-sided than all but about 1 in 568,000 of them, in the UCP’s favour. The other sits in the normal range.`,aside_pre:`You might call a map shaped like that `,aside_post:`. That word has no legal meaning in Canada, so we don’t use it as a verdict. We show you what the map does; you judge. For the deeper layers — what the law actually requires, and exactly how we ran the test — see `,box_heading:`What we can and can’t say`,box_can_1:`The minority map sits outside what 1.01 million neutral maps produce, in the UCP’s favour.`,box_can_2:`All four partisan-fairness measures point the same way.`,box_cant_1:`That any commissioner intended this — the audit reads outcomes, not motives.`,box_cant_2:`That the map “is” a gerrymander — that isn’t a category Canadian law recognizes.`,box_cant_3:`How a court would rule, or what the committee will choose.`,law_link:`Law`,methods_link:`Methods`},why_redrawn:{heading:`Why this happens — and why it touches you`,p1:`Alberta is divided into 87 ridings. Each one elects a single MLA to the legislature. Your riding decides who that person is, which neighbourhoods get grouped with yours, and whose concerns your MLA hears first.`,p2:`The lines don’t stay fixed. As people move and cities grow, some ridings end up with far more voters than others, so the province redraws the map every few years to keep them roughly even. A panel of commissioners does the drawing, working from rules set out in law: districts have to be close in population, stay in one piece, and keep real communities together where they can.`,p3:`That’s the normal process. This time it broke down. The commissioners couldn’t agree, and split into two camps, each with its own map. Then a committee of MLAs set both of those maps aside and began drawing its own, larger one. A legislative committee overriding the commission like that is rare.`,p4:`A line on a map decides whose vote counts for what. It can keep a community’s voters together, or scatter them across several districts where their numbers no longer add up to much. It can keep some races close and put others out of reach. None of that shows on the surface; it is set by where the boundaries fall.`},two_maps:{heading:`Two maps — and who drew them`,p1:`When the commission split, it didn’t produce one map with a dissent attached. It produced two complete, competing maps. Both are legal. They just draw the lines differently.`,p2:`A boundary commission has five members. The Chief Justice of Alberta names the chair — the neutral seat, here held by Dallas K. Miller, a former Court of King’s Bench judge. The party in government names two members; the opposition names two.`,p3:`This commission divided three to two. The chair and the two opposition-appointed members backed one map — the majority report, because most of the commission signed it. The two government-appointed members backed the other — the minority report.`,p4:`The map the audit flags as the more one-sided is the minority report — the one the two government-appointed members drew. The audit can’t show whether they meant to, and doesn’t try. It shows what the map does.`,p5:`The cover map at the top of this page lets you compare them yourself. Flip between the two proposals and today’s map, find your own riding, and watch which neighbourhoods get grouped together or split apart.`,p6:`A committee of MLAs has since set both maps aside to draw its own, due later in 2026 — a move this site looks at on the Law page. These two remain the audit’s clearest test case, and the same tests will apply to whatever the committee produces.`},disclaimer:{text:`AI translated this site. Some of it may still appear in English while the translations are in progress. If you notice errors or would like to help translate this project, please %s.`,link_label:`contact us`,word_count:`For scale: the English prose runs about {count} words. You are welcome to take on all of it or just a part. In most cases the work is fixing small errors the machine made, not translating from scratch.`},epigraph:{heading:`On reading this map`,reader:`Land doesn't vote. Colouring the map this way only makes rural Alberta look bigger than it is. Leave the empty land empty.`,reader_label:`a reader`,author_p1:`Fair — and that is exactly what the map does. It is built from Elections Alberta's own geometry and counts, at the only resolution they keep: how many people voted in each voting area, and how. The colour runs on a spectrum between the two parties, and its depth follows population — which is why the cities glow and the open country stays pale.`,author_p2:`The land west of Ponoka is pure white: no polling station, no one recorded living or voting there. It is blank precisely because land doesn't vote. The aim is not to interpret the data, only to let it speak at the grain it was recorded in — and to leave you a little wiser than you came.`,author_label:`the author`,ethic:`That is the commitment behind the whole audit: map the system, and let the data speak for itself — no more than it allows.`},opener:{heading:`Who's this for?`,body:`Us. All of us. Rural, Urban, curious, wonk, journalist, lawyer, academic, politician — all of us. Because it impacts all of us. Whether or not you like the party in power, what the split commission produced has never been done before. And it's given us the opportunity to peer inside the machine in ways we never could before. Now we can establish a baseline — a series of tests, and everything that comes after can be graded on it. Let me show you what I found.`},stakes:{q1:{heading:`Is the proposed map a gerrymander?`,body:`"Gerrymander" is not a term Canadian courts use, and this audit does not apply it as a verdict. What the audit can say is narrower and factual: four of the five structural tests it runs flag the <em>minority proposal</em> and none flag the alternative (the <em>majority proposal</em>); the fifth test is neutral for both. Whether that pattern amounts to what people informally mean by a "gerrymander" is a judgment this audit leaves to the reader.`,footnote:`The "majority" and "minority" names come from a 3–2 split among the Electoral Boundaries Commission (chaired by Justice Miller), which produced two competing proposals rather than a single recommendation. The legislature has since set both aside and referred redistricting to a six-MLA committee chaired by Brandon Lunty (a UCP MLA); the committee oversees a separate four-person Independent Advisory Panel — two members nominated by the Premier (Hon. Monte Solberg and Darwin Durnie), two by the Leader of the Opposition (Dr. Gerard Kennedy and Brent Robinson) — tasked with producing a new 91-seat boundary proposal before the November 2026 deadline.`},q2:{heading:`What does "gerrymander" mean in Canadian law?`,body:`There isn't one. The Canadian test is different: whether the boundaries give voters <em>effective representation</em> under section 3 of the Charter. The minority proposal raises serious questions under the effective-representation standard; only a judge can answer them definitively, and no one has asked one yet.`},q3:{heading:`What's at stake for Albertans?`,body:`At a 50/50 provincial vote, the audit's measurements place the minority proposal at a structural extreme: fewer than 100 of the 1.01 million neutral comparison maps produce the same kind of seat imbalance. That imbalance matters because a 60-of-89 majority leaves only a token opposition and is effectively immune to internal dissent — not because it crosses any special threshold (Alberta's Assembly has no two-thirds rule; the same procedural powers are available to a bare majority). Whether the minority proposal's tilt is large enough to push one party past that 60-seat threshold at vote shares <em>other</em> than 50/50 is a question this audit has not yet tested. Whether that imbalance is acceptable is a question for Albertans, not for this audit.`},cta_law:`Read the legal context →`,cta_methods:`See how we tested →`,scorecard_h:`The scorecard`,scorecard_fig_alt:`Scatter plot: efficiency gap on the horizontal axis, count of structural tests failed on the vertical axis. The 2019 enacted map and the 2026 majority map cluster in the safe lower-left corner. The 2026 minority map appears alone in the upper-right outlier region.`,scorecard_fig_caption:`Both lanes on one picture. Horizontal: how skewed the partisan-fairness number is (right = more UCP-favoured). Vertical: how many of five structural-fairness tests the map fails. Bottom-left is the safe corner where neutral procedures routinely land; the upper-right is the outlier region. The 2019 enacted map and the 2026 majority sit in the safe corner. The 2026 minority sits alone in the outlier region.`,scorecard_intro:`Two independent measurements applied to both maps under the same pre-registered thresholds. Structure uses only the shape of the lines — no election results. Numbers tests how the lines convert votes into seats. Both lanes reach the same conclusion.`,scorecard_close:`Two independent measurements, one answer. The convergence is the audit's strongest single signal.`},top_callouts:{gerrymander_lead:`Is the minority map a gerrymander?`,gerrymander_body:`On the audit’s joint partisan-bias score, the commission’s minority map sits in the extreme tail of 1,010,000 algorithmically-drawn neutral comparison maps — approximately 69 of them reach its seat share at a tied vote, and the odds of its combined profile under neutral drawing are at most roughly 1&nbsp;in&nbsp;568,000. The majority map falls well within normal range.`,tldr_label:`TL;DR`,tldr_p1:`Alberta’s commission split, the government took the pen, and a six-MLA committee (the Lunty committee) reports in November 2026. Neither commission map is law.`,tldr_p2:`This audit tested both commission maps the same way, against 1,010,000 computer-drawn neutral maps built from official Elections Alberta files. The majority proposal looks like the maps neutral drawing routinely produces — it passes every pre-registered test. The minority proposal crosses four of five structural tests, and at a tied 50/50 vote only about 69 of the 1,010,000 neutral maps award as many seats as it does. The odds that a neutral process produces its overall fairness profile work out to about 1 in 568,000 — and that figure is a deliberately cautious ceiling, not a precise estimate. One measure, the efficiency gap, landed just under the audit’s pre-set line; it is reported as a miss.`,tldr_p3:`The audit measures outcomes, not intent. When the Lunty committee releases its map, this audit will apply the same tests to it.`,tldr_footer:`Pre-registered falsification conditions and retraction commitments are in %s.`,tldr_footer_link:`Retractions and Corrections`},picture:{heading:`The picture, before the proof`,lead:`Three maps, two ways of measuring. One dot is not like the others. This picture is the audit’s whole case in one image — and right now you have no way to judge whether it means anything. The lines on it are not laws. The corner is not a courtroom. By the end of this page you will know exactly what this picture can prove, and exactly what it cannot. The log comes back to it at the end.`},head:{title:`Alberta's Electoral Map, Audited`,meta_description:`Alberta's 2026 boundary commission filed two maps. One looks normal; the other favours the UCP further than nearly every one of 1,010,000 neutral maps. The committee map that replaces both is scored here against tests locked in advance.`},nav:{skip_to_content:`Skip to content`,home_aria:`Back to top`,theme_aria:`Toggle dark/light mode`,theme_title:`Toggle dark mode`,nav_aria:`Open table of contents`,drawer_top:`↑ Top`,route_story:`Story`,route_law:`Law`,route_methods:`Methods`,stakes:`Stakes`,findings:`Findings`,history:`History`,reform:`Reform`,group_overview:`Overview`,group_audit:`The audit`,group_context:`Context`,group_forward:`Going forward`,group_apparatus:`Apparatus`,why:`Why does this matter?`,map:`The map at a glance`,split:`How the commission broke`,litmus:`1,010,000-Map Litmus Test`,crack_pack:`Cracking, packing, draining`,for_you:`What this means for you`,impact:`Impact on the ground`,gerrymanders:`Clean gerrymanders`,history_full:`A history of gerrymandering`,canada:`Canada's different`,lunty:`Lunty`,suggestions:`Reform suggestions`,smoking_gun:`The smoking gun`,picture:`The picture`,act1:`Act I: The map`,act2:`Act II: The simulation`,act3:`Act III: The conduct`,revisited:`The scorecard, revisited`,explainers:`Explainers A–N`,retractions:`Retractions`,authors_view:`The author's view`,references:`References`,technical:`Technical resources`,feedback:`Send feedback`,happened:`What happened`,does:`What the map does`,law:`What the law requires`,system:`How the committee got the job`,know:`How we know`,test:`The November test`,mind:`What would change my mind`,evidence:`The full record`,fixes:`Fixes for next time`,bar_aria:`Site`,bar_home:`Main page`,bar_evidence:`Full record`,bar_explorer:`Map explorer`,bar_norms:`Norms`,bar_explainers:`Explainers`,bar_fixes:`Fixes`,bar_feedback:`Feedback`,group_this_page:`On this page`,group_pages:`Pages`},hero:{h1:`Laws, Norms, & Statistics: An Audit of the 2026 Alberta Electoral Boundaries Commission Reports`,subtitle:`Alberta's commission produced two competing riding maps in 2026. I ran the same tests on both and asked one question: do they treat voters the same way?`,badge:`Official Elections Alberta maps — Published May 2026`,cover_note:`Click to zoom in and explore all three boundary maps at once. Pin the viewport and flip between maps. The boundaries shift; the voters stay put. Scroll down for the analysis.`,cover_note_1:`This map is the best way in. Click it to zoom and explore. The buttons at the top switch between the minority map, the majority map and the 2019 enacted boundaries, or layer all three to see exactly where they part ways. <strong>Detail</strong> colours each polling area by how people voted in 2023. <strong>Trend</strong> adds party shading by district (blue UCP, orange NDP). <strong>Lines</strong> turns boundaries on and off. <strong>Find</strong> jumps to any riding by name.`,cover_note_2:`Lock the viewport and flip between maps. Watch a boundary move while the voters underneath stay still. The whole question, in one gesture.`,cover_note_3:`When you're done exploring, scroll down for the summary. The full technical analysis is in the Resources section. All of the data comes from official Elections Alberta shapefiles and other government and open-source records.`,image_alt:`Alberta electoral district maps — minority commission proposal, coloured by 2023 vote`,map_hint:`Click to explore interactively`,btn_title:`Click to open interactive map`,btn_aria:`Click to explore interactively`},boundary:{heading:`What this audit can and can't tell you`,can_1:`The minority map's geometry crosses 4 of 5 pre-registered structural thresholds <em>without using any election data at all</em>. The fifth (anchoring) is neutral. The majority crosses 0 of the 4 firing. These tests measure properties of the boundary lines themselves — district shape, municipal anchoring, population spread — and reach the conclusion before any vote is counted.`,can_2:`Separately, when election data is brought in, the minority map sits at the 99.99th percentile of 1.01 million algorithmically-drawn comparison maps matched on population balance and contiguity (the ensemble enforces those two requirements, not every statutory criterion such as communities of interest). Roughly 69 of those 1.01 million neutral maps reach the same seat share at a tied vote. Counting both analytical channels, the odds of this profile under neutral drawing are at most about 1 in 568,000. Two analytical instruments — geometric and statistical — reach the same conclusion, favouring the same party; the joint bound is the dependence-aware summary of that convergence, not four independent tests reading in agreement.`,can_3:`Three of the configurations the minority proposal contains were flagged in writing by Commission Chair Justice Miller in the majority report's response to the minority (final report, pp. 62–63). The audit's tests were run with no knowledge of his flags and surface the same regions. Because Justice Miller chaired the commission and signed the majority report, these are the chair's own criticisms — corroborating, not a fully independent third instrument — but the audit's blind tests landing on the same regions is still striking.`,cant_1:`The audit does <strong>not</strong> establish that any commissioner intended the partisan effects it measures. Boundary geometry cannot reveal intent.`,cant_2:`The audit does <strong>not</strong> predict what the Lunty committee will choose, what the November 2026 vote will be, or how Albertans will react.`,cant_3:`The audit does <strong>not</strong> predict how a court would rule if a Charter challenge were brought against either proposal.`,cant_4:`The audit does <strong>not</strong> claim the dependence-robust bound of approximately 1 in 568,000 (p&nbsp;≤&nbsp;1.76×10<sup>−6</sup>) is the probability that a gerrymander occurred. That number is the tail probability of the minority's geometry under a neutral algorithmic null. It is evidence the neutral null is implausible. It is not a posterior probability of partisan intent — that question requires evidence the geometry cannot supply.`,cant_5:`The audit does <strong>not</strong> tell any individual voter what position to take or what to do with this information. The choice is yours.`},editorial_intro:{heading:`What is redistricting, and why it matters`,p1:`Every voter in Alberta lives in an <em>electoral district</em> — a slice of the province that elects one person to the legislature. There are 87 districts. Each district elects one MLA. When you cast a ballot in a provincial election, you are choosing the MLA for the district you live in. For most Albertans, that is the whole connection to the legislature: one MLA, one district, one vote.`,p2:`Those district lines are not permanent. People move, neighbourhoods grow, rural areas thin out, cities sprawl. Every eight to ten years, Alberta is supposed to redraw the lines so each district is roughly the right size and reflects the way Albertans actually live now. The body that does the redrawing is the <em>Electoral Boundaries Commission</em> — an independent commission with judges, lawyers, and public members, not politicians.`,p3:`This is the standard process. This time, the standard process produced something unusual. The commission's five members split 3–2 on what the map should look like, and rather than settling on one recommendation they produced two: a <em>majority proposal</em> (backed by three commissioners) and a <em>minority proposal</em> (backed by two). Both are sitting on the table. On April 21, 2026 the Legislative Assembly passed Government Motion 37, setting both aside and referring redistricting to a six-MLA Select Special Committee chaired by Brandon Lunty (a UCP MLA). The committee oversees a separate four-person Independent Advisory Panel, constituted under the same motion, tasked with producing a new 91-seat map; the committee must deliver its report to the legislature by November 2, 2026.`,p4:`Why it matters to you: the lines decide who your MLA is. They decide which neighbourhoods, towns, and concerns get represented together. If your city is split across four MLAs instead of one, no single representative is accountable for the city as a whole. If your community of interest — a small town, a rural region, a downtown core — is divided between districts, your voice on provincial decisions is diluted. The map also shapes which party can form a government, and at what margins. The audit's specific finding (the minority proposal sits at a structural extreme) is the reason you are reading this site, but the broader question is older and applies to every redistricting cycle: do the lines reflect the way Albertans live, or do they shape the politics following?`,p5:`The rest of this page walks through what the two proposed maps actually do.`,key_terms_lead:`Key terms in this section — click to read:`},editorial_reflect:{heading:`Interlude: What this means for you and your community`,intro_p1:`The log pauses here. Which party gains or loses seats is the legislature's problem — it is not where you experience these maps. You experience them through three concrete questions about your own district:`,intro_q1:`Where does your MLA live?`,intro_q2:`Are they invested in your community?`,intro_q3:`Will the demands of the district's urban head dominate its rural tails?`,intro_p2:`Every other framing — partisan advantage, supermajority threshold, statistical extreme — eventually points back to those three. The five rungs below walk through how each proposed map answers them, at five scales.`,you_h:`You.`,you_p:`Your electoral district decides who represents you in the legislature. Right now you live in one of 87 districts. Under both proposed maps you may live in a different one — possibly with a different MLA, possibly anchored to different neighbouring communities. If you don't know what district you're in right now, or who your MLA is, you're not alone: most Albertans couldn't name their MLA. But the boundary lines are not abstract. They decide whose phone number is on your local representative's office wall, whose neighbourhood petition gets your name attached to it, whose concerns your MLA hears about first. The map explorer on this site — search for your community by name — shows which district you sit in under each proposal. If your district changes, your representative changes — and your representative's relationship to your community changes with it.`,community_h:`Your community.`,community_p:`Communities are not abstract either. A high school's catchment area, a chamber of commerce, a faith community, a neighbourhood association — these are real groupings of people with shared local concerns. When a boundary line cuts through them, no single MLA is responsible for the whole. Casing 1 is the extreme case: Airdrie, one city in four pieces, no single representative accountable for it. The same dynamic plays out anywhere a town, neighbourhood, or recognised community of interest is split — the bigger the split, the weaker the representation. (On the broader measure of how faithfully each map follows municipal lines overall, both proposals sit inside the Canadian norm — Casing 5 records the finding that dissolved.)`,municipality_h:`Your municipality.`,municipality_p:`When a city is fractured across many representatives, its ability to bargain on provincial decisions weakens. A council asking for transit funding, a school board negotiating a new school, a mayor lobbying for highway extensions — each of those goes better when the city can point to a few MLAs who owe accountability to the city as a whole. The minority proposal splits Calgary's north, east, and central districts across multiple divisions whose vote-share patterns suggest <em>packing</em> (concentrating one party's voters into a few high-margin seats) on top of <em>cracking</em> (splitting the other party's voters across many low-margin seats). Whether the pattern is intentional is a question the audit cannot answer — boundary geometry doesn't reveal intent. What it can say is that the four statistical measures flag the same districts the structural tests flag, and that the alternative proposal does not produce the same fingerprint.`,region_h:`Your region.`,region_p1:`If you live outside Alberta's cities you have probably noticed political conversations about boundaries always seem to centre the cities. It's a fair complaint, so let's be direct about what this audit does and does not say about rural Alberta.`,region_p2:`What it does <strong>not</strong> say: rural Alberta has too many seats. The EBCA allows district populations to vary by up to 25% so one rural MLA isn't representing a geography the size of southern France. Canadian courts treat the variance as legitimate. Both proposed maps preserve it. Nothing in this audit changes it.`,region_p3:`What it <strong>does</strong> say: in several places on the minority proposal, rural communities are being attached as the <em>tail</em> of a district whose population centre sits in a city. Look at Casing 1's Airdrie split again, this time from the rural side: three of its four districts extend out into a different stretch of rural countryside, and in each the population centre is the urban slice, not the rural tail. An MLA elected from that kind of district is most likely to live, campaign, and prioritise where the votes are — which means rural communities formerly represented by a dedicated rural MLA become the back half of an urban-led seat. That pattern repeats on the minority proposal in ways it does not on the majority proposal.`,region_p4:`The audit doesn't propose taking seats away from rural Alberta. It asks whether the lines respect the rural communities those seats are meant to represent, or whether rural geography is being used as ballast to absorb urban votes into districts whose centre is somewhere else. If you live in one of those rural tails, the question of which map gets enacted decides whether your MLA represents the rural community you actually live in, or an urban district whose lines happen to include your land.`,province_h:`Your province.`,province_p:`The legislature is what you get when you sum every district's answers to the three questions above. If most districts are anchored to communities whose MLAs actually live in them, the legislature represents those communities. If most districts have rural tails attached to urban heads, the legislature represents the heads — and the tails get whatever attention is left over. The partisan question — which party wins a majority — is downstream of that. The large-majority question — whether one party crosses 60 of 89 seats, a margin that makes a government effectively immune to floor-crossings and leaves an opposition too small to sustain scrutiny — is downstream of <em>that</em>. At a hypothetical 50/50 provincial split, the audit's measurements place the minority proposal at a structural extreme: fewer than 100 of the 1.01 million neutral comparison maps produce the same kind of seat imbalance. Whether that imbalance pushes a party past 60 seats at the vote shares Albertans actually deliver is a question this audit has not yet directly tested — an honest gap in the record. Whether the answer to any of these questions matters enough to act on is, again, a question for you.`},editorial_history:{heading:`Context: A short history of gerrymandering`,p1:`The word comes from 1812. Massachusetts governor Elbridge Gerry signed off on a state-senate map whose districts were so contorted in his party's favour that a Boston cartoonist drew one of them as a salamander — wings, claws, a forked tongue. The cartoonist's pun, <em>Gerry-mander</em>, stuck. The shape stuck too: two centuries later, the word still means drawing electoral lines to engineer a partisan outcome.`,p2:`The term endures because the problem endures. Anywhere voters choose representatives from geographic districts, someone has to draw the lines, and the lines can be drawn many ways. Different countries have arrived at different answers about who should do the drawing and what should constrain them.`,p3:`<strong>The United States</strong> treats partisan gerrymandering as a problem the federal courts mostly cannot fix. In <em>Rucho v. Common Cause</em> (2019), the U.S. Supreme Court ruled that partisan gerrymanders are nonjusticiable "political questions" the federal courts will not resolve. Some states (California, Michigan) have responded by creating independent citizen commissions to draw their own lines; others (Texas, North Carolina) have continued to draw openly partisan maps and defended them on the basis that <em>Rucho</em> permits it.`,p4:`<strong>The United Kingdom</strong> uses four permanent Boundary Commissions — one each for England, Scotland, Wales, and Northern Ireland — staffed by judges and senior civil servants. They redraw lines roughly every eight years against fixed rules (population equality, geographic coherence, respect for local government boundaries). Since the Parliamentary Constituencies Act 2020, their final recommendations take effect automatically by Order in Council, with no parliamentary vote required — Parliament's former power to reject them was removed.`,p5:`<strong>Australia</strong> delegates the work to the Australian Electoral Commission, a federal independent agency with full authority over both election administration and boundaries. Redistributions happen automatically when a state's seat count changes or seven years pass since the last one. The commissioners' decisions are reviewable on procedural grounds but not on partisan ones. As in the U.K., gerrymandering as Americans know it is virtually unheard of.`,p6:`These three cases bracket the spectrum: courts staying out (U.S.), independent commissions with strong parliamentary deference (U.K.), and a permanent independent agency with full authority (Australia). Canada sits somewhere different again — which is what the next section takes up.`},glossary:{more_link:`Learn more →`,"electoral-district":{term:`Electoral district (ED)`,definition:`The geographic area that elects one member to the provincial legislature, often shortened to "ED" after first use. Each ED has one MLA. (The word "riding" usually refers to federal districts. Alberta's statutes call a provincial one an electoral division.)`},riding:{term:`Riding`,definition:`In Canada, the word most often means a federal electoral district. Alberta's statutes call the provincial equivalent an "electoral division". This site calls it a riding, a district or a division interchangeably.`},mla:{term:`MLA`,definition:`Member of the Legislative Assembly: the person one electoral district elects to represent it in the Alberta legislature.`},ucp:{term:`UCP`,definition:`United Conservative Party, Alberta's governing provincial party today. It formed in 2017 when the Progressive Conservatives and the Wildrose Party merged, and it has held government since 2019.`},ndp:{term:`NDP`,definition:`New Democratic Party (Alberta NDP), Alberta's official opposition today. It held government from 2015 to 2019.`},gerrymander:{term:`Gerrymander`,definition:`Drawing electoral boundaries to give a party an advantage. The word comes from an 1812 Massachusetts map. Canadian law has no offence by that name. That limits what a court will call it, not whether it happens. The closest legal test is effective representation under section 3 of the Charter.`},cracking:{term:`Cracking`,definition:`A gerrymandering technique: split a voting bloc across many districts so it never reaches a majority in any single one. Divide a city across four ridings, for example, and its voters are outnumbered in each.`},packing:{term:`Packing`,definition:`A gerrymandering technique: crowd one party's voters into a small number of districts. The party wins those districts overwhelmingly but "wastes" many votes, and fewer of its voters are left to compete in other districts.`},draining:{term:`Draining`,definition:`This audit's term for a follow-on effect of cracking and packing. The wasted votes those techniques produce get pushed into strategically chosen places, where they alter the political character of nearby electoral districts. The framing is the audit's own, not an established concept in the redistricting literature. The audit tests for the effect and finds results consistent with it, but treats it as exploratory, not as a settled methodology.`},anchoring:{term:`Anchoring`,definition:`How firmly the proposed boundaries follow existing municipal lines, such as city limits and town boundaries. A highly anchored map mostly respects those lines. A loosely anchored map often departs from them, especially at politically meaningful spots, and that is a structural warning sign.`},"charter-s3":{term:`Section 3 of the Charter`,definition:`The section of the Canadian Charter of Rights and Freedoms that guarantees citizens the right to vote. Canadian courts read it not as a strict "one person, one vote" rule but as a right to "effective representation."`},"effective-representation":{term:`Effective representation`,definition:`The standard Canadian courts apply when they judge electoral boundaries. It means voters should have a meaningful voice. Equal riding populations are part of that, but so is recognition of community ties, geography and minority representation. The leading statement is from the Supreme Court of Canada's 1991 Saskatchewan Reference.`},ebc:{term:`Electoral Boundaries Commission (EBC)`,definition:`The body that draws Alberta's provincial electoral boundaries under the EBCA. Justice Miller chaired the 2026 commission. Its commissioners split 3–2 and produced two competing proposals, the majority and minority proposals, instead of a single recommendation.`},"lunty-committee":{term:`Lunty committee`,definition:`The Select Special Committee on Electoral Boundaries: six MLAs, four UCP and two NDP, chaired by UCP MLA Brandon Lunty. Government Motion 37 (introduced April 16, passed April 21, 2026) created it after the Assembly set both commission maps aside. It oversees an Independent Advisory Panel that produces a 91-seat proposal, and it must report to the Legislature by November 2, 2026. It sits outside the standard commission process. No law requires it to hold public hearings.`},"advisory-panel":{term:`Independent Advisory Panel`,definition:`The panel the Lunty committee engaged under Government Motion 37 to draw a 91-seat proposal. The Premier nominated the Hon. Monte Solberg and Darwin Durnie. The Leader of the Opposition nominated Dr. Gerard Kennedy and Brent Robinson. Alberta's acting chief justice declined to help find a judge to chair it, and retired Court of Appeal justice Brian O'Ferrall was later named chair. The panel advises. The committee's MLAs decide.`},ebca:{term:`EBCA`,definition:`The Electoral Boundaries Commission Act — the Alberta law that sets the rules a new map must follow, including how far district populations may vary.`},ensemble:{term:`The 1.01-million-map test`,definition:`A computer drew 1.01 million legal Alberta maps at random. All of them follow the same rules, and the computer never sees a vote, which is what makes them neutral. A real map counts as unusual when it falls outside what almost all of these maps produce.`},efficiency_gap:{term:`Efficiency gap`,definition:`A measure of "wasted" votes, compared between the two parties. A vote is wasted if it goes to a loser, or if it goes to a winner beyond what the win needed. A large gap points to a one-sided map.`},mean_median:{term:`Mean-median gap`,definition:`Take a party's vote share in each district. The mean-median gap is the distance between the average of those shares and the middle (median) one. A large gap suggests its voters are spread in a way that wastes votes.`},declination:{term:`Declination`,definition:`A measure of how lopsidedly each party wins its seats: by blowouts or by squeakers. After a June 2026 sign correction, it points the same way on the minority map as the other measures do, toward the governing party.`},seats_5050:{term:`Seats at a tie`,definition:`How many seats each party would win if the province split its vote exactly 50-50. It strips out who actually won and tests the map's built-in tilt.`},fsa:{term:`Forward sortation area (FSA)`,definition:`The first three characters of a Canadian postal code (the letter-digit-letter part). About 270 FSAs cover Alberta. Most fall entirely within a single electoral district.`}},home:{hero:{h1:`Alberta's Electoral Map, Audited`,subtitle:`Alberta's boundary commission split in 2026 and filed two maps. I set both beside 1.01 million maps a computer drew with no stake in who wins. The majority's map sits among them. The minority's leans to the UCP further than almost any of them.`,status:`The committee map that replaces both is due Monday, November 2, 2026. Within 72 hours, this page will score it.`,week:`<strong>This week.</strong> I registered the November tests before the committee's map existed (OSF registration qsgy8). I'll publish the scores whichever way they point. The first check is the one the government picked: <a href="#recommendation-5">Recommendation 5</a>.`},happened:{h:`What happened`,p1:`Every so often Alberta redraws its ridings, the districts that each send one MLA to the Legislature. Where the lines fall can decide who wins.`,p2:`On March 23, 2026 the independent commission doing the redraw split three to two and filed two maps. Both are legal under the Act. The chair and the two commissioners nominated by the opposition wrote the majority map. The two commissioners nominated by the government wrote the minority map. Same rules, same data, same 1,345 public submissions. Two maps.`,p3:`The majority map looks like what a neutral process draws. The minority map doesn't:`,li1:`It splits Airdrie, a city of 85,805, into four districts. Outside Airdrie East, which holds more than half the city, Airdrie's residents are a minority.`,li2:`In north-east and central Calgary, where the NDP won thirteen of seventeen seats in 2023, its districts run 11.5% above the provincial average.`,li3:`Split the vote dead even and it hands the UCP 51.7% of the seats. Only 69 of 1,010,000 computer-drawn maps give more.`,li4:`Replay the 2023 election-day vote and the UCP takes 60 of 89 seats. On the majority map, 55.`,p4:`The Assembly adopted neither map. On April 21 it passed Government Motion 37, which handed the job to the Select Special Committee on Electoral Boundaries: six MLAs, four UCP and two NDP, chaired by UCP MLA Brandon Lunty. The committee's 91-seat map is due November 2. CBC has reported there will be no public hearings on it, and no draft released first for the public to comment on.`,box_h:`What I can say, and what I can't`,can1:`The minority map falls outside what 1.01 million neutral maps produce, in the UCP's favour.`,can2:`All four partisan-fairness measures lean the same way.`,cant1:`That any commissioner meant to do this. My tests measure what a map does. They can't show motive.`,cant2:`That the government directed its nominees. I found no evidence of coordination. Appointing someone is not evidence of it.`,cant3:`That the pattern will happen again. The map that has it was never enacted. November will show whether it comes back.`,cant4:`How a court would rule, or what the committee will choose.`,p5:`<strong>On the word.</strong> Gerrymandering means drawing lines to give a party an advantage. You recognise it by what a map does, and by what is known about how it was drawn. Canadian law has no offence by that name, so a court won't rule on gerrymandering as such. That doesn't mean it can't happen here. The closest legal test is effective representation under section 3 of the Charter, covered below.`,p6:`<strong>Reading the cover map.</strong> The cover colours Alberta's 4,765 voting areas by how people in each one voted in 2023: orange where NDP votes are concentrated, blue where UCP votes are. The colour deepens only where lots of people live, so a voting area spread over hundreds of square kilometres of parkland stays pale. West of Ponoka the land is pure white, because it has no polling station and nobody was recorded living or voting there. The lines on top are the minority map's 89 proposed districts. <a href="__BASE__/explorer">Open the map explorer</a> to switch between all three maps.`},does:{h:`What the minority map does`,p1:`The two maps agree on most of Alberta. Where they differ, here is what the minority map chose, and what each choice does.`,h3_1:`One city, four districts`,p2:`Airdrie has 85,805 people (2024 municipal census), one city council and one school division. The law caps each district at one-and-a-quarter times the provincial average, so Airdrie needs at least two districts. The majority map gives it two.`,p3:`The minority map gives it four: north to Olds-Three Hills-Didsbury, east to Airdrie East, west to Calgary-Foothills-Airdrie West, and centre-south to Calgary-Airdrie. Airdrie East takes more than half the city, and nine in ten of its people are Airdrie residents. Nearly all the rest of the city goes to the two Calgary-edge districts, where Calgary residents outnumber Airdrie's. The north piece holds about 350 people. The split meets every criterion of my pre-registered cracking test. The majority's two-way split meets none.`,p4:`Splitting a community so thinly that it can't decide any of its seats is called cracking. That is what happens to the part of Airdrie outside Airdrie East. Airdrie would have four MLAs. Most of the voters who elect three of them live outside Airdrie.`,h3_2:`Bigger districts where the NDP is strongest`,p5:`In Calgary's north-east and central districts, where the NDP won thirteen of seventeen seats in 2023, the minority map's districts average 11.5% above the provincial average population. The majority's average 2.8%. A bigger district means each vote in it counts for less. Putting one party's voters into fewer, larger districts is called packing. This pattern meets my pre-registered packing test.`,h3_3:`Unequal district sizes`,p6:`Equal district populations are the one value Alberta's law puts a number on. By the commission's own population tables, the minority map's districts miss the ideal size by 4,707 people on average. On the majority map, 3,180. The minority's spread is 48% wider. On 2021 census numbers the gap narrows: the two maps' average deviations are almost the same, though the minority's typical district is still further from equal (3,938 against 2,827). The usual defence of odd lines is that they were needed to balance populations. On the numbers the commission itself used, that defence doesn't work here.`,h3_4:`Rural tails on urban districts`,p7:`I'm not saying rural Alberta has too many seats. The Act lets district populations vary by up to 25%, so one rural MLA doesn't have to cover an area the size of southern France. Both maps use that room.`,p8:`But in several places the minority map ties rural communities to a district whose population centre is in a city. Three of Airdrie's four pieces run out into a different stretch of countryside, and in each the district's population centre falls in the urban part. The minority map does this in places where the majority doesn't.`,h3_5:`Three boundaries the chair called out`,p9:`The commission's chair flagged four of the minority's boundaries as geographically anomalous, among them these three:`,li1:`the Rocky Mountain House–Banff Park extension into uninhabited national-park land;`,li2:`the lasso-shaped corridor of Calgary-Nolan Hill–Cochrane;`,li3:`the reach of Olds–Three Hills–Didsbury into north Airdrie.`,p10:`The chair signed the majority report, so you would expect him to criticise only the minority. But I ran my geometry tests without knowing which boundaries he had flagged, and they independently confirmed three of his four geometric flags.`,p11:`He called the park extension "a bad faith effort" to claim a population protection, section 15(2), that is written for remote communities where people actually live. My check undercuts that charge: the division qualifies under s.15(2) even without the extension. Putting the Banff townsite with Canmore makes sense as a community of interest, because the town sits inside a national park it can't grow into. His objection to the empty-park extension still stands. The townsite's placement doesn't affect it.`,h3_6:`The seat advantage`,p12:`Split the province-wide vote dead even, and this is the UCP's share of seats on each map:`,li4:`the median neutral map gives 44.8%;`,li5:`the majority map gives 46.1%, the 78th percentile;`,li6:`the minority map gives 51.7%, the 99.99th percentile, and only 69 of 1,010,000 neutral maps exceed it.`,p13:`On the minority map the UCP keeps the 45 seats it needs for a majority even if its vote share falls to about 49.7%. On the majority map it would need to win the popular vote by about 4 points. Replay the 2023 election-day vote and the minority map gives it 60 of 89 seats. On the majority map, 55.`,p14:`Sixty seats is a two-thirds majority. In Alberta, that unlocks no special power. A simple majority can already pass laws and budgets, invoke closure, change the rules of the House and set every committee's membership. Sixty seats would give the government a cushion. A few floor-crossings couldn't threaten it, and a smaller opposition would have fewer members to keep up committee scrutiny.`,p15:`None of these choices breaks Alberta's law. The Act allows splitting cities, and every district on both maps sits inside the ±25% band. Canadian law has no rule against partisan advantage as such. Its test is whether voters get effective representation.`},law:{h:`What the law requires, and what it doesn't`,h3_1:`The Constitution`,p1:`Section 3 of the Charter gives every citizen the right to vote. The Supreme Court of Canada reads it as a right to effective representation. Roughly equal voting power is the starting point, a "prime condition", but strict equality isn't required. A district can be bigger or smaller for a real reason, such as geography, community history, shared local interests or a minority community's voice. The difference has to be justified.`,p2:`Courts give legislatures a lot of room here. They ask whether reasonable people, applying those principles, could have drawn the lines this way. And no government can switch the right off: the notwithstanding clause doesn't apply to section 3.`,p3:`Courts have also looked at how a map gets made. In 2017 Nova Scotia's Court of Appeal found the province's map violated section 3, because the government had directed its independent commission to change course and the final map didn't reflect the commission's own view. The court added that a legislature may still draw a map itself.`,p4:`In 2026 the Supreme Court of Canada struck down a Quebec law that paused Quebec's commission to protect ridings in the Gaspésie (<em>Quebec (AG) v. Lalande</em>, 2026 SCC 13, 7–2, reasons May 1). Quebec could have protected them more narrowly. A unanimous vote didn't save the law. On June 12, 2026 Quebec's National Assembly passed its own 127-seat map.`,h3_2:`Alberta's statute`,p5:`The <em>Electoral Boundaries Commission Act</em> sets the commission's rules:`,li1:`<strong>Who sits.</strong> A chair appointed by cabinet from eligible roles that include judges. Four non-MLA members, two nominated by the Premier and two by the Opposition, appointed by the Speaker.`,li2:`<strong>Hearings.</strong> Public hearings before and after its draft map.`,li3:`<strong>Deadlines.</strong> A draft within seven months, and a final report within five months after that.`,li4:`<strong>Seats.</strong> 91. The Act said 89 when the commission drew its maps. Bill 32, introduced April 23, 2026, raised it to 91.`,li5:`<strong>Population.</strong> Every division within 25% of the average. Up to four remote divisions may go as low as 50% below, if the commission finds at least three of five criteria met.`,li6:`<strong>Factors.</strong> The commission must consider effective representation, and may weigh growth, communities of interest, geography and other factors.`,p6:`Both commission maps fit inside these rules.`,h3_3:`What the law doesn't require`,p7:`Most of that rulebook is addressed to "the Commission". Read plainly, it doesn't bind the Legislature or a committee of MLAs unless the committee's motion adopts it. Whether Government Motion 37 does isn't public.`,li7:`The Legislature doesn't have to adopt a commission's map. A report becomes law only if MLAs pass a bill.`,li8:`I found no provision that requires a committee of MLAs to hold hearings, be independent, publish a draft or explain its choices. Government Motion 37 reportedly says the review is expedited and does not require public hearings.`,li9:`Recommendation 5, which the government cited, binds no one.`,li10:`Elections Alberta says it needs at least a year and a half to prepare new ridings. That's a planning need. No law makes it a deadline.`,li11:`Courts don't review a law while it's being made. A challenge can only come after a boundaries law passes.`,h3_4:`It has happened here before`,p8:`In 1992 Alberta's commission could not agree. Its final report was five separate reports, one from each commissioner. On July 2, 1992 the Assembly passed Motion 24 and handed the work to a Select Special Committee of MLAs chaired by Bob Bogle. The Opposition refused to appoint members, so four Progressive Conservative MLAs drew the map. Alberta voted on it in the 1993 election.`,p9:`In 1994 the Court of Appeal let that map stand but criticised how it was made. The committee's members couldn't explain several of its boundaries and district populations. One of the smallest districts was Bogle's own. The court said a proper review was needed before the Legislature's term ran out. In 1995 the Legislature amended the Act and changed how commissions are appointed. Alberta used that process from then until 2026.`,h3_5:`What this means in November`,p10:`The committee's map can still be challenged in court. It faces the same test as any map: effective representation, with every population gap justified. Reasons matter. Alberta's Court of Appeal criticised the last committee-drawn map for not giving them. I'm scoring the map and the process. Whether it's constitutional is for a court to say.`},system:{h:`How the committee got the job`,p1:`The commission did its work in public. It held hearings in sixteen communities. It received 1,345 written submissions. And on the strength of more than 80 of them, it reversed its own interim proposal.`,p2:`Four weeks after the split, Government Motion 37 (introduced April 16, passed April 21, 2026) created the Select Special Committee on Electoral Boundaries, with six MLAs:`,li1:`four UCP: Brandon Lunty (chair), de Jonge, Sawyer and Wiebe;`,li2:`two NDP: Ganley and Gray.`,p3:`The committee oversees an Independent Advisory Panel, which drafts the 91-seat proposal. In June the committee appointed four panel members: the Hon. Monte Solberg and Darwin Durnie, nominated by the Premier, and Dr. Gerard Kennedy and Brent Robinson, nominated by the Opposition.`,p4:`Alberta's acting chief justice declined the committee's request to help find a judge to chair the panel, citing "the irregularity of this process". The Alberta branch of the Canadian Bar Association declined to take part, and so did the Law Society of Alberta. Retired Court of Appeal justice Brian O'Ferrall was later named chair. The panel advises. The decisions belong to the committee's MLAs. The committee's UCP members also declined to release the submissions the committee received, citing privileged information. At the committee's October 28 meeting, its UCP members voted 3–2 to end the review of the panel's report before NDP motions on it were considered, and voted down an NDP motion to disclose what the panel and its consultants were paid (per reporting on the committee's October 28, 2026 meeting; transcript citation pending). The panel was due to report to the committee by October 22. Its report is now before the committee, but its map has not been made public.`,p5:`In May, Duane Bratt, Professor of Political Science at Mount Royal University, described the process to me as without precedent in Canada. That was wrong. Alberta did it in 1992. A deadlocked commission's work went to a committee of MLAs, PC members alone drew the map after the Opposition refused to take part, and the Court of Appeal later criticised the result.`,p6:`2026 differs from 1992 in one important way. The commission didn't deadlock. A majority signed a report, and under the Act a majority report is the commission's report. Government Motion 37 set it aside anyway.`,p7:`On the floor, the government presented its route as following the commission: "We are adopting the recommendations from the report" (Government House Leader, Hansard, April 16, 2026). The opposition called it "retaliation against the independent Electoral [Boundaries Commission]." The report itself doesn't fully support the government's claim. The majority asked the Legislature to adopt its 89-seat map. The one recommendation that proposed 91 seats came from the chair alone.`,p8:`Every step was lawful. But this time the MLAs who approve the map will also run in it. And nothing stops a future government, of any party, from citing this cycle as precedent.`,h3_1:`Recommendation 5: what the government cited`,p9:`The government justified handing the job to a committee with one recommendation in the commission's report. So that recommendation is the first thing to check when the committee's map comes out. The chair, Justice Dallas Miller, wrote Recommendation 5 alone, in an addendum to the majority report: "My majority colleagues do not agree with me on this point. That is why I am alone in making this recommendation" (final report, p. 66). He also stated its purpose: it "is formulated for the express purpose of dissuading the Legislature from accepting the minority report."`,p10:`It's a fallback, and a specific one. If the Legislature wouldn't accept the majority's choice to remove two divisions outside Edmonton and Calgary, the chair asked it to amend the <em>Electoral Divisions Act</em> from 89 seats to 91, restore those two divisions, and keep "the rest of the province as we propose" (the majority map) "to the extent possible." Restoring the two divisions should:`,li3:`<strong>(a) Leave Airdrie and the south alone.</strong> No change to any division in Airdrie, or with any land south of Airdrie's southern city limit, except Drumheller-Stettler. On the majority map that is 41 divisions: both Airdrie seats, all 28 Calgary seats, and the 11 divisions around and south of Calgary.`,li4:`<strong>(b) Leave north Edmonton alone.</strong> No change to any Edmonton division north of the North Saskatchewan River: 11 divisions on the majority map.`,li5:`<strong>(c) Put south Edmonton back.</strong> Every Edmonton division south of the river returns to the commission's October 2025 interim map, the draft it published for comment before the final split. The committee may add Nisku to Edmonton-South East if it wants Leduc and Beaumont back in one division. That is 10 divisions.`,li6:`<strong>(d) Consider a Clearwater seat.</strong> Consider restoring a division made mostly of Clearwater County and western Mountain View County, with s.15(2) status. This is the only restored seat the recommendation places. It names no place for the second.`,p11:`Together, the conditions rule out most of the ground the commission split over. Airdrie, Calgary, Cochrane and Chestermere, home to the four-way Airdrie split and the Calgary-edge hybrids, all fall under condition (a). Red Deer and St. Albert are covered only by the softer clause, "to the extent possible." A map that reopens Airdrie or Calgary may still be lawful. But it isn't the map Recommendation 5 describes. Government Motion 37 itself reportedly lets the panel apply the recommendation "subject to any modifications the independent advisory panel considers necessary." The <a href="__BASE__/explorer">map explorer</a> outlines all four areas, and each one's pin says whether Recommendation 5 changes it or leaves it alone.`},know:{h:`How we know`,h3_1:`How the neutral maps were drawn`,p1:`A computer drew 1,010,000 legal Alberta maps from the official Elections Alberta files, each with its districts inside the population band and in one piece. The method, ReCom, is the standard one in this field. It merges two neighbouring districts, splits the result at random into two new legal ones, and repeats. The computer never sees a vote. That is what makes these maps neutral. Where a real map's numbers fall among the million shows how unusual it is.`,p2:`My commitments are filed on the Open Science Framework. The random seeds were locked to a public beacon before the official map files existed, and <a href="__BASE__/methods">the Methods page</a> labels each finding pre-registered or exploratory.`,h3_2:`In Alberta, neutral is not 50/50`,p3:`Rural UCP voters win their ridings by wide margins, like 60-40, and those margins waste a lot of extra votes. Urban NDP voters win theirs by closer margins, like 51-49. So when the vote splits dead even, the median neutral map gives the UCP only 44.8% of seats. That is the baseline both maps are measured against.`,h3_3:`The results, side by side`,table1_h1:`Test`,table1_h2:`Majority map`,table1_h3:`Minority map`,table1_r1c1:`Follows municipal lines (Canadian norm 70–85%)`,table1_r1c2:`80%: within norm`,table1_r1c3:`72%: within norm`,table1_r2c1:`Population spread from ideal size (commission tables)`,table1_r2c2:`3,180`,table1_r2c3:`4,707: 48% wider`,table1_r3c1:`NE/central Calgary districts above provincial average`,table1_r3c2:`2.8%`,table1_r3c3:`11.5%`,table1_r4c1:`Boundaries flagged by the commission's chair`,table1_r4c2:`0`,table1_r4c3:`3`,table1_r5c1:`Airdrie split (legal minimum: 2)`,table1_r5c2:`2 pieces`,table1_r5c3:`4 pieces`,table1_r6c1:`<strong>Pre-registered structural summary</strong> (4 of 5 or more = outlier)`,table1_r6c2:`<strong>0 of 5</strong>`,table1_r6c3:`<strong>4 of 5</strong> (the fifth, anchoring, is neutral for both maps)`,table1_r7c1:`UCP seat share at a tied vote (neutral median 44.8%)`,table1_r7c2:`46.1% (78th percentile)`,table1_r7c3:`51.7% (99.99th percentile; 69 of 1,010,000 exceed it)`,table1_r8c1:`Mean-median gap`,table1_r8c2:`1st percentile: an outlier, but leaning the NDP's way, the wrong direction to help the UCP`,table1_r8c3:`deeper in the tail than 99.97% of neutral maps, leaning the UCP's way`,table1_r9c1:`Declination (a second lopsidedness measure)`,table1_r9c2:`22nd percentile: inside the normal range`,table1_r9c3:`deeper in the tail than 98.8%, leaning the UCP's way`,table1_r10c1:`Efficiency gap (pre-set line about +4.1%)`,table1_r10c2:`+0.1% (16th percentile)`,table1_r10c3:`+4.0% (94.5th percentile): a miss`,table1_r11c1:`UCP seats on 2023 votes`,table1_r11c2:`55 of 89`,table1_r11c3:`60 of 89`,table1_r12c1:`Odds of this profile under neutral drawing`,table1_r12c2:`n/a`,table1_r12c3:`at most about 1 in 568,000`,p4:`The structural tests use geometry only. All five were pre-registered on April 24, 2026, before the final simulation results were compiled. The 2019 enacted map sits beside the majority, at a 46.0% tied-vote seat share (78th percentile).`,fig_caption:`Partisan skew runs left to right; failed structural tests run bottom to top. The 2019 map and the 2026 majority map sit in the safe corner. The minority map sits alone, out in the outlier region.`,h3_4:`What "1 in 568,000" means`,p5:`The chance that a neutral process produces the minority map's combined profile across the four fairness measures is at most about 1 in 568,000 (p ≤ 1.76×10⁻⁶, a Bonferroni-corrected, dependence-robust upper bound). I looked in two places, so I doubled the raw figure. The real chance is at most this, and probably smaller.`,p6:`That figure isn't the probability that the map is innocent. Treating it that way is the prosecutor's fallacy. A map this rare can still come from unusual but honest judgment. My claim is only that ordinary drafting variation isn't a plausible explanation.`,h3_5:`Checking with a second method`,p7:`I swapped the simulation's engine for a structurally different one, a spanning-forest sampler registered in advance at OSF (he53s) and run on 2026-07-10. Every metric's percentile moved by less than one point. A separate implementation, the R redist package, also found zero plans reaching the minority's value.`,h3_6:`Limits of the simulation`,p8:`The simulation enforces population and contiguity, keeping each district in a single piece, but not every rule the commission weighed (s.15(2), community of interest, municipal anchoring). It's a strong outside check, not a list of every map a lawful commission might draw. So the geometry tests, which don't use the simulation, carry most of the weight. The tied-vote test isolates what a map contributes on its own. A big enough swing in a real election can still outweigh any map's lean.`,h3_7:`What didn't hold up`,p9:`Some tests came back against my findings. They stay on the page.`,li1:`<strong>The anchoring test came back neutral.</strong> The minority map follows municipal lines 72% of the time and the majority 80%. Both sit inside the 70–85% Canadian norm.`,li2:`<strong>The efficiency gap missed.</strong> The minority came in at +4.0%, the 94.5th percentile. The pre-registered line was the 95th (about +4.1%), so I report it as a miss.`,li3:`<strong>The mechanism test failed.</strong> I tested whether the flagged shapes produce the seat advantage. On my test, they don't. The shapes and the seat numbers point at the same map, but the link between them didn't hold up.`,li4:`<strong>The minority passed one test outright.</strong> On neighbour-drain, which looks for packed districts next to thin-margin ones, it shows 1 coupled signal, against the majority's 2 and the 2019 map's 5.`,li5:`<strong>I retired two statistics.</strong> The Swing-Zone Allocation Test fell from p = 0.0024 to p ≈ 0.19 once corrected for neighbouring areas voting alike. I retired it on 2026-06-13. The one-in-fifteen-million headline combined two channels that weren't independent. I retired it on 2026-06-10.`,h3_8:`Both sides tested`,p10:`I ran every written accusation from either side through the same tests. None of these checks was set up in advance, so they carry less weight than the five structural tests. Every number behind them is public.`,table2_h1:`The accusation`,table2_h2:`Who made it`,table2_h3:`What I found`,table2_r1c1:`Three of the minority's boundaries are geometrically anomalous`,table2_r1c2:`The chair (majority report)`,table2_r1c3:`Largely confirmed: my blind tests independently confirmed three of the chair's four geometric flags; the fourth fell below threshold`,table2_r2c1:`The minority's changes in five places had "no public support"`,table2_r2c2:`The majority (final report, pp. 59, 62)`,table2_r2c3:`Overbroad: right on three of five, wrong on one, partially wrong on one`,table2_r3c1:`The park extension was "a bad faith effort" to claim s.15(2) protection`,table2_r3c2:`The chair (final report, p. 10)`,table2_r3c3:`Undercut: the division qualifies under s.15(2) even without the flagged extension`,table2_r4c1:`The majority "delete[s] or mangle[s] rural electoral divisions"`,table2_r4c2:`The minority (p. 356)`,table2_r4c3:`Reversed: the minority keeps fewer rural-anchored divisions (23 vs 28, against 2019's 31) and absorbs more into city-named districts (7 vs 3)`,table2_r5c1:`The majority "decline[d] to use" the ±25% flexibility in rural Alberta`,table2_r5c2:`The minority (p. 356)`,table2_r5c3:`Supported: majority rural divisions average −6.0% deviation (4 below −10%); the minority's average −12.2% (11 below −10%)`,table2_r6c1:`"Substantial and consistent testimony" for hybrids was ignored`,table2_r6c2:`The minority (p. 356)`,table2_r6c3:`Overbroad: support was configuration-specific, documented for three of seven hybrid configurations and absent for three`,table2_r7c1:`The majority's rural districts are engineered corridors of isolation`,table2_r7c2:`My own counter-hypothesis (T3.2)`,table2_r7c3:`Not supported: the geographic explanation held, and the majority cleared`,p11:`The minority's published reasons for its contested lines mostly fail on public data: five of six don't survive an independent check. Usually the general claim is true and the specific line isn't. About a third of Cochrane's workers commute somewhere in Calgary. That says nothing about the Nolan Hill neighbourhood the corridor reaches. The majority published no such list, so this check only runs one way. Taken together, the minority's two charges against the majority describe two different approaches. More but fuller rural divisions on the majority map. Fewer but lighter ones on the minority map.`,h3_9:`Who did this`,p12:`I'm the only author, a self-funded student at Mount Royal University, and I've voted for and donated to both conservative and progressive provincial parties (more under About me). Findings that went against what I expected stay on the record, and every number can be reproduced from public code, public data and random seeds committed in public before the analysis ran.`,h3_10:`The full record`,p13:`All fourteen findings are on <a href="__BASE__/evidence">the full record</a>, each with its numbers, what it could show, what Canadian practice expects and what the law does with it. Each one links to a short explainer on <a href="__BASE__/explainers">the explainers page</a>.`},test:{h:`The November test`,p1:`The committee's 91-seat map is due November 2, 2026. I registered the November tests (OSF registration qsgy8) before the committee's map existed. I'll publish the scores within 72 hours of the map's release, whichever way they point.`,p2:`<strong>The process.</strong> Were public hearings held? Was a draft released? Are the advisory panel's members and terms of reference published? Is the record behind the map public? The committee has kept its submissions private, so I can only score the reasons for its lines from what its report publishes. The process also gets its own nine-feature scorecard, published in draft on <a href="__BASE__/norms#measurable">the norms page</a>. Four of the committee's failing cells are features it can still add before it reports.`,p3:`<strong>Recommendation 5.</strong> Test X1 scores the committee's map against the chair's four conditions, one at a time:`,li1:`(a), (b) and (c) pass if the map leaves those divisions as described.`,li2:`(d) asks only that a Clearwater seat be considered, so it's scored on evidenced consideration. It passes if the map contains the division, or if the committee's published report names the option and gives a reason for adopting or declining it. With the submissions withheld, the report is the only record that counts. Silence or boilerplate fails.`,p4:`X1 passes only if all four do. I'll also report a strict reading, which fails (d) unless the seat exists. Recommendation 5 binds no one in law. What X1 tests is whether the committee delivered what the government cited.`,p5:`<strong>The map.</strong> Where does it land on every measure on this page, against the same million-map distribution and under the same pre-registered thresholds?`,p6:`<strong>What each outcome means.</strong> If the committee's map repeats the minority map's pattern, drawn by different people, under different constraints, on a different timeline, the structural finding becomes confirmatory. If it lands inside the neutral bands, the finding stays an isolated observation about one map that was never enacted, and I'll say so here. Either way, the arithmetic is public. You can check it yourself.`},mind:{h:`What would change my mind`,p1:`Every finding has a condition, written in advance, that would retract it. If one is met, I'll publish the retraction within 30 days.`,li1:`<strong>Someone draws a better-justified map.</strong> If anyone produces a legal Alberta map that satisfies the minority's own stated reasons for Airdrie, Cochrane, Nolan Hill and Rocky Mountain House–Banff Park, and follows municipal lines about as often as the majority's, I'll retract the finding that those boundaries can't be explained by their stated reasons. The challenge is open at <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/issues/14" rel="noopener">Issue #14</a>.`,li2:`<strong>A document shows the reasons came first.</strong> If an internal commission document, dated before the minority's final choices, shows those choices were driven by community submissions I haven't seen, I'll retract the inference that they were drafting decisions.`,li3:`<strong>The neighbour-drain pass turns out to be an artefact.</strong> If the continuous version of that score falls in the extreme upper tail (p < 0.05) of random permutations, I'll withdraw the minority's pass.`,li4:`<strong>An election contradicts the simulation.</strong> If the 2027 election is fought on either commission map and the actual seat split contradicts the projection from 2023 votes, I'll revisit the simulation's percentile findings against the actual results.`,li5:`<strong>A court distinguishes <em>Lalande</em>.</strong> In <em>Quebec (AG) v. Lalande</em>, 2026 SCC 13, the Supreme Court struck down Quebec's law pausing its commission, and Quebec then legislated its own map. If a court reviewing Alberta's route finds it constitutionally different, for example because handing a finished commission's work to an MLA committee isn't the same as freezing a commission mid-process, I'll retract the argument on <a href="__BASE__/norms">the norms page</a> that the two belong in the same class.`,p2:`The November map can also weaken the overall conclusion, as described above. I correct mistakes in public. I don't delete them. Every correction is listed in the <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">academic report's Documented Corrections section</a>.`},authors:{h:`The author's view`,p1:`Everything above is the audit. This section is my opinion. Delete it and no number on this page changes.`,p2:`Two facts are hard to explain innocently. The commissioners the government nominated drew a map that neutral map-drawing almost never produces: fewer than a hundred matches in a million draws. And when the commission split instead of endorsing that map, the government didn't ask why. It moved the job to a committee its own MLAs control.`,p3:`Each fact has an innocent explanation. A commissioner can be eccentric in good faith, and a legislature can lose patience with a split commission. Put the two facts in order, though, and the innocent explanations get harder to hold: a government wanted a certain kind of map, the independent process didn't produce one, and a different process was set up.`,p4:`What worries me is that no law was broken. I checked, and that checking is most of what this audit is. The Act makes the commission's report advisory. It sets no notice period, and requires no draft, hearings or consultation before the Legislature acts. The protection was a convention, not a law, and a convention binds only a government that chooses to follow it. Alberta went through this in 1992, and in 1995 it changed how commissions are appointed.`,p5:`The committee that replaced the commission has six MLAs, four from the government and two from the opposition, with a government MLA as chair. It has an advisory panel, chaired by a retired judge who was appointed after the province's acting chief justice declined to help find one. The panel only advises. The MLAs vote, and they will run in the districts they approve. The map won't have a public hearing before it's final.`,p6:`This government has done this kind of thing before. Its first bill, as written, would have let cabinet rewrite laws without the Legislature, and that power was removed only after public outcry. Its own ethics commissioner found the Premier breached the conflicts law by pressing her attorney general about a criminal case. It passed a law letting cabinet repeal local bylaws and trigger the removal of elected councillors. When a court paused one of its laws in December 2025, it invoked the notwithstanding clause. Each of those moves was lawful, and each set aside a convention to get past an independent check.`,p7:`I also worry about what the map buys. Replay the 2023 election-day vote and the minority map gives the UCP sixty seats of eighty-nine. Sixty seats would protect a government from floor-crossings, and from an opposition large enough to keep up scrutiny in committee. I'd worry about that in anyone's hands.`,p8:`I could be wrong, and I've set out how you'd know. The committee's map is due November 2, and I registered the tests before it existed. If it lands inside the neutral range, my suspicion has taken real damage, and this site will say so within 72 hours. I committed to that before I knew the answer.`,signed:`— Will Conner`},fixes:{h:`Fixes for next time`,p1:`Two problems make every audit of Alberta's maps harder than it needs to be. First, about half of all votes now come in before election day, and Elections Alberta reports them by division rather than by voting area. So roughly 395,000 NDP and UCP votes cast in 2023 can't be placed on a map. Second, commissions draw from census data that's already years old by the time a map takes effect. Both problems can be fixed. <a href="__BASE__/fixes">The proposals page</a> explains how.`}},fixes:{page_title:`Fixes for next time · Alberta Electoral Boundary Audit`,h1:`Fixes for next time`,meta:`Plain-language companion · what would make the next map easier to check`,back:`← Back to the audit`},evidence:{page_title:`The full record · Alberta Electoral Boundary Audit`,h1:`The full record`,meta:`Plain-language companion · the fourteen findings in full`,intro:`Every finding behind the main page, in full: what was found, what it could show, what Canadian practice expects, and its limits, including what the law does with it. The findings that ran against the audit stay right beside the ones that support it.`,back:`← Back to the audit`,group_map:`On the map`,group_sim:`In the simulation`,group_conduct:`In the conduct`,beat_found:`What we found`,beat_show:`What it could show`,beat_context:`Context`,beat_canada:`What Canadian practice expects`,beat_law:`Limits and the law`,explainer:`Explainer`,e1:`Airdrie: one city of 85,805, four districts`,e2:`The three boundaries the chair called out`,e3:`North-east and central Calgary: larger districts where the NDP is strongest`,e4:`Worse at the one thing the law actually measures`,e5:`Municipal anchoring: both maps inside the norm`,e6:`Fewer than 100 maps in 1,010,000`,e7:`The test that missed`,e8:`One in 568,000, and what that number is not`,e9:`We tried to knock down our own result`,e10:`The signals that pointed the other way`,e11:`Five of six reasons don’t survive checking`,e12:`The commission that couldn’t sign one map`,e13:`When the process might have answered, it was replaced`,e14:`The independent-commission norm, set aside, and the time it happened before`},body:{section_link_aria:`Link to section`,the_map:{heading:`1: The Map`,heading2:`The map on the cover`,p1:`The cover map is the best single image in this audit. Here is how to read it.`,p2:`Alberta is divided into 4,765 Voting Areas — small geographic zones Elections Alberta uses to count polling-station ballots. Each one is coloured by how people in it actually voted in 2023: orange where NDP votes are concentrated, blue where UCP votes are concentrated. But the colour only becomes dark and saturated where a lot of people live. A Voting Area that covers hundreds of square kilometres of parkland or farmland stays pale — nearly invisible. The map lights up where people are, and fades where they aren't.`,p3:`This is very different from the Alberta you see on election night. Most election maps colour entire ridings solid blue or orange based on who won. Rural ridings are geographically large and the UCP wins most of them, so election-night Alberta looks like a wall of blue with small orange pockets in Edmonton and Calgary. The cover map uses the same votes and the same geography — but shows them weighted by where people actually live. What appears is a province where most of the population is concentrated in a dense arc of cities, and those cities vote very differently from the rural map that normally represents them.`,p4:`The boundary lines drawn over the colour are the minority commission's 89 proposed electoral districts — the map this audit ends up critiquing. The audit's work is to ask what those lines do to the people underneath them.`,p5:`This image is what makes the stakes plain. A province that looks like it votes one way on a standard map is actually a province where most of the people live in areas that vote the other way. Once the population is visible underneath the boundary choices, those choices stop looking random.`},preliminary:{badge:`PRELIMINARY`,heading:`Preliminary findings — pending independent expert review`,body:`Independent subject-matter experts are reviewing the statistical tests in this section before final publication. The full results sit below, open to that scrutiny.`},structural_results:{heading:`Structural audit results — before any statistics:`,body:`The majority map crosses <strong>zero of five</strong> pre-registered structural thresholds. The minority map crosses <strong>four of the five</strong>; the fifth (anchoring) is neutral — both maps fall within the 70–85% Canadian norm. These are geometric measurements — population spread, <button class="vocab-term" data-def="how closely a district's borders follow pre-existing city and municipal limits, rather than cutting through them" aria-expanded="false">municipal anchoring</button>, Airdrie split count, NE/central Calgary population excess, and the seven boundary configurations Commission Chair Justice Miller himself flagged in writing (majority report, pp. 59 and 62–63) — requiring no election data and no statistical sampler. The next section tests both maps against 1,010,000 computer-drawn neutral maps and reaches the same conclusion through a completely different instrument. Two independent instruments — geometric and statistical — converge, and both land on the regions the commission chair criticized in writing.`},clean:{heading:`6: When a fair-looking map isn't`,legal_label:`A NOTE ON LEGAL TERMINOLOGY`,legal_body:`"Gerrymandering" has no legal definition in Canadian law. The word is used throughout this report in its everyday political sense — manipulating electoral boundaries for partisan advantage. The legal tests actually applying in Canada are different: whether boundaries provide "effective representation" under s.3 of the <em>Charter of Rights and Freedoms</em> (the constitutional standard the Supreme Court of Canada set in the 1991 <em>Saskatchewan Reference</em>), and whether the commission followed the rules of Alberta's <em>Electoral Boundaries Commission Act</em>. The audit's findings are evidence bearing on those legal questions. They are not proof of a legally-defined wrong, and this report does not describe them in those terms.`,intro_p1:`The cleanest single question to ask of any electoral map is this: if the province's vote split exactly evenly between the two main parties, what seat count would the map produce? This holds the electorate constant and asks the map alone what it does.`,intro_p2:`To answer this, the audit generated 1,010,000 computer-drawn, mathematically neutral Alberta maps. The simulation used the official Elections Alberta shapefiles on the commission's geography, holding every plan to the same population-balance (±25%) and contiguity requirements — the two criteria the algorithm enforces, not every statutory factor (it does not, for example, enforce communities of interest), so the comparison set is best read as population-and-contiguity-neutral rather than fully statute-compliant. The commission's two 2026 maps were then placed into that distribution to see how normal they are. The simulation ran four independent chains of 252,500 steps each, with the base seed drawn from the Cloudflare drand beacon and pre-registered at OSF before execution.`,howmcmc_label:`HOW THE SIMULATION WORKS`,howmcmc_mcmc:`Merge two neighbouring districts, split the blob back into two new legal ones at random, repeat a million times, saving the map each step. That is the whole machine. The step-by-step walkthrough — and every other test on this page, in plain language — is on <a href="__BASE__/methods">the Methods page</a>.`,howmcmc_recom:`The algorithm is called ReCom — the standard tool of the field — and it preserves the two hard legal rules (population balance, contiguity) by construction.`,prereg_label:`PRE-REGISTRATION`,prereg_body:`Pre-registration means writing the tests, thresholds, and predicted directions down in a public, time-stamped record before looking at the data — so a threshold cannot be quietly moved after the answer arrives. This audit's commitments are filed on the Open Science Framework, its random seeds were locked to a public beacon before the official map files existed, and each finding is labelled pre-registered or exploratory accordingly. The full accounting of which is which is on <a href='__BASE__/methods'>the Methods page</a>.`,neutral_p:`In Alberta, the neutral answer is not 50/50. <em>Across 1,010,000 computer-drawn legal Alberta maps, the median map gives the UCP only 44.8% of the seats at 50/50 votes</em> — a typical Alberta map under neutral votes hands the NDP a small seat majority. This is counterintuitive but mechanical: rural UCP voters win their ridings by 60-40 margins (wasting many "extra" UCP votes), while urban NDP voters win their ridings by tighter 51-49 margins (wasting fewer NDP votes per win). At neutrality, NDP comes out ahead on seat efficiency.`,full_dist:`The full distribution from the canonical 1,010,000-map simulation:`,t1_col_a:`Where the map sits`,t1_col_b:`UCP seats at 50/50 votes`,t1_r1_a:`Median Alberta map`,t1_r1_b:`44.8% — NDP slight seat majority`,t1_r2_a:`95th-percentile map`,t1_r2_b:`47.1%`,t1_r3_a:`99th-percentile map`,t1_r3_b:`48.4%`,t1_r4_a:`<strong>Maximum across 1,010,000 maps</strong>`,t1_r4_b:`<strong>51.72% (69 of 1,010,000 plans exceed the minority's 51.69%)</strong>`,seat_count_note:`A note on seat counts. The 2026 commission maps each have <strong>89</strong> districts; the audit's computer simulation runs on the <strong>87</strong>-district 2019 map (its starting substrate); the November Lunty committee will produce <strong>91</strong>. All percentages are seat <em>shares</em>, comparable across these denominators. The simulation uses the 2019 map as its starting point because the ReCom algorithm needs a legally enacted map to propose swaps from — the 2019 map is the last enacted Alberta electoral map. Using either commission proposal as the substrate would be circular: we would be measuring whether a map is extreme compared to maps derived from itself.`,pattern_intro:`The results — placing the three real maps in this distribution — point to a specific, surgical pattern of boundary drawing.`,sub1_h:`All four statistical measures fire simultaneously`,sub1_p:`When the official Elections Alberta shapefiles are used, the minority map is a statistical outlier on every partisan-fairness metric — not just the tipping-point one.`,t2_col_a:`Map`,t2_col_b:`Efficiency gap`,t2_col_c:`Mean-median`,t2_col_d:`<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener" title="Declination measures the angular difference between the seats-votes curve for each party. Negative values favour the NDP; positive favour the UCP.">Declination</a>`,t2_col_e:`Seats at 50/50`,t2_r1_a:`Majority 2026`,t2_r1_b:`+0.1% (p16.5)`,t2_r1_c:`−3.6% (p1)`,t2_r1_d:`−0.027 (p21.8)`,t2_r1_e:`46.1% (p78.5)`,t2_r2_a:`Minority 2026`,t2_r2_b:`<strong>+4.0% (p94.5)</strong>`,t2_r2_c:`<strong>+1.0% (p99.97)</strong>`,t2_r2_d:`<strong>+0.077 (p98.8)</strong>`,t2_r2_e:`<strong>51.7% (p99.99)</strong>`,sub1_close:`The majority map sits comfortably inside the normal range on three of four metrics. Its mean-median sits at p1 (= p0.99) in the NDP-favourable direction — an unusual result but pointing the wrong way to help the UCP. The majority map's close adherence to municipal boundaries places NDP-heavy urban cores into their own compact districts, where NDP votes win by efficient margins while UCP rural wins tend to be by larger margins; this mild structural NDP efficiency advantage is what shows up in the mean-median measure. The minority map is in the tail on all four, each pointing in the same partisan direction.`,sub2_h:`The 50/50 tipping point: fewer than 100 of 1,010,000 neutral maps reach it`,sub2_p:`The tipping-point metric introduced above — UCP seats at a 50/50 provincial vote — is the most intuitive way to compare the three maps.`,t3_col_a:`Map`,t3_col_b:`UCP seats at 50/50 votes`,t3_col_c:`Where it sits`,t3_r1_a:`2019 enacted`,t3_r1_b:`46.0%`,t3_r1_c:`78th percentile — inside the normal range`,t3_r2_a:`<strong>Majority 2026</strong>`,t3_r2_b:`<strong>46.1%</strong>`,t3_r2_c:`<strong>78th percentile — well within bounds</strong>`,t3_r3_a:`<strong>Minority 2026</strong>`,t3_r3_b:`<strong>51.7% (46 seats)</strong>`,t3_r3_c:`<strong>99.99th percentile — fewer than 100 of 1,010,000 neutral draws reach this</strong>`,sub2_close:`Fewer than 100 of 1,010,000 computer-drawn neutral Alberta maps produced a <code>seats@50/50</code> value as high as the minority proposal's. Based on actual recent voting patterns, it would award the UCP 60 seats (compared to 55 in the majority proposal). The majority proposal is the kind of map a neutral procedure routinely generates. The minority proposal is the kind of map you have to specifically aim to draw.`,sub3_h:`What this means in plain language`,sub3_p:`The minority proposal sits in the extreme tail of the 1,010,000-plan ensemble on three of four partisan-fairness metrics, with the fourth (efficiency gap, +4.0%) at the 94.5th percentile — <em>near, but below</em>, the audit's pre-registered Alberta-calibrated threshold of the 95th. The two joint-test channels share underlying efficiency-gap data and are not statistically independent, so combining their p-values under Fisher's method overstates significance. The defensible upper bound from a dependence-robust combination is roughly <strong>one in 568,000</strong> (Bonferroni; p&nbsp;≤&nbsp;1.76×10<sup>−6</sup>). That remains an extreme result, well beyond conventional significance thresholds — but it is reported as a bound, not as four independent instruments reading in agreement.`,details_summary:`What this p-value means — and what it doesn't`,details_p1:`A p-value answers one question: if the map were drawn by a neutral process, how often would we see a result this extreme or more extreme? At the dependence-robust bound p&nbsp;≤&nbsp;1.76×10<sup>−6</sup>, the answer is at most about once in 568,000 trials.`,details_p2:`This is a frequentist hypothesis test, not a measurement of intent. It does not say the commission intended to gerrymander, and it does not quantify how unfair the map is in practical terms. It says the boundary pattern is statistically inconsistent with the ReCom neutral-drawing reference distribution — a strong external check, but not a perfect one (it does not enforce every statutory criterion the commission worked under, e.g., s.15(2) tiers and community-of-interest constraints).`,details_p3:`The structural test battery (population, splits, anchoring, compactness, signatures) was registered with timestamps before canonical recomputation (<a href="https://osf.io/w2s8k" rel="noopener">OSF registration w2s8k</a>). The partisan-bias channels (joint Mahalanobis, SZAT, Fisher/Bonferroni combination) are labelled "exploratory" in the audit's own §4.3.1 sense: documented in the repository, but not pre-data. The audit reports each channel separately and combines them under the dependence-robust bound rather than presenting them as fully independent confirmatory tests.`,szat_label:`SWING-ZONE ALLOCATION TEST (SZAT)`,szat_body:`SZAT was designed as a second analytical channel: instead of asking "is this map extreme overall?" it asks "are the specific line choices partisan-neutral?" It works by isolating only the Voting Areas where the minority's map differs from the majority's — the contested re-draws — and testing whether those particular choices, taken together, shift vote efficiency in one party's direction. Because it compares only the points of departure, it automatically controls for everything the two maps share: the same geography, population targets, and statutory rules. Under a standard permutation test SZAT returned p=0.0024; under a block-permutation null that corrects for spatial autocorrelation across adjacent Voting Areas, it returned p≈0.19 — not significant. SZAT is retained as exploratory context but does not survive as a confirmatory channel. The headline rests on the simulation alone. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Technical details →</a>`,two_q:`<strong>The SZAT result.</strong> The 1,010,000-map simulation asks: <em>is this map extreme compared to neutral maps drawn on the same Alberta geography?</em> A second test — the <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/szat_summary.json" rel="noopener">Swing-Zone Allocation Test</a> — asked a different question: <em>are the specific lines on the map partisan-neutral?</em> It works by looking only at the Voting Areas where the minority drew differently from the majority and asking whether those particular choices, taken together, shifted vote efficiency in one party's direction. Under standard permutation it returned p=0.0024. Under a block-permutation null — which corrects for spatial autocorrelation among adjacent Voting Areas — it returned p≈0.19. The block-permutation result does not reach significance. The audit therefore reports the simulation result alone as the headline: a dependence-robust upper bound of <strong>1 in 568,000</strong> (p&nbsp;≤&nbsp;1.76×10<sup>−6</sup>), not a Fisher combination of two independent channels.`,super_lead:`In an 89-seat legislature, a two-thirds supermajority requires exactly 60 seats. The minority proposal’s tied-vote seat share of 51.7% — a level only 69 of the 1,010,000 neutral maps reach — sits in the regime where a UCP supermajority becomes statistically reachable on Alberta’s 2023 geography. But the simulation does not enforce every statutory criterion the commission worked under, so this is a strong external check, not proof that no legally compliant Alberta map could reach this seat count. Act I’s structural evidence, which does not depend on the simulation at all, carries most of the weight; the tied-vote tail position is the supporting context.`,super_label:`WHY A LARGE MAJORITY MATTERS`,super_body:`Under Canada's Westminster system, Alberta's Assembly has no two-thirds threshold that unlocks special powers: a governing majority — even a bare one — can already pass laws and budgets, invoke "closure" to end debate, change the rules of the House, and set the membership of every committee. What a very large majority changes is margin and durability, not the menu of powers. A government holding 60 of 89 seats is effectively immune to internal dissent — a handful of floor-crossings cannot threaten it — and faces an opposition too small to force recorded divisions or sustain committee scrutiny. The concern here is the concentration of seats and the thinning of effective opposition, not a procedural threshold being crossed.`,super_close:`The urban-hybridization pattern identified in Act I — urban voters distributed into surrounding rural-edge districts — is consistent with the 60-seat outcome, though the audit’s direct test of whether that geometry is the specific mechanism came back negative and is reported as a failure (Casing 9). The structural and statistical findings converge on the same proposal and the same communities — and they agree on who benefits.`,sub4_h:`Confirmation from the targeted-procedure test`,sub4_p:`To be sure this isn't a quirk of the neutral simulation's known compactness preference, the audit ran a targeted hill-climbing procedure (<a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">Cannon et al. 2022 — cited and described in the technical report</a>) in both directions: maximising UCP seats and maximising NDP seats. Same number of steps (40,000) in each direction, same statutory constraints, same provincial geometry.`,t4_col_a:`Procedure`,t4_col_b:`Most-extreme value reached`,t4_col_c:`What it tells us`,t4_r1_a:`Neutral MCMC, max produced`,t4_r1_b:`51.72% UCP seats @ 50/50 (69 of 1,010,000 plans exceed the minority's 51.69%)`,t4_r1_c:`The natural ceiling under neutral drawing`,t4_r2_a:`Neutral MCMC, min produced`,t4_r2_b:`~39% UCP seats @ 50/50`,t4_r2_c:`The natural floor under neutral drawing`,t4_r3_a:`Targeted hill-climb, UCP-maximizing`,t4_r3_b:`<strong>52.9%</strong>`,t4_r3_c:`What a procedure deliberately aiming for UCP advantage can reach`,t4_r4_a:`Targeted hill-climb, NDP-maximizing`,t4_r4_b:`<strong>37.9%</strong>`,t4_r4_c:`What a procedure deliberately aiming for NDP advantage can reach (below the neutral floor)`,sub4_close:`The minority map's 51.7% sits closer to the targeted-UCP ceiling (52.9%) than to the neutral median (44.8%). The majority map's 46.1% sits much nearer the neutral median, at the 78th percentile. Both the 2019 enacted map and the 2026 majority fall comfortably within what neutral procedure routinely produces — different vote shares, same zone of unremarkable outcomes. The majority continues 2019 Alberta practice on the partisan-fairness axis the same way it continues 2019 practice on municipal anchoring (80.0% vs 2019's 75.1%). Two maps drawn under the same Alberta rules, by the same five commissioners, in the same room: one lands where neutral procedures routinely produce, the other lands where you have to specifically aim to land.`,sub4_quote:`<em>This</em> is the shape of the finding, and it is also the framing a court would actually apply.`,sub5_h:`Ruling Out Alternative Explanations`,sub5_p:`When presented with a statistical outlier of this magnitude, a rigorous audit must test the standard innocent explanations before treating the pattern as unexplained. The structural data (Lane 2) weighs against each of the standard alternative explanations:`,defense1:`<strong>The "Natural Political Geography" Defense:</strong> <em>("Urban voters are naturally packed; the map just reflects Alberta's geography.")</em> The 1,010,000 simulations already account for Alberta's natural geography. Geography does give the UCP a baseline efficiency advantage — but the two real comparison maps show where that advantage naturally tops out: both the 2019 enacted map and the 2026 majority sit at the 78th percentile on the tipping-point metric, and the 2019 map's highest placement on any partisan measure is the low 90s (declination, 91st percentile). The minority map sits at the 99.99th percentile — an extreme outlier <em>even when compared to Alberta's naturally skewed baseline</em>.`,defense2:`<strong>The "Communities of Interest" Defense:</strong> <em>("The odd shapes were drawn to keep specific communities together.")</em> If you are trying to keep communities together, you follow municipal borders. The majority map followed existing city limits 80% of the time. The minority map followed them 72% of the time — both within the 70–85% Canadian norm. What the minority map does do is actively split the unified city of Airdrie into four separate pieces, and place three of its boundary decisions precisely in the urban-edge zones the commission chair flagged as geometrically anomalous — choices not explainable by community-of-interest logic.`,defense3:`<strong>The "Population Equality" Defense:</strong> <em>("They had to draw weird boundaries to make sure every district had the exact same population.")</em> On the commission's own population tables the minority map is <em>worse</em> at population equality: its Population Mean Absolute Deviation (MAD) was 4,707, 48% wider than the majority map's 3,180. On 2021 census numbers the two maps' mean deviations are almost the same, and the minority's median deviation is wider (3,938 against 2,827). That median spread sits at the 99th percentile of neutral maps balanced to within ±12.5%, but at the bottom of the range when neutral maps may use the statute's full ±25%.`,defense4:`<strong>The "Incompetence or Bad Luck" Defense:</strong> <em>("They just drew a sloppy map and got unlucky with the numbers.")</em> Hitting a 60-seat supermajority configuration while also splitting Airdrie into four pieces and placing three boundaries in the exact zones the commission's own chair flagged as anomalous requires precision. The joint dependence-robust upper bound on the probability of accidentally drawing a map this extreme on both analytical channels under the ReCom neutral reference distribution is roughly <strong>1 in 568,000</strong> (p&nbsp;≤&nbsp;1.76×10<sup>−6</sup>). That bound is still extreme — well beyond conventional significance — but it is reported as a bound, not as a precise single probability.`,sub5_close:`What the data shows is that the minority proposal worsened both population parity and community coherence relative to what the same five commissioners produced simultaneously under identical statutory rules. The audit does not determine what the minority commissioners intended — boundary geometry cannot reveal intent — but the structural departure from both the neutral ensemble and the majority proposal's output stands regardless of intention.`,sub6_h:`A note on the R cross-validation`,sub6_p1:`An earlier version of this audit (using approximated rather than official shapefiles) cross-validated the Python ReCom ensemble against the R <code>redist</code> package's Sequential Monte Carlo sampler. The cross-check produced unstable results: across three runs with the same nominal seed, the fraction of plans reaching the old minority value (48.3% on the approximated geometry) was 5.6%, then 28%, then 58% — a sampler-convergence failure, not a discovery. The full write-up is at <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md" rel="noopener">findings/redist_python_comparison.md</a>.`,sub6_p2:`With official Elections Alberta shapefiles, the minority map's <code>seats@50/50</code> rises to 51.7% — a value fewer than 100 of 1,010,000 neutral plans reach. The R cross-validation question becomes moot: zero plans from either sampler reach the canonical value at comparable sample sizes.`,sub6_asymm:`<strong>The asymmetry around 50/50 is more telling than the inversion itself.</strong> A precision sweep of the seat-vote curve at 0.01-percentage-point resolution finds the minority map keeps the UCP at or above the 45-seat legislative-majority threshold down to a UCP provincial vote share of about <strong>49.7%</strong>. This is technically a vote-seat inversion — the UCP would form government on the minority map while losing the popular vote by 0.3 percentage points — but 0.3 points is well within ordinary polling noise, so on its own this is not a dramatic finding. What <em>is</em> dramatic is the contrast: on the <strong>majority</strong> map, the UCP would need to <em>win</em> the popular vote by about 4 percentage points to reach the same 45-seat threshold. Both maps face the same Alberta geography and the same statutory rules; the gap between them — 0.3pp vs +4pp — is structural difference, not noise.`,sub6_close:`This is the structural-bias finding the audit holds with confidence. It is geometry-only; it does not depend on any election result; it does not move when polls do.`,sub6_caveat:`<strong>One caveat the audit takes seriously.</strong> A real electorate is not a uniform 50/50. Voters can swamp any map's structural lean with enough swing — a particularly upset or inspired electorate will tip the result regardless of how the boundaries are drawn. The 50/50 test isolates <em>the map's contribution to the outcome</em>, not the outcome itself. What it shows is what the map does when the electorate doesn't decide for it.`,sub7_h:`The bottom line`,sub7_p1:`The audit's central finding is geometric. <strong>Lane 2 — the structural-irregularity scorecard — is the foundation; Lane 1 is the proof that the geometry is doing partisan work.</strong>`,sub7_p2:`The chart below puts both lanes on a single picture. The horizontal axis is Lane 1 (the partisan-fairness efficiency gap, where further right means more UCP-favoured); the vertical axis is Lane 2 (the count of structural-fairness tests the proposal fails, out of five, where higher means more structural problems).`,stakes_fig_alt:`Scatter plot with efficiency gap on the horizontal axis and count of structural tests failed on the vertical axis. The 2019 enacted map and the majority 2026 map cluster in the safe lower-left corner. The minority 2026 map appears in the upper-right outlier region.`,stakes_fig_caption:`The two ways of measuring the two commission proposals, plotted together. Left-to-right: how skewed the proposal looks on the partisan-fairness number — the further right, the more it favours the UCP. Bottom-to-top: how many of five structural-fairness tests the proposal fails — the higher, the worse. The 2019 enacted map sits in the safe corner: low on both. The majority 2026 proposal stays flat at zero structural problems and near-zero partisan skew (+0.1%). The minority 2026 proposal is a structural outlier on every test that distinguishes the two maps (4 of 5; the fifth, anchoring, is neutral for both); its efficiency gap (+4.0%) sits just below the Alberta threshold line.`,stakes_table_intro:`The same findings in plain summary form, leading with the structural finding because the cross-validated evidence supports it most strongly:`,t5_col_b:`Structure — Act I (geometry only, no votes; the academic report’s “Lane 2”)`,t5_col_c:`Numbers — Act II (vote-dependent; “Lane 1”)`,t5_r1_a:`<strong>Majority 2026</strong>`,t5_r1_b:`clean — crosses <em>no</em> structural threshold`,t5_r1_c:`inside the normal range on every measure (tied-vote seat share 46.1%, 78th percentile; efficiency gap +0.1%)`,t5_r2_a:`<strong>Minority 2026</strong>`,t5_r2_b:`<strong>crosses 4 of 5 structural thresholds</strong> by a wide margin (anchoring neutral — both maps within Canadian norm)`,t5_r2_c:`extreme tail on three of four fairness measures — tied-vote seat share 51.7% (only 69 of 1,010,000 neutral maps reach it); two further measures past the 98.8th and 99.9th percentiles; efficiency gap +4.0% (<em>near but below</em> the pre-set line — a reported miss); combined odds under neutral drawing about 1 in 568,000`,details2_summary:`Why the structural act carries the case — technical detail`,details2_p:`The audit pre-registered five structural-irregularity tests on April 24, 2026, before the final simulation results were compiled. Anchoring is neutral for both maps; of the remaining four, the minority crosses every one and the majority crosses none. Those measurements are geometric — no statistical sampler, no vote data. <strong>This is the central finding.</strong> The simulation corroborates it: the minority sits in the extreme tail on three of four fairness measures, with the fourth (the efficiency gap) just under the pre-set line at the 94.5th percentile, and combined odds of about 1 in 568,000 under neutral drawing — the deliberately cautious ceiling explained in Casing 8. Two honesty notes live in the casings: the flagged boundary shapes themselves are <em>not</em> the direct mechanism of the seat swing — that claim failed its test and the failure is reported (Casing 9; full write-up at <a href='https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/redist_python_comparison.md' rel='noopener'>findings/redist_python_comparison.md</a>) — and the Swing-Zone Allocation Test did not survive its corrected null and is exploratory only (Casing 10). The structural act carries the case; the numbers corroborate without carrying.`},impact:{heading:`5: Effects on Representation`,lanes_label:`LANE 1 AND LANE 2`,lanes_body:`<strong>Lane 1 (numbers)</strong> uses election results to test whether the map turns votes into seats fairly: it asks how the map performs across different vote splits. <strong>Lane 2 (structure)</strong> looks only at the drawn lines — city splits, population spread, boundary shapes — and uses no election data at all. Each lane is independent: a map can fail one and pass the other. The minority proposal fails both. The majority passes both.`,intro:`Lane 1 depends on which election results you score the maps against. Lane 2 does not. Its structural evidence lives in the maps themselves: the drawn lines, the split cities, the places where boundaries follow, or don't follow, administrative lines that exist for other reasons. On these tests the two maps are not close.`,fig_alt:`Bar chart comparing four pre-registered structural-fairness tests side by side, plus a summary score panel. The majority map bars sit at zero or well inside safe ranges. Three of the five panels have a pre-registered failing line (dashed red): NE/central Calgary crowding, chair-flagged boundaries, and the summary scorecard. On those three, the minority bar crosses the line and the majority bar stays inside it. The population-spread and Airdrie panels have no failing line; population spread shows the majority at 3,180 and the minority at 4,707 people from the ideal district size. The fifth pre-registered test, municipal anchoring, was neutral for both maps — both fell within the 70–85% Canadian norm — so it is not plotted; the summary panel scores the minority 4 of 5 with anchoring counted as neutral.`,fig_caption:`The four pre-registered structural-fairness tests, side by side, plus a summary score panel. Teal bars are the majority map; purple bars are the minority map. A dashed line appears where a test has a pre-registered failing threshold: NE/central Calgary crowding, chair-flagged boundaries, and the summary scorecard. The minority bar crosses every failing line shown. The majority bar never does. The population-spread and Airdrie panels have no failing line — population spread shows the majority at 3,180 and the minority at 4,707 people from the ideal district size. The fifth pre-registered test, municipal anchoring, was neutral for both maps — both fell within the 70–85% Canadian norm — so it is not plotted here; the summary panel scores the minority 4 of 5 with anchoring counted as neutral.`,table_intro:`The same five tests as a table, each test's threshold set beside its result. The bottom row is the audit's <em>summary</em>: how many of the five tests each map fails.`,table_col_test:`Test`,table_col_majority:`Majority map`,table_col_minority:`Minority map`,table_col_direction:`Direction / Beneficiary`,table_r1_a:`Border follows existing municipal lines (70–85% Canadian norm)`,table_r1_b:`80% — within norm`,table_r1_c:`72% — within norm`,table_r1_d:`N/A — both within Canadian norm`,table_r2_a:`Population spread (tighter is better)`,table_r2_b:`3,180`,table_r2_c:`4,707 — 48% wider`,table_r2_d:`Structural (Reduces vote equality)`,table_r3_a:`NE/central Calgary population excess above average`,table_r3_b:`2.8%`,table_r3_c:`11.5%`,table_r3_d:`<strong>UCP</strong> (Packs urban NDP votes)`,table_r4_a:`Boundaries flagged by the commission's own chair`,table_r4_b:`0`,table_r4_c:`3`,table_r4_d:`N/A`,table_r5_a:`Airdrie split (constraint minimum: 2)`,table_r5_b:`2 pieces`,table_r5_c:`4 pieces`,table_r5_d:`<strong>UCP</strong> (Cracks urban/suburban power)`,table_r6_a:`<strong>Pre-registered summary</strong> (&ge; 4 of 5 = outlier)`,table_r6_b:`<strong>0 of 5 fired</strong>`,table_r6_c:`<strong>4 of 5 fired</strong> (anchoring test neutral — both maps within Canadian norm; remaining 4 tests all fire)`,table_r6_d:`<strong>UCP</strong>`,rationales_p:`A separate finding, for the minority alone: <strong>five of six of the minority commissioners' published rationales fail under independent check</strong>. The test runs against the minority only because the majority published no list of rationales for contested redraws. The audit cannot apply it to both maps alike, so it is reported here as a single flag, not as extra rows in the structural-irregularity count. (The audit once listed a seventh redraw. It turned out to rest on a federal-boundary claim that cannot be traced in the minority report, so it was removed rather than left standing as a weak claim.)`,chair_appendix_p:`The audit also tested a separate, blanket assertion in the majority report, which the chair signed: that the minority's changes in five places (Airdrie, Cochrane, Chestermere, Red Deer and St. Albert) had <strong>no public support</strong> in the 1,345 public submissions (final report, pp. 59 and 62). A keyword search across the full submission archive (93.4% machine-parsed, 6.6% image-only and excluded; methodology and per-configuration evidence at <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/findings/submission_search_findings.md" rel="noopener">findings/submission_search_findings.md</a>) turned up a more nuanced picture than either the majority's blanket claim or a blanket dismissal of it. The majority was right on three of the five: the Airdrie 4-way split, the Calgary–Nolan-Hill–Cochrane hybrid and the St. Albert minority alternative each lack any documented support. It was wrong on Chestermere, which drew multiple submissions opposing a Calgary merger, which materially align with the minority's intent. And it was partly wrong on Red Deer: the Red Deer hybrids drew a peri-Red-Deer hybrid proposal from a sitting Red Deer councillor, aligned in direction but not in exact configuration. Two configurations the majority attacked on other grounds also drew support: Rocky Mountain House–Banff Park drew an explicit, detailed proposal from at least one Clearwater-area submission, plus several aligned ones, and Beiseker residents supported Olds–Three-Hills–Didsbury in writing. So the majority's "no public support" sweep is demonstrably overbroad, but it is not invented out of whole cloth, since three of the five do hold up. <strong>This finding cuts against the majority, not against the minority.</strong>`,summary_p:`<strong>On Lane 2, the majority crosses zero structural thresholds. The minority crosses four of the five, by a wide margin.</strong> The count is a raw tally. It is not a calibrated family-wise probability. Its weight comes from directional unanimity — every test that fires points the same way — not from a joint null-distribution calculation. The statistical lane (§3) supplies the joint probability, through a different instrument.`},cpd:{heading:`4: Cracking, Packing, and Draining`,vocab_label:`Three moves, one playbook`,vocab_packing:`<strong>Packing</strong> means cramming one party's voters into districts the party wins by landslides. Each packed ballot still counts, but once the seat is won it adds nothing more. Large, lopsided wins. Wasted votes.`,vocab_cracking:`<strong>Cracking</strong> means splitting a community across several districts so it wins none of them outright. A city strong enough to carry two seats gets carved into four, and in three of them its people are outnumbered. Diluted votes. One seat where there could be two.`,vocab_draining:`<strong>Draining</strong> is the companion move, played out on the map: packed and cracked districts sit side by side, so over-concentrated supporters on one side "drain" voting power away from the contested districts next door. That adjacency, the way the districts touch, amplifies both effects. Packing and cracking reinforce each other across district lines.`,vocab_disclaimer:`All three can happen without any explicit partisan intent. What the audit measures is whether the pattern, and its statistical size, is consistent with what a neutral map-drawing process produces. <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md#5-results" rel="noopener">Full methodology at §5 of the technical report.</a>`,fig_alt:`Map showing the division of Airdrie into four separate districts under the minority map`,fig_caption:`The division of Airdrie into four separate districts under the minority map, diluting its urban voting power.`,intro:`The five commissioners worked from the same statutory rules, the same provincial geography, the same archive of 1,345 public submissions, the same demographic data. Their two competing drafts agree on most of Alberta. Where the drafts part, they part on choices someone in the room had to make. Three of those choices are worth seeing as choices. Not numbers.`,airdrie_p:`<strong>It splits the City of Airdrie into four pieces.</strong> The law caps each electoral division at one-and-a-quarter times the provincial average, so Airdrie needs at least two divisions. The majority map gives it two. The minority gives it four: north to Olds-Three Hills-Didsbury, east to Airdrie East, west to Calgary-Foothills-Airdrie West, centre-south to Calgary-Airdrie. Only Airdrie East is mostly Airdrie; each other piece is stapled to a Calgary-edge or rural district. An Airdrie resident with a question for her MLA has to know which part of the city she lives in before she can call the right office. Her neighbours two blocks over will give her three different answers. The PTA at her child's school cannot send a single delegation to one MLA on a school-funding question. It has to coordinate four delegations to four offices, and three of those MLAs answer first to voters outside Airdrie. The minor-hockey association, the food bank, the Chamber of Commerce: every organization that works citywide now works across four provincial ridings.`,airdrie_callout_label:`WHY AIRDRIE MATTERS`,airdrie_callout_p1:`Airdrie has 85,805 people (2024 municipal census). One council, one tax bill, one school division: every civic system treats it as a unit.`,airdrie_callout_p2:`Split it across four provincial divisions — Calgary-Airdrie, Calgary-Foothills-Airdrie West, Olds-Three Hills-Didsbury and Airdrie East — and three of them are identified mainly with a neighbouring jurisdiction. The city has 85,805 residents, and one seat in the legislature where a majority of voters call the place home. The majority map gives it two.`,airdrie_callout_p3:`A four-way split is invisible to every partisan-fairness test except the one that asks: can a voter find their MLA?`,airdrie_callout_summary:`Both maps are legal. The four-way split is a choice.`,airdrie_btn:`Show flagged districts on map`,anchoring_p:`<strong>Where it departs from municipal lines, it departs at strategically important places.</strong> When an electoral map follows the edge of a city or town, voters can tell where their division begins and ends: the property-tax line, the school-division line, the local-election ward line and the provincial-election line all fall in the same place. Statistics Canada publishes these boundaries for free. On official Elections Alberta shapefiles, both maps follow municipal lines at comparable overall rates — the majority at 80%, the minority at 72% — and both sit within Canada's 70–85% norm (Quebec: 78%, Ontario: 82%, BC: 71%; comparator commissions documented in the monograph). (The audit's first, provisional analysis showed the minority anchoring at only 15%; that figure did not survive recomputation on official shapefiles — see the correction note below.) What stands out is not the overall rate. It is where the minority's departures cluster. The three boundaries the commission's own chair flagged as anomalous — Rocky Mountain House–Banff Park <button class="ed-trigger" data-ed-name="Rocky Mountain House-Banff Park">show ↗</button>'s extension into uninhabited national-park land, the Nolan Hill–Cochrane <button class="ed-trigger" data-ed-name="Calgary-Nolan Hill-Cochrane">show ↗</button> lasso corridor, and the Olds–North Airdrie <button class="ed-trigger" data-ed-name="Olds-Three Hills-Didsbury">show ↗</button> reach — each break from pre-existing civic geography, in the exact urban-edge zones where pairing urban and rural voters most directly affects which party wins the seat.`,anchoring_followup:`The minority commissioners gave reasons for each of the three flagged boundaries. For Rocky Mountain House–Banff Park, they cited geographic size, the Highway 22 corridor, and how close First Nations reserves sit to Rocky Mountain House. The commission chair called the extension into uninhabited national park land "a bad faith effort" to satisfy the area criterion, and the phrase appears in the commission's official final report. For Nolan Hill–Cochrane, they cited shared transportation and employment ties between northwest Calgary and Cochrane. Statistics Canada journey-to-work data shows only 35.8% of Cochrane workers travel to Calgary at all; most work within Cochrane itself. For the Olds–North Airdrie reach, they cited Highway 2 corridor continuity. The audit found the specific Airdrie extension fails on population grounds. Checked independently against primary data, five of the minority's six published sub-rationales fail or only partly hold.`,packing_p:`<strong>One area of Calgary is carved up to concentrate NDP voters into larger-than-average divisions.</strong> In Calgary's north, east, and central districts <button class="ed-trigger" data-ed-name="Calgary-North West-Bearspaw">show ↗</button>, the minority map's divisions average 11.5% above the provincial average. On the majority, 2.8%. The same geographic zone, drawn by the same commission under the same constraints, produces districts about 8.5% larger on one map than on the other. That fits the structural signature of <em>packing</em>: crowding one party's voters into fewer, larger districts, so each of their ballots weighs less. Packing and <em>cracking</em> (spreading a party's voters thinly across districts they narrowly lose) are the two classic gerrymandering moves. Both shrink a party's seat count below its vote share.`,chair_p:`The commission chair — appointed under the same Act, working from the same submissions — flagged four boundaries on the minority map as geographically anomalous, among them these three: Rocky Mountain House–Banff Park's extension into uninhabited national park land; the lasso-shaped Calgary-Nolan Hill–Cochrane corridor; the Olds–Three Hills–Didsbury reach into north Airdrie. The same chair gave the majority zero such flags. (In all, the chair's published criticism covers seven boundary configurations: the four geometric flags, plus three places named only in the majority report's claim that the minority's changes lacked public support. This audit independently confirmed anomalous geometry for three of the four geometric flags. The fourth, Calgary-Foothills-Airdrie West <button class="ed-trigger" data-ed-name="Calgary-Foothills-Airdrie West">show ↗</button>, did not meet the audit's confirmation threshold.) Beyond the chair's geometry flags, the audit's own cracking-signature test (academic §5.3.2) flags the four-way Airdrie split on every criterion. It is a community split that leaves Airdrie's residents a minority in three of the four ridings, which together hold nearly half the city; the majority's two-way split shows none. Cochrane and Chestermere come up cracking-adjacent. Some of what the audit's math flags, the chair did not. The audit measures the structural effect. Not intent.`},litmus:{heading:`3: The 1,010,000-Map Litmus Test`,fig_alt:`Histogram showing the distribution of efficiency gaps across 1,010,000 neutral Alberta maps. Most maps cluster near zero. The minority commission map (purple line) sits at the 94.5th percentile (+4.0%), in the shaded right tail. The majority map (teal line) sits at +0.1%, well within the normal range.`,fig_caption:`Distribution of <button class="vocab-term" data-def="a measure of how lopsidedly votes are converted into seats — positive values favour the UCP, negative values favour the NDP" aria-expanded="false">efficiency gaps</button> across 1,010,000 neutral Alberta maps drawn from the same geography. Most neutral maps cluster near zero. The shaded right tail marks the top 10%. The minority proposal&rsquo;s +4.0% sits at the 94.5th <button class="vocab-term" data-def="the percentage of maps that scored lower — p94 means 94 out of 100 neutral maps were less partisan than this" aria-expanded="false">percentile</button> — a region fewer than 6 in 100 neutral maps ever reach. The majority proposal&rsquo;s +0.1% is indistinguishable from what a neutral process typically produces.`,table_intro:`The table sets the two maps side by side. The first five rows use no election results; they are properties of the lines themselves. The last three depend on how votes were attributed to each district.`,table_col_measured:`What was measured`,table_col_majority:`Majority map`,table_col_minority:`Minority map`,table_col_direction:`Direction / Beneficiary`,table_r1_a:`Population spread across districts (tighter is better)`,table_r1_b:`3,180`,table_r1_c:`4,707 — 48% wider`,table_r1_d:`Structural (Reduces vote equality)`,table_r2_a:`NE/central Calgary population excess above average`,table_r2_b:`2.8%`,table_r2_c:`11.5%`,table_r2_d:`<strong>UCP</strong> (Packs urban NDP votes)`,table_r3_a:`Airdrie split`,table_r3_b:`2 divisions`,table_r3_c:`4 divisions`,table_r3_d:`<strong>UCP</strong> (Cracks urban/suburban power)`,table_r4_a:`Borders that follow existing municipal lines`,table_r4_b:`80% — within norm`,table_r4_c:`72% — within norm`,table_r4_d:`N/A — both within Canadian norm (70–85%)`,table_r5_a:`Boundaries flagged by the commission chair`,table_r5_b:`0`,table_r5_c:`3`,table_r5_d:`N/A`,table_r6_a:`Seats at 50/50 votes (percentile in 1,010,000-map simulation)`,table_r6_b:`46.1% — p78 (normal range)`,table_r6_c:`51.7% — p99.99 (fewer than 100 of 1,010,000 reach this)`,table_r6_d:`<strong>UCP</strong>`,table_r7_a:`Efficiency Gap (percentile in 1,010,000-map simulation)`,table_r7_b:`+0.1% — p16.5 (normal range)`,table_r7_c:`+4.0% — p94.5`,table_r7_d:`<strong>UCP</strong>`,table_r8_a:`Packing-cracking neighbourhood pattern`,table_r8_b:`2 coupled chain signals`,table_r8_c:`1 (pre-registered PASS)`,table_r8_d:`Neutral — minority achieves partisan effect via hybridization, not adjacency drain (§5.3.5)`,vocab_label:`VOCABULARY`,vocab_eg:`<strong>Efficiency gap.</strong> A single number for how lopsidedly a party's votes turn into seats. Positive numbers favour the UCP; negative, the NDP. The audit draws Alberta's outlier line at ~4.1%: the value exceeded by only 5% of the 1,010,000 neutral Alberta-specific simulations. That threshold is not borrowed from US or general literature. A threshold calibrated to another jurisdiction would be wrong here, because Alberta's natural geography produces a different neutral range.`,vocab_mm:`<strong>Mean-median difference.</strong> The gap between a party's median district vote share and its mean district vote share. When one party wins many close races, the median sits above the mean: those votes are spread efficiently. When a party wins many races by large margins, the mean sits above the median: votes are being wasted. A large mean-median gap in one direction flags structural inefficiency in how one side's votes are spread across districts.`,vocab_percentile:`<strong>Percentile ranking.</strong> In this audit, a "percentile" is a rank within the 1,010,000 neutral simulated maps. "p94" means 94% of neutral maps score lower: the real map is more extreme than 94% of neutral draws. "p99.99" means fewer than 1 in 10,000 neutral maps reach that level.`,vocab_anchoring:`<strong>Anchoring.</strong> The fraction of an electoral border that lies on a pre-existing administrative line — a city limit, a school-division boundary, a Statistics Canada census line.`,closing_p1:`The bottom rows depend on election results. The <em>seats@50/50</em> test holds the electorate at perfect parity — the UCP and NDP each win exactly half the votes province-wide — and asks how many seats the map hands the UCP. Neutral Alberta maps produce a median around 44.8% UCP seats. Alberta's geography, with NDP voters concentrated in city cores and UCP voters spread across rural ridings, gives the NDP a small efficiency advantage at neutrality. The majority map, at 46.1%, sits at the 78th percentile of the 1,010,000-map simulation: well inside the normal range. The minority map, at 51.7%, sits at the 99.99th percentile. Fewer than 100 of 1,010,000 neutral draws reach that value. The <em>efficiency gap</em> measures how lopsidedly each party's votes turn into seats. On the official Elections Alberta shapefiles the minority's efficiency gap is +4.0%, at the 94.5th percentile: just below the audit's 95th-percentile outlier line. The opening questions at the top of this page unpack the consequences.`,closing_p2:`The last row cuts the other way. On the neighbour-drain test the minority map has fewer coupled chain signals than the majority: 1 against the majority's 2 (and the 2019 enacted map's 5). The audit pre-registered this test before measuring, and the minority's lower count is a genuine pre-registered PASS. The minority does not show the classic pack-and-drain adjacency pattern. It is the single test where the minority numerically outperforms the majority. §5.3.5 of the academic report explains why. The minority gets its partisan effect through hybridization — city-splitting that internalises packing and cracking within individual electoral divisions (EDs) — and an adjacency-chain test, which only measures how packed districts cluster next to cracked ones, cannot see it.`},commission_split:{heading:`2: How the Commission Split`,intro:`Alberta's Electoral Boundary Commission finished its work on March 23, 2026 and could not agree. Three commissioners produced one map; the other two produced a different one. Commission Chair Justice Dallas K. Miller and two opposition-nominated commissioners wrote the majority report; two government-nominated commissioners — Dr. Julian Martin and John D. Evans — wrote the minority report. The split centred on how to draw boundaries in fast-growing urban-edge communities. The majority gave Airdrie two districts; the minority four. The majority drew north/east/central Calgary's divisions close to the provincial average; the minority drew them 11.5% above it. Both maps follow the same statute. Both are legal under the <em>Electoral Boundaries Commission Act</em>. The disagreement was about which specific geographic configurations best served the communities being drawn. Alberta's governing party is the United Conservative Party (UCP); its main opposition is the New Democratic Party (NDP). Smaller parties — the Alberta Party, the Liberal Party of Alberta, and others — contest seats too, but their combined provincial vote share has been low enough in recent elections that it does not materially affect the audit's partisan-fairness calculations, which are grounded in the 2023 UCP–NDP split. This audit measured both maps using the same methods, applied identically. Four findings stand out.`,finding1:`<strong>The two maps differ on six things you can measure without looking at any election results:</strong> how evenly people are spread across districts, whether voters are concentrated, how badly cities are cut up, whether borders follow city limits, the shape of the districts, and how many boundaries Commission Chair Justice Miller himself flagged as anomalous in writing (§5.8.2 of the majority report and Appendix C). The minority map differs from the majority on every one of them.`,finding2:`<strong>Every measured difference favours the same party.</strong> Everywhere the two maps diverge — north and east Calgary, Airdrie, urban areas with clear city limits — the minority map draws boundaries that spread NDP votes thinner and let UCP votes count more efficiently. The communities most reshaped by the minority map are the same communities where the NDP is strongest. The audit cannot determine intent. It can measure effect.`,finding3:`<strong>The process that replaced the commission had one precedent among the Canadian redistribution cycles this audit reviewed: Alberta's own, in 1992.</strong> None of the reviewed provinces hands redistricting, partway through a cycle, to a committee the governing party controls. Most require the legislature to debate the commission's map first, or give that map automatic effect unless the legislature overrides it. Alberta does neither. A commission report here changes nothing until the legislature passes a separate <em>Electoral Divisions Act</em>, so the governing party decides whether any commission map becomes law. On April 21 the Assembly used that power: Government Motion 37, passed 44 to 36, set both commission maps aside and gave the work to an MLA committee with a UCP majority. The government's stated justification was the chair's Recommendation 5. What that recommendation actually asks is set out next.`,finding4:`<strong>The statistical finding survives an independent change of simulation machinery.</strong> Forest-ReCom Phase A (100 k) yields percentile ranks within ±5 pp of canonical ReCom on every partisan metric — the pre-registered robustness check (OSF <a href="https://osf.io/he53s/" rel="noopener">he53s</a>, executed 2026-07-10; every metric moved by less than one percentile point). Details in Casing 9.`,closing:`<strong>The process is its own finding, separate from the maps.</strong>`},november:{heading:`The Lunty Committee`,context_label:`CONTEXT`,context_body:` — This section describes the process that replaced the commission and the legal framework that applies to it. It is not part of the statistical findings. The findings are in the fourteen casings above.`,intro:`Neither commission map is in force. On April 21, 2026 the Legislative Assembly passed Government Motion 37, setting both aside and referring redistricting to a Select Special Committee of six MLAs — four UCP, two NDP — chaired by Brandon Lunty (UCP, Leduc-Beaumont). The committee itself does not draw the map. It oversees a separate Independent Advisory Panel, constituted under the same motion, tasked with producing a 91-seat boundary proposal.`,intro_b:`Motion 37 contemplated five panel members — a sitting or retired judge as chair, two members nominated by the Premier, and two by the Leader of the Opposition — but Alberta's acting chief justice declined to nominate a judge to the chair. The panel operates with the four appointees the committee confirmed — the Hon. Monte Solberg and Darwin Durnie (Premier's nominees) and Dr. Gerard Kennedy and Brent Robinson (Opposition nominees) — under a chair appointed later: retired Court of Appeal justice Brian O'Ferrall (sourcing in Casing 13 above). The committee must deliver its report to the Legislature by November 2, 2026. Unlike the original commission, neither the committee nor the panel is required to hold public hearings; the panel draws on submissions the original commission gathered. When the committee's map is released, this audit will apply the same methodology to evaluate it.`,r5_h:`Recommendation 5: the yardstick the government chose`,r5_p1:`The government justified taking the pen by pointing to one recommendation in the commission's report. That makes it the first thing to check when the committee's map lands, due November 2. Recommendation 5 was written by one commissioner, the chair, Justice Dallas Miller, in an addendum to the majority report: “My majority colleagues do not agree with me on this point. That is why I am alone in making this recommendation” (final report, p. 66). He also stated its purpose. It “is formulated for the express purpose of dissuading the Legislature from accepting the minority report.”`,r5_p2:`It is a fallback, and it is specific. If the Legislature would not accept the majority's choice to remove two divisions outside Edmonton and Calgary, the chair asked it to amend the <em>Electoral Divisions Act</em> from 89 seats to 91, restore those two divisions, and keep “the rest of the province as we propose” (the majority map) “to the extent possible.” An all-party committee would study it. Restoring the two divisions should:`,r5_a:`<strong>(a) Leave Airdrie and the south alone.</strong> No change to any division in Airdrie, or with any land south of Airdrie's southern city limit, except Drumheller-Stettler. On the majority map that is 41 divisions: both Airdrie seats, all 28 Calgary seats, and the 11 divisions around and south of Calgary.`,r5_b:`<strong>(b) Leave north Edmonton alone.</strong> No change to any Edmonton division north of the North Saskatchewan River: 11 divisions on the majority map.`,r5_c:`<strong>(c) Put south Edmonton back.</strong> Every Edmonton division south of the river returns to the commission's interim map of October 2025, the draft it published for public comment before the final split. The committee may add Nisku to Edmonton-South East if it wants Leduc and Beaumont back in one division. That is 10 divisions on the majority map.`,r5_d:`<strong>(d) Consider a Clearwater seat.</strong> Consider restoring a division made mostly of Clearwater County and western Mountain View County, with s. 15(2) status. This is the only restored seat the recommendation places. It names no place for the second.`,r5_p3:`Read together, the conditions close off most of the ground the commission split over. Airdrie, Calgary, Cochrane and Chestermere, home to the four-way Airdrie split and the Calgary-edge hybrids, all fall inside condition (a). Red Deer and St. Albert are covered only by the softer clause: keep the majority map “to the extent possible.” A map that reopens Airdrie or Calgary may still be lawful. It is not the map Recommendation 5 describes. The <a href="__BASE__/explorer">map explorer</a> outlines all four under <em>EBC ’26 Annotations</em>; each area’s pin says whether Recommendation 5 changes it or leaves it alone.`,r5_test:`<strong>How it is scored.</strong> The audit's November checklist carries this as test X1 (academic report §5.5): the committee's map must meet all four conditions. Failing any one means Government Motion 37 did not implement the proposal the government cited.`,h_anomalous:`Why the Committee Is Anomalous`,anomalous_p1:`Canadian redistricting practice has, since the 1960s, settled on a single model: an independent commission, insulated from government direction, produces boundary recommendations; the legislature may debate them but cannot easily override them without a formal legislative vote. Alberta's statutory process under the <em>Electoral Boundaries Commission Act</em> follows this template — but with one structural difference from some other jurisdictions: Alberta's commission report has no automatic legal effect. Under the Act, a separate Electoral Divisions Act must be passed by the legislature to give any commission map force of law. This means the government of the day controls not only whether the commission map is debated, but whether it ever becomes law at all. Other Canadian jurisdictions take the opposite default: the commission's recommendations take effect unless the legislature affirmatively votes to override them.`,anomalous_p2:`What the government did in April 2026 had a precedent in Alberta itself: in 1992 a deadlocked commission's work went to a committee of MLAs. This time it allowed a completed, published commission process to conclude — both majority and minority reports filed — and then referred the redistricting task to a six-member committee of MLAs whose majority (four of six) is held by the governing party, without bringing either commission report to a vote. The Lunty committee is not a commission. It has no statutory independence from the government's legislative direction. Its four-member UCP majority mirrors the government's control of the legislature. No other Canadian province has transferred redistricting authority, mid-cycle, to a government-controlled legislative committee after an independent commission had completed its work.`,h_framework:`The Constitutional Framework`,framework_p1:`Section 3 of the <em>Charter of Rights and Freedoms</em> — "Every citizen of Canada has the right to vote in an election of members of the House of Commons or of a legislative assembly" — has been interpreted by the Supreme Court of Canada to guarantee not merely the act of casting a ballot but <em>effective representation</em>. The leading authority is <em>Reference re Provincial Electoral Boundaries (Saskatchewan)</em> [1991] 2 SCR 158, in which McLachlin J. (as she then was) wrote for the majority that the purpose of s.3 "is not equality of voting power per se, but the right to effective representation." Population parity is the primary consideration; departures are permitted when justified by community of interest, geography, history, or minority-representation objectives.`,framework_p2:`The Saskatchewan framework does not categorically prohibit partisan considerations in redistricting. What it establishes is that boundary maps must, on the whole, provide effective representation to voters — and that systematic impairment of one identifiable group's ability to elect proportionate representation is the pattern that s.3 challenges target. The audit's statistical and structural findings — the minority map's position at the 99.99th percentile of 1,010,000 neutral draws, its crossing of four of five structural thresholds (the fifth, anchoring, is neutral for both maps), the identified communities affected — are the evidentiary record a s.3 applicant would need to assemble. On the community-of-interest side of that record, the Federal Court's decision in <em>Raîche v. Canada</em> (2004 FC 679) is the leading Canadian authority: the court there required the federal Electoral Boundaries Commission to revisit boundaries that had ignored Acadian community of interest in New Brunswick. The audit's municipal-anchoring measurements and its specific community findings — Airdrie split into four districts, the chair-flagged urban-edge anomalies in northwest Calgary — are the same kind of evidence the Federal Court treated as legally cognizable. Whether that record meets the constitutional threshold is a legal question this audit does not decide; the audit reports the measurement.`,framework_p3:`The committee's legality as a process is a separate question. Alberta's <em>Electoral Boundaries Commission Act</em> does not expressly prohibit the legislature from constituting a parallel redistricting body, because the Act contemplates that the legislature will enact the final boundaries through ordinary legislation regardless. Whether the committee process, if it produces a map with the structural and statistical profile of the minority proposal, could survive a s.3 Charter challenge turns on whether effective representation is achievable under the resulting boundaries — the same test that would apply to any commission-produced map.`,h_quebec:`The Quebec Contrast`,quebec_p1:`Quebec offers the comparison most relevant to Alberta's situation. Quebec's Commission de la représentation électorale (CRE) is a permanent, independent electoral boundaries body, not an ad hoc commission constituted per redistribution cycle. The CRE operates continuously and cannot be dissolved or bypassed by cabinet action. Under Quebec's <em>Loi électorale</em>, the CRE establishes the final electoral map itself: the National Assembly debates the commission's report and hears representations, but does not vote to adopt or override it — within ten days of that debate the commission sets the boundaries, which are published in the Gazette officielle. The practical effect is that a governing party cannot, acting alone with its own majority, substitute its preferred map for the commission's; on the delimitation itself, the independent body has the last word.`,quebec_p2:`Quebec's model emerged partly from lessons about what happens when redistricting is not insulated from partisan control. The contrast with Alberta's current process — where a majority-controlled committee has replaced the commission's work before the legislature has voted on either commission report — illustrates the structural difference between redistricting systems that assume partisan pressure and design against it, versus systems where that pressure has a clearer path to the outcome.`,closing:`The audit will apply the same tests to the Lunty committee's map when it is released. The constitutional and comparative observations above are contextual; the methodology does not change.`,process_scorecard:`The map is only half of what gets scored in November. The process gets its own instrument: a nine-feature scorecard — hearings, published drafts, arm's-length drafting, and the rest of what the sixty-year norm guaranteed — published in draft on <a href="__BASE__/norms#measurable">the norms page</a>. Four of the committee's failing cells are features it can still add before it reports.`},casings:{frame_h:`The Smoking Gun`,frame_p1:`You came here looking for a smoking gun. This report does not have one. It cannot have one — and why it cannot is the most important thing we found.`,frame_cast:`Alberta’s 2025–26 Electoral Boundaries Commission finished its work on March 23, 2026, and could not agree. Three commissioners signed one map. The other two — the two the government nominated — signed a different one. Both maps are legal under the <em>Electoral Boundaries Commission Act</em>. Four weeks later, on April 21, the Legislative Assembly set both maps aside and handed the pen to a committee of six MLAs: four of them from the governing United Conservative Party (UCP), with a UCP member in the chair. That committee’s map is due November 2, 2026.`,frame_p2:`We measured both commission maps, and the process around them, every way we knew how. What we found is not a gun. It is casings: fourteen pieces of evidence, each one real, each one measured, each of which would count for something in a courtroom — and none of which, alone or together, can legally prove the conclusion they invite. A spent casing on the ground proves a gun existed and was fired. It cannot prove whose hand was on it. That gap between evidence and proof is not a loophole we failed to close. In Canada, it is the system as written. That, too, is a finding.`,frame_p3:`So this report is built like an evidence log. Each casing gets the same five questions, in the same order, every time:`,beat_found:`What we found`,beat_found_d:`the evidence, with its number.`,beat_show:`What it could show`,beat_show_d:`the conclusion you will be tempted to draw, stated at full strength.`,beat_experts:`What the experts say`,beat_experts_d:`how this kind of evidence is treated in places that do fight about it in court.`,beat_canada:`What Canadian practice expects`,beat_canada_d:`the norm.`,beat_gun:`Why it isn’t a smoking gun`,beat_gun_d:`the specific reason, under Canadian law, this evidence proves less than it seems to.`,frame_p4:`Each of the eight legal reasons is different. By the fourteenth casing you will have learned, one piece at a time, how Canadian boundary law really works — and why every casing in this log ends the same way.`,frame_p5:`Two casings in the log point the wrong way for our own story, and both are reported in full: one test we had to retract when better data arrived, and one lane where the minority map did better than the majority. A report that never loses an argument with itself isn’t checking. Failed and null tests are part of the record.`,frame_coi:`One more thing belongs in the log before the first casing: the author's own prior. He has voted for and donated to both conservative and progressive provincial parties in Alberta. For about 27 years he has also worked as a contract election officer for Elections Alberta, election by election, administering the vote on election day; nothing in this audit comes from that work. Three findings that ran against his expectation are kept in this log anyway, and every number reproduces from public code, public data, and random seeds committed in public before the analysis ran.`,frame_lenses:`This episode has three lenses, and each has its own companion page: <a href="__BASE__/law">what the law asks</a>, <a href="__BASE__/norms">what the norms ask</a>, and <a href="__BASE__/methods">how the maps were tested</a>. The log below draws on all three.`,frame_p1b:`Or maybe you came for something simpler. You heard Alberta is fighting over its electoral map, and you want to know what the fight is about. The short version: where district lines fall decides whose votes add up to a seat and whose scatter. Alberta was redrawing its ridings, the districts that each elect an MLA. The independent commission doing the work split into two camps and filed two competing maps on March 23, 2026 — both legal under the Act, both signed. Four weeks later the government set both aside and handed the pen to a committee its own party controls, a move Alberta last made in 1992. The fight is over what that committee will draw this November, and whether anyone could tell if it were drawn unfairly. This audit exists so that someone can tell.`,frame_routes:`Two ways in, then. If you came to learn the fight, start with the picture just below, then the map on the cover; the interlude midway down brings it to your own street. Each of the episode's three lenses has its own plain-language page: <a href="__BASE__/law">the law</a>, <a href="__BASE__/norms">the norms</a>, <a href="__BASE__/methods">the statistics</a>. If you came for the gun, the log starts at Casing 1: fourteen casings, five questions each, every one ending the same way.`,refrain:`A casing, not a gun.`,refrain_not_even:`Not even a casing. We logged it anyway.`,c2_refrain:`An accusation in the official record — a casing, not a gun.`,c3_refrain:`Two casings now, still no gun.`,c4_refrain:`Three casings now, still no gun.`,c6_refrain:`Sixty-nine of 1,010,000 — a casing, not a gun.`,c8_refrain:`One in 568,000 — a casing, not a verdict.`,c11_refrain:`Bad reasons for a lawful line — a casing, not a gun.`,c13_refrain:`Lawful, every step — a casing, not a gun.`,know_more:`Know more`,act1_h:`Act I: What the Map Does`,act1_intro:`Act I walks the lines themselves. No election results, no simulation: just geometry anyone can check against a paper map. The two drafts were drawn in the same room, by five commissioners working from the same statutory rules, the same provincial geography, the same archive of 1,345 public submissions and the same demographic data. They agree on most of Alberta. Where they part ways, they part on choices someone in the room had to make.`,act1_table_h:`Act I in one picture`,act1_table_close:`On Act I’s tests, the majority crosses zero of the discriminating structural thresholds, the ones that tell the maps apart. The minority crosses every discriminating one: four of four, with the retracted fifth shown rather than hidden. These measurements are geometric. They need no statistical sampler and no vote data. We pre-registered all five on April 24, 2026, fixing them in writing before the final simulation results were compiled.`,c1_title:`Casing 1 — A city of 85,805 with one seat of its own`,c1_found:`The minority map splits the City of Airdrie into four pieces. Airdrie has 85,805 people (2024 municipal census), one council, one tax bill and one school division. Every civic system treats it as a unit. The law caps each electoral division at one-and-a-quarter times the provincial average, so Airdrie needs at least two divisions. The majority map gives it two. The minority gives it four: north to Olds-Three Hills-Didsbury, east to Airdrie East, west to Calgary-Foothills-Airdrie West, and centre-south to Calgary-Airdrie. Airdrie East takes more than half the city, and nine in ten of its people are Airdrie residents. Nearly all the rest of the city is stapled to two Calgary-edge districts, where Calgary residents outnumber Airdrie’s. The north piece holds about 350 people. The split meets every criterion of our pre-registered cracking test (academic report §5.3.2), a test whose rules we fixed in writing ahead of time. The majority’s two-way split meets none.`,c1_show:`For the part of the city outside Airdrie East, this is the textbook definition of cracking: splitting a community so thinly that it decides nothing. An Airdrie resident with a question for her MLA has to know which part of the city she lives in before she can call the right office. The PTA at her child’s school cannot send a single delegation to one MLA on a school-funding question. It has to coordinate four delegations to four offices, and three of those MLAs answer first to voters outside Airdrie. If you wanted to dilute a fast-growing, politically contested city, this is what it would look like.`,c1_experts:`Community splitting is one of the primary red flags in the redistricting literature, because it is one of the two mechanical moves by which lines turn votes into fewer seats. The other is packing, its mirror. A four-way split is invisible to every partisan-fairness statistic except the one that asks: can a voter find their MLA?`,c1_canada:`Canadian commissions treat municipal integrity — keeping a city whole — as a core anchor for community of interest, the shared ties the Act asks boundary bodies to weigh. Splitting a city this size in two is routine. Splitting it four ways, leaving nearly half its residents outnumbered, is not. And the same commission’s majority draft proves a two-way split was available, on the same geography.`,c1_gun:`The <em>Electoral Boundaries Commission Act</em> allows municipalities to be split. Community of interest is one factor among several the Act lists, and it does not bind. The Supreme Court of Canada’s <em>Saskatchewan Reference</em>, the leading case on effective representation, tells courts to defer to how boundary bodies weigh those factors. Our review found no Canadian decision striking down a map for splitting a city. Both maps are legal. The four-way split is a choice, and under Canadian law, choices inside the statute’s wide lanes belong to the drawer. <em>(Legal lesson 1: the statute’s factors are discretionary, and courts defer.)</em>`,c1_app:`what “cracking” actually does to a vote`,c2_title:`Casing 2 — The three boundaries the chair called out`,c2_found:`The commission’s own chair — appointed under the same Act, working from the same submissions — flagged four boundaries on the minority map as geographically anomalous, among them these three: the Rocky Mountain House–Banff Park extension into uninhabited national-park land; the lasso-shaped corridor of Calgary-Nolan Hill–Cochrane; and the reach of Olds–Three Hills–Didsbury into north Airdrie. In the commission’s official final report, the chair called the park extension “a bad faith effort” to claim a population protection written for remote communities where people actually live. The same chair raised zero such flags against the majority map. That is not an independent verdict between the two maps: he signed the majority report, so criticism running only against the minority is what you would expect. What gives the flags weight is our own blind geometric tests, which take no side. They independently confirmed anomalous geometry for three of the chair’s four geometric flags. (The fourth, Calgary-Foothills-Airdrie West, did not meet our confirmation threshold; his published criticism covers seven boundary configurations in total.)`,c2_show:`An insider — the person legally responsible for the process — watched these lines being drawn and alleged, in public, that a legal protection was being gamed. That is as close to direct evidence as this record gets.`,c2_experts:`Spotting a gerrymander — lines drawn for a party’s advantage — began with bizarre shapes, and corridors and uninhabited extensions are the classic signatures. In fairness, the Banff arrangement has a defensible geography under the odd name and the odd shape. The town of Banff sits inside a federal park it cannot grow into, and grouping the townsite with Canmore has sound community-of-interest logic. Our Banff analysis credits that two-sided story in full. It also shows why the chair’s objection stands anyway: it is aimed at the empty-park extension, which the townsite’s placement does not touch.`,c2_banff_link:`See Banff on the map`,c2_canada:`Commissioners disagree in their reports all the time. A chair accusing colleagues of bad faith in the official final report is rare. In the cycles we reviewed, we found no other instance.`,c2_gun:`The chair’s words are opinion, inside a report with no legal force. “Bad faith” in a commission report is an accusation, not a ruling: no tribunal ever weighed it. Under the Act, both reports became advisory the moment they were filed — advice, and only advice. The legislature could set them both aside. It did. <em>(Legal lesson 2: commission reports bind no one — the legislature holds the pen.)</em>`,c2_app:`shape analysis and what s.15(2) protection is for`,c3_title:`Casing 3 — One zone of Calgary, drawn 11.5% too big`,c3_found:`Same zone of Calgary, same commission, same constraints — and on one map it comes out about 8.5% larger than on the other. In the city’s north-east and central districts, where thirteen of seventeen seats went NDP in 2023, the minority map’s divisions hold on average 11.5% more people than the provincial average. The majority’s hold 2.8% more. The pattern meets our pre-registered packing-signature test (academic report §5.3.1).`,c3_show:`This is packing: crowding one party’s voters into fewer, larger districts, so each of their ballots weighs less. Packing and cracking (finding 1) are the two classic gerrymandering moves. Both shrink a party’s seat count below its share of the vote.`,c3_experts:`Packing and cracking are the mechanism behind essentially every partisan-gerrymandering case ever argued in a United States court. Oversized districts exactly where one party’s voters cluster: that is the pattern the detection research is built to find.`,c3_canada:`Some spread from the average is normal inside the legal band, but Canadian commissions justify it with community-of-interest reasons. The minority’s published reasons for this zone are among those that fail an independent check. See finding 11.`,c3_gun:`Every one of those districts sits inside the Act’s ±25% population band, and Canadian law has no cause of action — no grounds to sue — for partisan effect. Section 3 of the Charter protects citizens’ effective representation: a meaningful voice, not just equal numbers. It does not promise parties that votes will turn into seats in proportion, and no Canadian court has read it that way. <em>(Legal lesson 3: inside the band, size asymmetry is lawful discretion — partisan effect is not a recognized legal harm.)</em>`,c3_app:`packing in a three-district toy example`,c4_title:`Casing 4 — Worse at the one thing the law actually measures`,c4_found:`Take each district, measure how far its population sits from an equal share, and average the gaps: that is the mean absolute deviation, or MAD. On the commission’s own population tables, the minority map’s districts stray further from equal than the majority’s — a MAD of 4,707 people against 3,180, 48% wider. On 2021 census numbers the gap is smaller. The two maps’ mean deviations are almost the same, while the minority’s median deviation (the gap for the district in the middle of the pack) is still wider: 3,938 against 2,827. Against neutral maps — drawn by computer, with no stake in who wins — that balance each district to within ±12.5%, that median spread sits at the 99th percentile, wider than nearly all of them. Against neutral maps allowed the statute’s full ±25%, both commission maps sit at the bottom of the range.`,c4_show:`Vote equality — every vote weighing the same — is the one value the statute puts a number on, and on the commission’s own figures the minority map gives up more of it than the majority drawn beside it. The common defence — “they had to draw weird boundaries to equalize population” — runs backwards here. The minority map is the less equal of the two.`,c4_experts:`In every formal model of redistricting, equal population is the constraint that comes first. Spread this wide, on a map drawn at the same time as a tighter one, is a cost signal: evidence that other goals outranked the statute’s central value.`,c4_canada:`Canadian commissions treat the deviation band as a limit, not a budget. Since the <em>Saskatchewan Reference</em> era, the long-run trend has been toward tighter equality, not looser.`,c4_gun:`The ±25% band is the only number in the statute, and no district on either map crosses it. Inside the band, the law does not rank maps. A wider spread and a tighter one are legally the same. <em>(Legal lesson 4: the statute contains exactly one number, and this map complies with it.)</em>`,c4_app:`what MAD measures and why the band exists`,c5_title:`Casing 5 — The casing that dissolved when we picked it up`,c5_found:`How often does a district line follow a city or town boundary? Both maps do it at rates inside the Canadian norm of 70–85%: the majority at 80%, the minority at 72% (Quebec: 78%, Ontario: 82%, BC: 71%). On overall rates, this test does not separate the two maps. What stands out is narrower. Where the minority does leave pre-existing civic lines, the departures cluster at the exact urban-edge zones the chair flagged — Rocky Mountain House–Banff Park, Nolan Hill–Cochrane, Olds–North Airdrie — where pairing urban and rural voters most directly affects which party wins the seat.`,c5_show:`When a district boundary follows a city or town line, the property-tax line, the school-division line and the provincial-election line all match, and voters can tell where their district begins and ends. On that measure the two maps look alike overall. The difference is where the minority’s departures fall.`,c5_experts:`This is what an artifact looks like: a signal made by the tools, not by the map. Provisional tracings manufactured it, and the real map files erased it. That lesson in method is why we re-ran everything on the official shapefiles the day Elections Alberta released them.`,c5_canada:`Nothing. No Canadian statute or practice guide requires any particular anchoring rate. The 70–85% norm describes what commissions do; it does not prescribe what they must do.`,c5_gun:`Not on its own. Both maps sit inside the Canadian norm, and the Act sets no anchoring threshold. Where the minority’s departures fall matters only alongside the chair’s flags and the geometry tests elsewhere on this page.`,c5_app:`what municipal anchoring measures, and what it can’t show`,act2_h:`Act II: What the Simulation Sees`,act2_intro_p1:`Act I needed nothing but the lines. Act II asks a harder question: how unusual are these maps, next to what a process with no agenda would draw? To answer it, we had a computer draw 1,010,000 mathematically neutral Alberta maps (4 independent chains × 252,500 steps, base seed from the Cloudflare drand public randomness beacon, pre-registered at OSF before execution). It used the official Elections Alberta shapefiles and held to the same statutory rules and geographic boundaries the commission used. Think of the simulation as a “what-if machine”: what would Alberta’s maps look like if nobody was trying to do anything? Set a real map inside that crowd, and its percentile — its place in the line — tells you how far out into the tail, the rare end, it sits.`,act2_intro_p2:`One fact about Alberta makes every number below readable. In this province, neutral is not 50/50. Split the province-wide vote exactly evenly, and the median of the 1,010,000 neutral maps — the middle of the pack — gives the UCP only 44.8% of seats. Why? Rural UCP voters win their ridings by wide 60-40 margins, wasting many “extra” votes, while urban NDP voters win theirs by tighter 51-49 margins and waste fewer. Left alone, Alberta’s natural political geography mildly favours the NDP’s seat efficiency. Keep that baseline in mind. It is what the maps below are measured against.`,c6_title:`Casing 6 — Fewer than 100 maps in 1,010,000`,c6_found:`Split the vote dead even, 50/50, and ask each map how many seats it hands the UCP. Across the million neutral maps the median answer is 44.8%, and the ceiling is 51.72%. Only 69 of the 1,010,000 go past the minority map’s 51.69%. The 2019 enacted map sits at 46.0% (78th percentile), the 2026 majority at 46.1% (78th percentile). The minority sits at 51.7%: the 99.99th percentile, at the far edge of the crowd. Two other pre-registered fairness measures agree. On each, the minority map lands deeper in the tail than 98 to 99.9 per cent of the neutral maps, all leaning the same way — toward the UCP. What does that mean in seats? Replay the actual 2023 voting patterns and the minority map’s geometry gives the UCP 60 of 89 seats. On the majority map, 55.`,c6_found2:`How far can “aiming” go? To find out, we also ran a targeted hill-climbing search — the standard tool for exploring biased-but-legal maps, which nudges a map step by step toward a chosen party — in both directions, 40,000 steps each, same constraints, same geometry. The minority map’s 51.7% sits closer to the deliberately aimed UCP ceiling (52.9%) than to the neutral median (44.8%). The majority map’s 46.1% sits much nearer the neutral median, at the 78th percentile. And around 50/50 the lopsidedness is starker than the number alone. A precision sweep finds that the minority map keeps the UCP at or above the 45-seat majority threshold down to a UCP vote share of about 49.7%: the UCP could lose the popular vote by 0.3 points and still form government. On the majority map, the UCP would need to win the popular vote by about 4 points to reach the same threshold. Same geography, same rules. The gap between the two maps is structural, not noise.`,c6_show:`Neutral processes essentially never produce this map. The majority map is the kind of map a neutral procedure turns out routinely. The minority map is the kind you have to aim to draw.`,c6_experts:`Ensemble outlier analysis — testing a real map against a crowd of neutral ones — is the state of the art in redistricting statistics. It is the method US courts found persuasive in the state cases that struck maps down. Three of four pre-registered metrics in the extreme tail, all four leaning the same way: that is a strong outlier profile. And the “it’s just Alberta’s natural geography” defence is already answered inside the method, because the simulation runs on Alberta’s natural geography. That geography’s baseline advantage tops out where the 2019 map and the 2026 majority sit: the 78th percentile, with the 2019 map’s highest placement on any partisan measure in the low 90s. Against Alberta’s naturally skewed baseline, the minority sits at the 99.99th percentile.`,c6_canada:`No Canadian commission has ever been required to test its map against a neutral ensemble. Here we are importing a standard the process itself never had to meet. That is exactly why the result is informative, and exactly why it binds nobody.`,c6_gun:`Two reasons, one legal and one statistical. Legal: as far as our review found, no Canadian court has yet weighed ensemble evidence. In the United States, the Supreme Court held in <em>Rucho v. Common Cause</em> (2019) that even strong statistical evidence of partisan gerrymandering is not for federal courts to police. A percentile is a description, not a threshold crossed. Statistical: the ensemble respects population and contiguity (each district a single connected piece), but it does not enforce every statutory criterion the commission worked under (s.15(2) hybrid protections, community of interest, municipal anchoring). So its percentiles measure extremity against that reference distribution, not against “everything a legally compliant commission might have drawn.” A strong outside check; not a perfect one. One further honest limit: a real electorate is not frozen at 50/50. With a big enough swing, voters can swamp any map’s structural lean. The 50/50 test isolates the map’s contribution to the outcome, not the outcome itself. <em>(Legal lesson 5: the best evidence type in the field has no legal home in Canada.)</em>`,c6_app:`how the what-if machine works and how to read a percentile`,c7_title:`Casing 7 — The test that missed`,c7_found:`The fourth partisan-fairness metric is the efficiency gap: a single number for how lopsidedly a party’s votes turn into seats, built from wasted votes (the votes a winner had beyond what was needed, plus every vote cast for a loser). For the minority map it came in at +4.0%, the 94.5th percentile. Our pre-registered outlier line is the 95th percentile (about +4.1% on Alberta’s simulated distribution). It missed. It leans toward the UCP, but it falls below the line, and every table in this report shows it that way. The majority map’s efficiency gap is +0.1% (16.5th percentile).`,c7_show:`On its own, almost nothing. That is exactly why it is in the log.`,c7_experts:`Near-misses are what an honest battery of tests naturally produces. If every test in a report fires, a reader should grow more suspicious of the auditor than of the map. This one missed, and it stays a miss. (The efficiency gap’s proposed US threshold, about 7%, is an academic proposal no court has adopted.)`,c7_canada:`Nothing. No Canadian body uses the efficiency gap at all.`,c7_gun:`We do not claim it as evidence at all. This entry is here to show the record was counted honestly. Pre-registration cuts both ways: the same locked line that gives the other metrics their force makes this one a miss. And a miss it stays. <em>(Epistemic lesson: the threshold was set before the answer was known — so the answer is allowed to be “no.”)</em>`,c7_refrain:`A casing, not a gun — and this one we do not even fire.`,c7_app:`the efficiency gap in one worked example`,c8_title:`Casing 8 — One in 568,000, and what that number is not`,c8_found:`Picture a drawing process with no agenda. How likely is it to produce the minority map’s combined four-metric profile? The chance is bounded at about one in 568,000. That is a deliberately cautious ceiling: we doubled our own margin to cover the second analytical channel we examined, so the true odds are at most this common, and likely rarer. Why double it, rather than quote the stronger single-test number? Because we gave ourselves two chances to find something rare — two channels, two chances for luck to look like a signal — so the odds are multiplied by two before they are quoted. The doubling holds no matter how the two channels relate, and that was the exact objection that killed the old figure. The four measures inside the simulation count as one look, not four, because they are combined into a single joint score before any probability is computed. (For the technical record: p ≤ 1.76×10⁻⁶, a Bonferroni-corrected, dependence-robust upper bound.) This report used to carry a stronger number: roughly one in fifteen million. That figure combined two channels (the four-metric joint score and the Swing-Zone Allocation Test) that were not statistically independent, and one of the channels later failed a corrected spatial null (finding 10). The Fisher combination was retired as the headline on 2026-06-10. The correction is permanent, and it stays on display.`,c8_show:`You will want this number to mean “the probability the map is innocent.” It is our strongest single number, and the pull to read it that way is enormous.`,c8_experts:`The number is well defined, and defensible as what it actually is: the probability of the map’s measured profile turning up under a neutral drawing process. In statistics, confusing P(evidence given innocence) with P(innocence given evidence) has a name, the prosecutor’s fallacy, and it has sent innocent people to prison. This report refuses the swap. How rare the map is under the neutral null — the no-agenda baseline — is not the probability of wrongdoing once the evidence is in (what statisticians call the posterior). For that you would need things no one has, like the base rate of eccentric-but-sincere drafting.`,c8_canada:`No Canadian legal standard takes in a number like this. There is no threshold for it to cross, because the law never defined one.`,c8_gun:`A one-in-568,000 map can still, in principle, come from unusual but honest judgment. The number measures how far outside neutral practice the map sits. It cannot see motive, and this report will not pretend it can. What we do claim is the weaker statement, and it is well supported: routine drafting variation is not a plausible explanation for this profile. What the explanation is, we put in your hands. <em>(Legal-epistemic lesson: no probability of a map is a probability of intent.)</em>`,c8_app:`the prosecutor’s fallacy in plain language`,c9_title:`Casing 9 — We tried to shoot our own result down`,c9_found:`We mounted three attacks on our own headline. The results were mixed, and all are reported in full. First, the sampler swap: we replaced the simulation’s mathematical engine with a structurally different one (a spanning-forest sampler, pre-registered at OSF as registration he53s and executed 2026-07-10), and the tail position survived. Every metric’s percentile moved by less than one point, a pre-registered ROBUST verdict on all four. Second, the software swap: an independent implementation (the R redist package) also finds zero plans reaching the minority’s value at comparable sample sizes. Third, the mechanism test, and here our claim failed. We tested whether the flagged geometry of Act I (the corridors, the park extension, the splits) is the specific mechanism producing the Act II seat advantage. The answer is no. Both lanes point at the same map and lean the same way, but the claim that the geometry is the mechanism did not survive its falsification test, the test built to knock it down. The report says so.`,c9_show:`The outlier belongs to the map, not to our tools.`,c9_experts:`Holding up across samplers and implementations is what separates a finding from an artifact. Publishing your own failed falsification is what separates an audit from advocacy.`,c9_canada:`Nobody requires any of this. We imposed it on ourselves, in writing, before running it.`,c9_gun:`Ruling out artifacts is not ruling in design. Surviving every attack we could mount establishes that the map is genuinely, robustly extreme. It says nothing about why. <em>(Epistemic lesson: robustness strengthens the description, never the accusation.)</em>`,c9_app:`what a sampler is and why swapping it matters`,c10_title:`Casing 10 — The signals that pointed the other way`,c10_found:`Three entries in the log do not help our story. All are reported. One the minority passed outright. The neighbour-drain test looks for the classic adjacency pattern, where packed districts sit right beside thin-margin ones. The minority shows 1 coupled chain signal against the majority’s 2 (and the 2019 enacted map’s 5): a genuine pre-registered PASS, and the single test where the minority beats the majority on the numbers. The pass is real but narrow. The minority gets its partisan effect through hybridization — splitting cities into districts that mix urban and rural voters inside single ridings — and an adjacency test cannot see that, because the packing and cracking happen within districts rather than between them. Two we retired. The Swing-Zone Allocation Test asked whether swing-zone voting areas were allocated to districts in a partisan pattern. It looked significant (p = 0.0024) until we corrected its null, the baseline of chance it is measured against, for spatial clustering: neighbouring voting areas vote alike, which violates the test’s assumption that each area is independent. After the correction it returns p ≈ 0.19, not significant, and on 2026-06-13 it was retired to exploratory status. And the Fisher combination that once produced the one-in-fifteen-million headline assumed an independence its channels did not have. It was retired 2026-06-10 (finding 8).`,c10_show:`As first computed, the retired tests suggested the specific boundary choices — not just the overall map — were partisan-loaded. After correction, they suggest nothing.`,c10_experts:`Spatial autocorrelation — neighbours resembling neighbours — is the classic way redistricting statistics fool their own makers, and correcting for it is the method working as intended. A drain-test pass alongside tail results elsewhere is not a contradiction. It is a fingerprint: it tells you which mechanism this map does not use.`,c10_canada:`Not applicable. These are our own instruments.`,c10_gun:`Two of these were our own instruments failing, not the map’s, and the third points in the map’s favour. They are in the record because a record that keeps only the convenient entries is not a record. <em>(Epistemic lesson, stated twice in this report on purpose: the null can win.)</em>`,c10_refrain:`Two retired, one pass for the other side. We logged them anyway.`,c10_app:`why neighbours voting alike breaks naive statistics`,act3_h:`Act III: What People Did`,act3_intro:`Acts I and II measured paper. Act III reads conduct: what the people in and around the process wrote, claimed and chose. In court, conduct is usually where questions of intent get answered. Watch what happens to it here.`,c11_title:`Casing 11 — Five of six reasons don’t survive checking`,c11_found:`The minority commissioners published reasons for their contested redraws. Five of the six fail an independent check. (A seventh redraw we had listed earlier turned out to rest on a federal-boundary claim that cannot be found in the minority report; we removed it rather than leave it standing as a weak claim.) The point is not that the minority’s reasoning is invented. In most of these cases the general claim is true, and a boundary honouring it could have been drawn. What the data does not reach is the particular line the minority actually drew. It defends Calgary-Nolan Hill–Cochrane on the idea that Cochrane residents “move fluidly” into Calgary. Statistics Canada’s 2021 journey-to-work data shows about a third of Cochrane’s workers commute somewhere in Calgary, while roughly half work within Cochrane: a real city-to-city tie, but one that says nothing about the Nolan Hill neighbourhood the corridor actually reaches. Airdrie’s commute to Calgary (about 76 percent of its out-commuters) and its rapid growth are both real, and could have supported a new Airdrie-area seat. Neither requires splitting the city four ways. Chestermere sends 86 percent of its out-commuters to Calgary, yet it shares no school division or transit system with the specific Calgary district the minority slices part of it into. And the minority’s “shared schools” argument for pairing Red Deer with Sylvan Lake does not hold. Sylvan Lake is in Chinook’s Edge School Division; the City of Red Deer is in Red Deer Public.`,c11_note:`Checked only against the minority, because the minority is the map whose contested redraws are public. The majority did not publish a list of reasons for contested redraws, so the check cannot be applied to both sides alike; it is reported as a single flag.`,c11_show:`Reasons that do not survive checking look like rationalizations: reasons found after the line, not before. In each case the evidence pointed to a boundary the minority could have drawn. The line it drew is a different one.`,c11_experts:`Setting a stated reason beside what the evidence supports is pretext analysis, a test of whether the reason is a cover. It is exactly how US courts probe intent in the gerrymandering cases they do hear. Reasons that fail on public data are the standard tell.`,c11_canada:`Commissions publish reasons precisely so the public can weigh them. Reasons that collapse against free, public Statistics Canada data defeat the point of publishing them.`,c11_gun:`No Canadian law requires a commissioner’s reasons to survive an independent check, and a failed reason fits sloppiness as easily as pretext. Courts reviewing boundaries ask whether the outcome denies effective representation, not whether the reasoning in the file was tidy. <em>(Legal lesson 6: bad reasons for a lawful line are still a lawful line.)</em>`,c11_app:`how to check a stated reason against public data`,c12_title:`Casing 12 — The commission that couldn’t sign one map`,c12_found:`The commission split: two final reports, two incompatible 89-seat maps, filed the same day. The three-commissioner majority included the chair. The two-commissioner minority — the commissioners the government nominated — produced the map every previous finding describes. Our instruments cut both ways across that divide. The majority report asserted that the minority’s changes in five places (Airdrie, Cochrane, Chestermere, Red Deer and St. Albert) had no public support in the 1,345 submissions (final report, pp. 59 and 62). We keyword-searched the full archive (93.4% machine-parsed) and found the majority right on three of the five, wrong on Chestermere, which drew aligned submissions, and partially wrong on Red Deer. Two configurations the majority attacked on other grounds, Rocky Mountain House–Banff Park and Olds–Three Hills–Didsbury, also had documented public support. The blanket claim is demonstrably overbroad. That finding cuts against the majority, not the minority, and it is in this log for exactly that reason. The criticism also ran the other way, and the log records that too. The minority report charges the majority with “an inclination to delete or mangle rural electoral divisions and, in effect, reduce effective rural representation” (minority report, p. 356). Our one majority-targeted structural counter-test to date asked whether the majority’s rural districts are engineered corridors of isolation. It came back supporting the innocent, geographic explanation (exploratory; the design and its limits are published). Then, the same day the charge surfaced, we counted the rural divisions themselves (exploratory; hypotheses frozen in the script before it ran; every classified name published). The direction reverses. Against 2019’s 31 rural-anchored divisions, the majority has 28: it absorbs three into city-named districts, merges six into three and adds three new ones. The minority has 23: it absorbs seven and merges two into one. A stricter version of the classifier gives the same order. Both maps thin rural representation relative to 2019, and that is the true core of the charge. But on the measure the accusation itself names, the minority map does more of what it accuses the majority of. The same page makes a second charge that can be measured: that the majority “declined to use” the Act’s ±25% flexibility in rural Alberta, a flexibility the minority insists is “not a benign allowance for errors in mapmaking” but “a deliberate instruction”. That one holds. The majority’s rural divisions average 6% below the provincial mean, with only four drawn more than 10% light. The minority’s average 12% below, with eleven drawn more than 10% light. Tested together, the two charges describe two design philosophies, not one vice: more-but-fuller rural divisions on the majority, fewer-but-lighter on the minority. Both directions of every cut are in the log.`,c12_show:`A process designed to converge produced two answers, and the outlier map came from the government’s nominees. You are invited to find that suggestive. Many will.`,c12_experts:`Who appointed whom is standard evidence in institutional-capture analysis. It carries weight only when the instruments are applied to both sides alike, which is why our correction of the chair matters as much as our findings against the minority.`,c12_canada:`Consensus reports are the norm, and the machinery of the Act assumes one map arrives. A split commission, with the chair publicly accusing colleagues, is not a scenario the statute was written for.`,c12_gun:`Nomination is not instruction. We found no evidence of coordination between the government and its nominees, and none can be inferred from appointment alone. Commissioners, whoever named them, have gone their own way before. <em>(Epistemic lesson: provenance raises the question; it cannot answer it.)</em>`,c12_app:`how commissioners are appointed and what nomination does and doesn’t imply`,ledger_h:`Both sides, tested — the accusations ledger`,ledger_intro:`Every accusation each side put in writing, run through the same tests, each result reported where it fell. This ledger is not a scorecard. Nothing in it gets added up: some rows land on the minority, some on the majority, some on the chair. The only score in this report is the five locked tests above. None of these checks was set up ahead of time the way those five were, so they carry less weight. Every number and name behind them is public.`,ledger_col_a:`The accusation`,ledger_col_b:`Who made it`,ledger_col_c:`Where it landed`,ledger_r1_a:`Three of the minority's boundaries are geometrically anomalous`,ledger_r1_b:`The chair (majority report)`,ledger_r1_c:`Largely confirmed — the audit's blind tests independently confirmed three of the chair's four geometric flags; the fourth fell below threshold`,ledger_r2_a:`The minority's changes in five places had “no public support”`,ledger_r2_b:`The majority (final report, pp. 59, 62)`,ledger_r2_c:`Overbroad — right on three of five, wrong on one, partially wrong on one`,ledger_r3_a:`The park extension was “a bad faith effort” to claim s.15(2) protection`,ledger_r3_b:`The chair (final report, p. 10)`,ledger_r3_c:`Undercut — the division qualifies under s.15(2) even without the flagged extension`,ledger_r4_a:`The majority “delete[s] or mangle[s] rural electoral divisions”`,ledger_r4_b:`The minority (p. 356)`,ledger_r4_c:`Reversed — the minority keeps fewer rural-anchored divisions (23 vs 28, against 2019's 31) and absorbs more into city-named districts (7 vs 3)`,ledger_r5_a:`The majority “decline[d] to use” the ±25% flexibility in rural Alberta`,ledger_r5_b:`The minority (p. 356)`,ledger_r5_c:`Supported — majority rural divisions average −6.0% deviation (4 below −10%); the minority's average −12.2% (11 below −10%)`,ledger_r6_a:`“Substantial and consistent testimony” for hybrids was ignored`,ledger_r6_b:`The minority (p. 356)`,ledger_r6_c:`Overbroad — support was configuration-specific: documented for three of seven hybrid configurations, absent for three`,ledger_r7_a:`The majority's rural districts are engineered corridors of isolation`,ledger_r7_b:`The audit's own counter-hypothesis (T3.2)`,ledger_r7_c:`Not supported — the geographic explanation held; the majority cleared`,ledger_close:`Neither side's accusations survived intact, and neither side's map escaped a hit. On the floor of the legislature, no one criticized the majority report at all. The government wrapped its motion in the majority chair's own recommendation; the opposition demanded the report's adoption. The written charges against the majority exist only in the minority's own pages. That is why we had to test them ourselves.`,c13_title:`Casing 13 — When the process might have answered, it was replaced`,c13_found:`The commission held hearings in sixteen communities, received 1,345 written submissions, and reversed its own interim proposal on the strength of 80-plus of them: a system visibly responding to what the public said. Four weeks after its split reports arrived, that system was replaced. Government Motion 37, introduced April 16 and passed April 21, 2026, set both reports aside. It created a Select Special Committee of six MLAs — four UCP, two NDP, chaired by UCP MLA Brandon Lunty — to oversee a 91-seat map due November 2, 2026 (<a href="https://www.assembly.ab.ca/assembly-business/committees/ceb" rel="noopener">committee page</a>). The committee is not required to hold public hearings, and per <a href="https://www.cbc.ca/news/canada/edmonton/alberta-boundaries-committee-motion-9.7172743" rel="noopener">CBC’s reporting</a> it will not hold hearings on the map it produces. No draft will be released for public challenge before the map is final. It is served by an Independent Advisory Panel, <a href="https://www.cbc.ca/news/canada/edmonton/alberta-boundaries-panel-legislative-committee-elections-9.7187435" rel="noopener">chaired by retired Court of Appeal justice Brian O’Ferrall</a>. The panel advises; the MLAs decide. On the floor, the government presented the takeover as faithfulness to the commission — “We are adopting the recommendations from the report” (Government House Leader, Hansard, April 16, 2026) — while the opposition described the same motion as presenting the “minority report in slow motion.” Against the report itself, that claim of faithfulness reads narrower. The majority asked the Legislature to adopt its 89-seat map. Its seat-count fix was aimed at future commissions. And the one recommendation that did propose 91 seats was the chair’s alone: “My majority colleagues do not agree with me on this point.”`,c13_show:`When the independent route failed to deliver a usable answer, the government took the pen. And the vehicle it chose removed every mechanism by which the public could contest what it writes before it becomes law.`,c13_experts:`The design gives up each transparency feature the redistricting research treats as protective: published drafts, public hearings, arm’s-length drafters. Civil-liberties observers (<a href="https://ccla.org/press-release/ccla-sounds-the-alarm-over-the-politicization-of-albertas-electoral-map/" rel="noopener">CCLA</a>) raised the concern about politicization independently of this audit.`,c13_canada:`This is the deepest norm in modern Canadian redistribution: politicians do not draw their own districts. Alberta last broke it in 1992, when a committee of MLAs drew the 1993 map. The Court of Appeal let that map stand in 1994 but faulted the committee for being unable to explain several of its boundaries, and in 1995 the Act was amended to change how commissions are appointed. Our November tests (on the main page) measure the committee’s process against exactly the features it is not required to provide.`,c13_gun:`Every step is lawful. The Act makes the commission’s reports advisory. It sets no minimum notice or comment period, and it imposes no hearing or draft-release requirement on what follows. Under parliamentary sovereignty the legislature may lawfully do precisely what it did. <em>(Legal lesson 7: the process that could have created accountability is optional — and opting out is legal.)</em>`,c13_app:`the Act’s process from commission to committee, end to end`,c14_title:`Casing 14 — The sixty-year norm, set aside in an afternoon`,c14_found:`Canada spent roughly sixty years building independent boundary commissions. They were the institutional answer, since the federal reform era of the 1960s, to the once-routine practice of governing parties drawing their own ridings. In May, Duane Bratt, Professor of Political Science at Mount Royal University, described the process to the author as without precedent in Canada. That claim is wrong. In 1992 Alberta set its deadlocked commission’s work aside and gave the map to a committee of MLAs, whose map was used in the 1993 election. What is new in 2026 is narrower. The commission did not deadlock — a majority signed a report, which the Act treats as the commission’s report — and it was set aside anyway. In some jurisdictions a commission’s map takes effect unless the legislature overrides it. In Alberta, it takes a bill.`,c14_show:`The opposition named it on the floor: “retaliation against the independent Electoral [Boundaries Commission].” The injury is not one map. It is the demonstration that the guardrail was a convention, a habit and not a law — and conventions bind only governments that consent to be bound. Nothing prevents the next government, of any party, from citing this cycle as precedent.`,c14_experts:`Research comparing jurisdictions treats independent commissions as the single most protective institutional feature against gerrymandering. Removing the institution matters more than any one boundary it might have drawn.`,c14_canada:`The federal process and the provinces use arm’s-length commissions, with exceptions: Alberta in 1992, and Quebec, whose National Assembly legislated its own 127-seat map in June 2026 after the Supreme Court struck down its pause of the commission. Alberta’s 2026 cycle departed from that standard by simple majority vote.`,c14_gun:`Constitutional conventions bind politically, but courts will not enforce them; the Supreme Court said as much in the 1981 Patriation Reference. That does not put the process beyond the courts’ reach. In 2017 Nova Scotia’s Court of Appeal found a map unconstitutional because the government had stifled its commission’s independent view. In 2026 the Supreme Court struck down Quebec’s law pausing its commission (<em>Quebec (AG) v. Lalande</em>, 2026 SCC 13). What a court reviews is the enacted map, under section 3. <em>(Legal lesson 8: norms are not law, but how a map is made can still matter in court.)</em>`,c14_app:`conventions versus law, and how norms erode`,rev_h:`The Scorecard, Revisited`,rev_p1:`Fourteen casings. No gun. Now go back to the picture from the top of this page — you can read it now.`,rev_p2:`The horizontal axis is one of Act II’s four fairness measures: the efficiency gap, more UCP-favoured the further right you go. The vertical axis is Act I’s count of discriminating structural tests failed, the tests that tell the maps apart. The 2019 map and the 2026 majority sit in the quiet corner: near-zero skew, zero structural flags. The minority sits alone. Four of four structural flags. An efficiency gap just under the line we set in advance. And, off this chart’s axes, a tied-vote seat count that only 69 of 1,010,000 neutral maps exceed, and a 60-of-89 seat outcome on recent voting patterns. The two acts converge on the same map and the same communities. The specific claim that the geometry is the mechanism failed its test (Casing 9), yet both acts still agree on who benefits.`,rev_litany_intro:`Now run this instrument itself through the same five questions, one last time.`,rev_found:`A scorecard: the best instrument I could build to draw fourteen casings together into something that can be stated, checked, and falsified. Five pre-registered structural tests: the minority crosses every discriminating one, the majority none, the retracted fifth on display. Four partisan-fairness metrics against 1,010,000 neutral maps: three in the extreme tail, one reported miss.`,rev_show:`The closest thing to a gerrymandering signal that can exist under Alberta law and Canadian norms: a checkable way of saying “this map is the kind of map that aiming produces,” with every threshold set before any answer was known.`,rev_experts:`When intent cannot be seen, the field reads maps with combined batteries of outlier tests. Pre-registration is what keeps them honest.`,rev_canada:`Nothing. No Canadian institution scores maps this way. That is exactly why we had to build one.`,rev_gun:`Its thresholds are our own calibrations, not legal lines. Alberta is one province with one split commission: a sample size of one. And no pile of casings ever becomes a gun, because the gap between “extreme” and “deliberate” is not statistical. It is the gap the law chose to leave open.`,rev_refrain:`A casing, not a gun. But this casing fires again in November.`,playbook_h:`What running the play again would look like`,playbook_p1:`This report cannot prove a gerrymander; the word has no legal home here. What it can do is say, in advance and in public, exactly what the signature looks like, and then say whether the November map carries it. Our November tests were registered (OSF, registration qsgy8) before the committee’s map existed. The registration’s own name for the check is the Lunty test, and it is the confirmatory counterpart to everything above. The signature has two halves. Process: were public hearings held; was a draft released; are the advisory panel’s members and terms of reference published; does the map honour the recommendation the government cited when it took the pen? Outcome: where the map lands on every metric in this report, against the same million-map distribution, under the same pre-registered thresholds.`,playbook_p2:`Suppose the committee’s map repeats the minority’s signature, though drawn by different people, under different constraints, on a different timeline. Then the structural finding above earns confirmatory status. If it lands inside the neutral bands, the finding stands as an isolated observation about one map that was never enacted, and this report will say exactly that. The scoring runs within 72 hours of the map’s release, whichever way it points. That commitment was registered before anyone knew the answer. Pass or fail, you will not have to trust our judgment. Only our arithmetic, which is public, seeded from a public beacon, and reproducible by anyone.`,appendices_note:`Every casing above links to a lettered explainer — one concept each, from “this is confusing” to “now I understand” — on the companion page:`,appendices_link:`The fourteen explainers (Appendices A–N)`},authors_view:{heading:`The Author's View`,heading_aria:`Link to the author's view`,preamble:`Everything else on this page is the audit. Pre-registered tests. Documented corrections. Evidence you can check without trusting me. Delete this section and not one number changes. This section is not a finding. It is an opinion — signed, severable, and mine.`,p1:`The audit cannot prove intent. I have kept that discipline on every page above. This page is where I set it down.`,p2:`Start with the two facts I cannot make innocent. Government-nominated commissioners drew a map that neutral map-drawing almost never produces — fewer than a hundred matches in a million draws. And when the commission split rather than endorse it, the government did not ask why. It took the pen.`,p3:`Each fact has an innocent reading. A commissioner can be eccentric in good faith. A legislature can lose patience with deadlock. But put the facts in sequence and the innocent readings strain. A government wanted a certain kind of map. The independent route did not deliver one. A route was found that would.`,p4:`Here is what alarms me. It is not that a law was broken. No law was broken — I checked, and that checking is most of what this audit is. The statute makes the commission’s report advisory. It sets no notice period. It requires no draft, no hearings, no consultation. Every step of the takeover was legal. That is the alarm. The guardrail was never law. It was a habit — and habits only bind governments that choose to keep them.`,p5:`Look at what the habit used to buy. The commission held hearings in sixteen communities. It read 1,345 written submissions. It changed its mind in public, because the public gave it reasons to. The committee that replaced it is six MLAs: four government, two opposition, government chair. No rule required an independent voice at that table, and none sits there. There is an advisory panel — chaired, to its credit, by a retired judge. But advisers advise. The votes belong to the MLAs, and the map they draw is the map they will run in. It will face no public hearing. No draft will be released for the public to contest. It arrives finished.`,p6:`And this government has been here before. Its first bill, as written, would have let cabinet rewrite laws without the legislature. That power was stripped — after the outcry, not before. Its own ethics commissioner found the Premier breached the conflicts law by pressing her attorney general about a criminal case, and called interference with the administration of justice “a threat to democracy.” It passed a law letting cabinet repeal local bylaws and trigger the removal of elected councillors. And when a court paused one of its laws in December 2025, it invoked the notwithstanding clause; within a week the injunction was gone. Every one of those moves was lawful. Every one spent a norm to get past an independent check. Redrawing the electoral map through a committee the government controls is not a departure. It is the pattern, applied to elections.`,p7:`Political scientists have names for governments that keep the letter of the law while hollowing out the norms beneath it. The gentlest is <em>democratic backsliding</em>. The literature is blunt about how it works. Democracies rarely die of coups anymore. They die of this — one lawful, norm-breaking step at a time, each with a plausible reason, none of them illegal.`,p8:`Canada spent sixty years building one norm above the rest: politicians do not draw their own districts. Voters choose their representatives. Not the reverse. In April 2026, Alberta set that norm aside in an afternoon, by a vote of 44 to 36.`,p9:`I worry about what the map buys. On recent voting patterns, the minority map’s geometry yields sixty seats of eighty-nine. That is not a mandate. It is insulation — from floor-crossings, from committees, from any opposition large enough to sustain scrutiny. I would worry about that insulation in any hands. I worry more in the hands of a government that has just shown me, in this very file, what it does with procedural control when a process threatens to answer back.`,p10:`I could be wrong. Unlike most opinions about this government, mine ships with the terms of its own destruction. The committee’s map is due November 2. The tests were locked before it existed. Were hearings held. Are the advisers named, their terms of reference published. Does the map honour the recommendation used to justify the takeover. Where does it land against a million neutral maps. If it lands inside the neutral bands, my suspicion took real damage — and this site will say so within seventy-two hours, because I committed to that before I knew the answer. That is the difference between an opinion and an accusation. An opinion tells you what would change it.`,signed:`— Will Conner`,sources:`<em>Sources for this section.</em> The ethics finding and the quoted phrase are verbatim from the Ethics Commissioner’s report, <a href="https://www.ethicscommissioner.ab.ca/media/3124/allegations-involving-premier-danielle-smith-may-17-2023.pdf" rel="noopener">Allegations Involving Premier Danielle Smith (May 17, 2023)</a>: “In my opinion, Premier Smith contravened s.3 of the Conflicts of Interest Act in her interaction with the Minister of Justice and Attorney General.” The Sovereignty Act’s original cabinet powers and their removal: <a href="https://www.cbc.ca/news/canada/edmonton/alberta-sovereignty-act-1.6678407" rel="noopener">CBC, December 2022</a>. Bill 20’s cabinet powers over councillors and bylaws: <a href="https://www.cbc.ca/news/canada/edmonton/alberta-bill-gives-cabinet-power-to-remove-municipal-councillors-change-or-repeal-bylaws-1.7185346" rel="noopener">CBC, April 2024</a> and the <a href="https://rmalberta.com/wp-content/uploads/2025/10/Bill-20-Member-Resource-Branded.pdf" rel="noopener">RMA analysis of the act as passed</a>. The notwithstanding-clause invocation and the injunction’s end: <a href="https://www.cbc.ca/news/canada/edmonton/alberta-government-notwithstanding-clause-bills-9.6983786" rel="noopener">CBC, December 2025</a> and <a href="https://egale.ca/awareness/egale-v-alberta-healthcare/" rel="noopener">Egale Canada’s case timeline</a>. The committee’s structure, the advisory panel, and its judicial chair: <a href="https://www.cbc.ca/news/canada/edmonton/alberta-boundaries-committee-motion-9.7172743" rel="noopener">CBC, April 2026</a> and <a href="https://www.cbc.ca/news/canada/edmonton/alberta-boundaries-panel-legislative-committee-elections-9.7187435" rel="noopener">CBC, May 2026</a>; the commission’s sixteen-community hearings and 1,345 written submissions are from its final report (p. 14). The committee’s creation (Government Motion 37, passed April 21, 2026) and its six members: the <a href="https://www.assembly.ab.ca/assembly-business/committees/ceb" rel="noopener">Legislative Assembly’s committee page</a>. The acting chief justice’s refusal: <a href="https://bowislandcommentator.com/news/2026/05/28/chief-justice-cites-integrity-issues-refuses-to-suggest-electoral-boundaries-chair/" rel="noopener">Southern Alberta Newspapers, May 2026</a>. The 1992 committee and the 1995 rebuild: <a href="https://albertaviews.ca/knowing-draw-line/" rel="noopener">Alberta Views</a> and <a href="https://docs.assembly.ab.ca/LADDAR_files/docs/bills/bill/legislature_23/session_3/19950213_bill-020.pdf" rel="noopener">Bill 20 (1995)</a>. “Democratic backsliding” follows Steven Levitsky and Daniel Ziblatt, <em>How Democracies Die</em> (Crown, 2018), and Nancy Bermeo, “On Democratic Backsliding,” <em>Journal of Democracy</em> 27(1), 2016. The ensemble and seat figures are this audit’s own, sourced throughout the report above.`},references:{heading:`References and Methodology`,heading_aria:`Link to references`,intro:`The method draws on established literature in political science, statistics and law. Full citations follow American Political Science Association (APSA) style; court cases follow Canadian legal convention. The complete reference list is in the <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">technical report</a>. The key sources are here.`,h_academic:`Academic literature`,h_cases:`Court cases`,h_statutes:`Statutes`},resources:{heading:`Reports and code`,heading_aria:`Link to technical`,tag_plain:`Plain Language`,plain_label:`Full public report`,plain_desc:`Long-form, with maps, for general readers`,tag_summary:`Summary`,summary_label:`Summary of findings`,summary_desc:`Plain-language overview that explains every concept from scratch`,tag_academic:`Academic`,academic_label:`Technical report`,academic_desc:`Full methods and citations for researchers`,tag_notebook:`Notebook`,notebook_label:`Interactive notebook`,notebook_desc:`Run the charts yourself, in your browser, with nothing to install`,tag_code:`Code`},about_me:{heading:`About me`,p1:`I'm a student at Mount Royal University. I did this research on my own: it was not assigned as coursework, and the university did not commission it. My views are my own and do not represent the university. I've worked as a contract election officer for Elections Alberta for about 27 years, election by election, administering the vote on election day. I'm not under contract now; I last worked at a recent election. I've had no other employment with Elections Alberta and have no knowledge of its work beyond those tasks. Nothing in this audit comes from that work; every input is public. This research is my own, not Elections Alberta's, and does not speak for it. I have no connection to the commission. I've voted for and donated to both conservative and progressive provincial parties in Alberta as an adult.`,p2:`My political history could affect how I look at this issue, and the main protection against that is the method. I tested both maps the same way, registered my tests in public, time-stamped records, labelled every finding pre-registered or exploratory, and put everything online so anyone can check my work. I paid for this research myself. If you find something I got wrong, I want to know.`,p3:`Seed-commitment and pre-registration records: <a href="https://osf.io/6pt83" rel="noopener">OSF:6pt83</a>, AsPredicted:#289,469, AsPredicted:#289,451 — the random seeds were time-stamped to a public beacon before the official shapefiles were released; the neighbour-drain test (#289,451) was registered before measurement, the others filed alongside exploratory analysis.`,p4:`Questions or corrections: `},translation_about:{heading:`About this translation`,p1:`You are reading an AI translation. Anthropic’s Fable 5 model produced it, and it is still awaiting review by a native speaker. The English version is the authoritative text: if anything in this translation is unclear or seems wrong, the English original governs.`,p2:`Translation quality matters here in a way it doesn’t on most websites. This audit makes statistical claims about electoral fairness, and a mistranslated number or a wrongly hedged sentence misleads in ways a reader will find hard to detect. Machine translation of civic-statistical prose is genuinely difficult. Errors are likely.`,p3:`If you are a native speaker and you spot an error — or you’d like to review a section properly — please %s. For scale: the English prose runs about {count} words. You are welcome to take on all of it, or just a portion. In most cases the work is correcting minor errors the machine made, not translating from scratch, and even reviewing a single section helps.`,p3_link:`get in touch`},retractions:{heading:`Retractions and Corrections`,heading_aria:`Link to retractions`,conditions_label:`RETRACTION CONDITIONS`,conditions_intro:`Every finding is pre-committed to a specific falsification condition. If any condition below materialises, the finding it names is retracted publicly within 30 days. The overall directional conclusion — that the minority map sits outside the neutral range on multiple independent tests — is retracted under the methodology's pre-committed compound condition: at least three of the six independent structural dimensions reversing direction.`,c1_title:`Condition 1 — A counter-map exists`,c1_what:`<em>What gets retracted:</em> The structural finding that the Airdrie four-way split and the three chair-flagged boundaries cannot be explained by the minority's stated community-of-interest rationale.`,c1_cond:`Condition: someone produces a legal Alberta map satisfying the minority's own stated reasons — Airdrie, Cochrane, Nolan Hill, Rocky Mountain House–Banff Park — and anchors on municipal lines at majority-comparable rates. Open challenge at <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/issues/14" rel="noopener">Issue #14</a>.`,c2_title:`Condition 2 — The Neighbour-Drain pre-registered pass is reversed`,c2_what:`<em>What gets retracted:</em> The Casing 10 entry recording the minority map as a pre-registered PASS on the neighbour-drain adjacency test.`,c2_cond:`Condition: the v2 continuous drain score falls in the extreme upper tail (p &lt; 0.05) of random permutations across the fixed contiguity graph, meaning the pass was a measurement artefact of the v1 binary scoring method rather than a genuine null result.`,c3_title:`Condition 3 — A pre-2026 commission document surfaces`,c3_what:`<em>What gets retracted:</em> The inference that the minority's boundary choices were drafting decisions rather than responses to documented community submissions.`,c3_cond:`Condition: an internal commission document dated before the minority's final boundary choices shows those choices were explicitly driven by community submissions the audit has not seen — not by the six published sub-rationales the audit tested.`,c4_title:`Condition 4 — The 2027 election result contradicts the simulation`,c4_what:`<em>What gets retracted:</em> The simulation finding — that at a tied vote the minority map awards a seat share only 69 of 1,010,000 neutral draws exceed.`,c4_cond:`Condition: if the 2027 provincial election is fought on either commission map and the actual partisan seat split contradicts the directional projection from 2023 votes, the simulation's percentile findings are revisited against actual results.`,c5_title:`Condition 5 — An Alberta court distinguishes the Quebec SCC ruling`,c5_what:`<em>What gets retracted:</em> The procedural argument in the Lunty Committee section that Government Motion 37, which replaced the commission with the Lunty committee, sits in the same constitutional class as Quebec's 2024 redistricting freeze.`,c5_cond:`Background: on April 22, 2026 — the day after Alberta passed Government Motion 37 — the Supreme Court of Canada upheld, 7–2 and from the bench, a Quebec Court of Appeal ruling that the Legault government's legislative freeze on its redistricting commission violated the Charter's s.3 democratic-representation guarantee. Condition: a court reviewing the Alberta motion finds it constitutionally distinct — for example, because reassigning the work to an MLA committee differs structurally from a legislative freeze, or because Alberta's effective-representation analysis under s.3 comes out differently than Quebec's.`,corr_label:`DOCUMENTED CORRECTIONS (canonical recomputation, 2026-05-11)`,corr_light_label:`CORRECTIONS`,corr_light_intro:`This audit corrects in public and deletes nothing. The retracted structural test is told in full at Casing 5; the two retired statistical tests at Casings 8 and 10. The complete ledger of every correction — what changed, when, and why — is kept in the <a href="https://github.com/Ixby/alberta-electoral-boundaries-audit/blob/master/reports/academic/report_academic.md" rel="noopener">academic report’s DOCUMENTED CORRECTIONS section</a>.`,corr_intro:`The following early finding did not survive reanalysis against official Elections Alberta shapefiles (received 2026-05-06). It is retained here per the audit's pre-committed policy of never deleting failed findings.`,corr_municipal:`<strong>Municipal anchoring (retracted).</strong> Early analysis using provisional map boundaries showed the minority map anchored to municipal lines only 15% of the time — 4.9&times; below the 70–85% Canadian norm. This figure was an artefact of the provisional (DPG-era) boundary reconstructions. On official Elections Alberta canonical shapefiles, both maps anchor within the Canadian norm: majority 80%, minority 72%. The municipal-anchoring <em>divergence</em> between the two maps is not a signal that survives canonical recomputation. The three boundary anomalies flagged by the commission chair (Rocky Mountain House–Banff Park, Nolan Hill–Cochrane, Olds–North Airdrie) remain and are not affected by this correction.`},suggestions:{heading:`Suggestions`,heading_aria:`Link to suggestions`,resume:`The opinion is over; the log resumes. Three pieces of housekeeping remain: what would make the next audit easier, the conditions under which this one retracts itself, and the paper trail.`,intro:`This audit ran into two data problems that have nothing to do with the commission's work and everything to do with how Alberta's electoral system is designed. Both are fixable.`,advance_p1:`<strong>About half of all Alberta votes now arrive before election day</strong>: advance polls, mobile polls, special ballots. Elections Alberta reports these results as totals for each electoral division, not by specific Voting Area. So roughly 395,000 NDP and UCP votes cast in 2023 cannot be pinned to any neighbourhood on a map. They are counted. They just can't be located. Every advance voter is checked against a voters list before receiving a ballot, and that list links each voter to a specific Voting Area. Publishing advance-vote totals by Voting Area would not require any change to the voting process. Only to what Elections Alberta reports.`,advance_p2:`This affects the commissioners too, not just outside analysts. When a commission decides whether to keep Airdrie whole or split it, whether a corridor between two communities makes sense, whether a proposed boundary divides a natural constituency, it is making judgments that depend on knowing where voters live. Commissioners work from the same published dataset as everyone else. They are missing half the geographic signal too, about the very communities they are drawing boundaries around.`,lesser_slave_p1:`In at least one community in northern Alberta, this gap is total. In the northern part of the Lesser Slave Lake <button class="ed-trigger" data-ed-name="Lesser Slave Lake">show ↗</button> division sits a Voting Area covering 4,832 km&#178; — more than four-fifths the size of Prince Edward Island — where every single vote in 2023 was cast through Elections Alberta's mobile polling team. Those 844 residents' choices are counted in the divisional total, but they cannot be pinned to any location on a map. In the published election results, the community is entirely invisible.`,lesser_slave_p2:`When the commission first considered eliminating the Lesser Slave Lake division and merging it into a larger riding, it was working without geographic vote data from those communities. In the end it preserved the division. That came after 80+ public submissions, many from the Indigenous communities in the northern part of the riding, and it invoked s. 15(2) of the <em>Electoral Boundaries Commission Act</em> — the provision that lets up to four remote ridings, meeting at least three of five criteria such as size, distance and the presence of a First Nations reserve or M&#233;tis settlement, have populations as much as 50% below the provincial average. They got there. But the data in front of them didn't show who was voting in the communities they were deciding to protect.`,ebca_label:`SECTION 15(2) EBCA`,ebca_body:`Section 15(2) of Alberta's <em>Electoral Boundaries Commission Act</em> is a discretionary provision that allows commissions to protect undersize ridings — those more than 25% below the provincial population average — when the riding meets at least three of five specific criteria: (a) geographic area exceeding 20,000 km², (b) distance more than 150 km from the Legislature Building by most direct highway route, (c) absence of any town with more than 8,000 residents, (d) presence of an Indian reserve or a Métis settlement, and (e) whether the riding is coterminous with a boundary of the Province of Alberta. The provision is not automatic; the commission must judge whether the criteria are met. Lesser Slave Lake independently meets four of the five.`,rationale_p1:`The interim rationale for eliminating the riding was population. At roughly 27,000 residents, Lesser Slave Lake sits about 45% below the provincial average, close to the legal floor. That reads like a straightforward application of the rules. It isn't. Alberta law gives commissions explicit discretion to protect undersize ridings when at least three of five specific criteria apply, and Lesser Slave Lake meets four of them independently. Its area is 69,566 km² (criterion a, threshold 20,000 km²). Its nearest boundary is more than 150 km from the Legislature by highway (criterion b). No town in the riding has a population over 8,000 (criterion c). And the riding contains fourteen Indian reserves and M&#233;tis settlements whose communities share a common northern geography, a common dependence on mobile polling to vote at all, and a collective interest in having a representative primarily accountable to northern Alberta (criterion d).`,rationale_p2:`Under the proposed Mackenzie merger, that collective voice would have been absorbed for good into a riding where the other party wins by more than two to one. Not because those communities changed. Because the lines around them did. Each of those four criteria is an objective fact about the riding's geography, not a judgment call. Together they describe a constituency the provision was written to protect: remote, large, sparsely populated, and home to communities whose interest in representation cannot be read from raw population numbers. You need three to qualify. Lesser Slave Lake has four. Treating the population shortfall as if it compelled elimination misreads the statute. The commission's reversal was the correct application of the law, not a concession to political pressure.`,banff_p:`Here is the other side of the story. While the Indigenous communities in Lesser Slave Lake were fighting to be counted, the dissenting commissioners proposed protecting a different riding by extending it into the uninhabited part of Banff National Park. The commission's own chair called it "a bad faith effort" to claim the legal protection; the phrase is in the commission's official final report. The audit's check undercuts that charge: the division qualifies under s.&#x2009;15(2) even without the extension. Still, in the minority's map, a protection written for remote communities where people live was stretched over empty parkland. The communities it was designed to help had to fight for it through public submissions. The Lunty committee will face the same §&#x2009;15(2) decision in November, with no statutory requirement to hold public hearings and no guarantee that the 80 submissions that reversed the commission's interim position will carry the same weight a second time.`,census_p1:`<strong>Alberta should wait for the 2026 census before drawing the next map.</strong> Canada counts its population every five years. The 2026 census was taken in May 2026, and its first results are due in February 2027. The commission that drew the maps assessed in this audit had to start from the 2021 census, updated to a July 2024 provincial estimate: a count already four years old when the maps were drawn, and potentially fourteen years old by the time those boundaries retire. Fast-growing cities like Airdrie and Chestermere will change by 40% or more over that window. Rural communities will shrink. The map will be wrong from the day it is used. A straightforward change to the <em>Electoral Boundaries Commission Act</em> could require that any new commission be appointed only after Statistics Canada releases the most current dissemination-area data from the preceding census. The result: maps that reflect where Albertans actually live. Not where they lived a decade ago.`,census_p2:`The Lunty committee works under the existing statute, which sets no census-timing requirement, and it cannot unilaterally delay past its November 2026 deadline. This recommendation applies to a future amendment to the <em>Electoral Boundaries Commission Act</em>, not to the current process. The tension is real. A committee required to deliver a map by November is working from a census already five years old by then. Naming the constraint is more useful than pretending it does not exist.`,closing:`Neither of these is a finding about the current commission's maps. They are observations about a system that makes accurate electoral analysis harder than it needs to be, offered here as practical suggestions, not conclusions. Both are genuinely fixable. Fixing them would put every future commission, and every future audit, on better ground.`}},editorial_canada:{heading:`Context: Canada is different — and similar`,p1:`Canada belongs to the same family as the U.S., the U.K., and Australia. We elect single members from geographic districts under first-past-the-post. We redraw the lines periodically — federally after each decennial census, provincially on staggered schedules. We inherited the basic machinery from the same Westminster roots. So far, no surprises.`,p2:`What sets Canada apart is the test the lines have to pass.`,p3:`In American constitutional law, the binding rule is <em>one person, one vote</em> — districts must have populations as nearly equal as practicable, and large departures require strict justification. In Canadian constitutional law, the binding rule is different. Section 3 of the <em>Canadian Charter of Rights and Freedoms</em> guarantees every citizen the right to vote. In <em>Reference re Provincial Electoral Boundaries (Sask.)</em> — the 1991 Saskatchewan Reference, the leading case — the Supreme Court of Canada interpreted the right as a right to <em>effective representation</em>, not a right to mathematical equality of district populations.`,p4:`That distinction matters. Effective representation allows district populations to vary, sometimes substantially, when there are good reasons: vast rural geographies one MLA cannot reasonably serve at standard population density, communities of interest that should be kept together, minority representation that mathematical equality would dilute. The Saskatchewan Reference made that flexibility constitutional. The EBCA's 25% population variance — the rule that protects rural Alberta seats — flows directly from it.`,p5:`The catch is that flexibility cuts both ways. If a commission can legitimately depart from population equality for the right reasons, it can also depart from population equality for the wrong ones. Canadian law has no American-style mathematical floor to fall back on. It has the effective-representation test, applied by judges, after the fact, in litigation. Most jurisdictions guard against the wrong reasons with structural protections: federally, redistribution commissions are insulated by statute and their boundaries take effect through a representation order, without a parliamentary vote to adopt them. Quebec goes furthest — its permanent independent commission establishes the final map itself, with no Assembly vote to adopt or override it. Even British Columbia, whose Legislative Assembly does vote to approve the commission's proposals and enact them in legislation, treats adopting the independent commission's work as the norm rather than substituting a map of its own.`,p6:`Alberta is the exception. Under the <em>Electoral Boundaries Commission Act</em>, the commission's report is a recommendation only — the legislature must vote to enact it. Approval is normally a formality. In the 2026 cycle, the commission split 3–2 and produced two competing proposals; the legislature created a separate MLA committee, chaired by a UCP MLA, to choose between them. Nothing in Canadian constitutional law required the committee to exist. Nothing requires its choice to follow the commission's process. This is the structural gap this audit is examining.`,p7:`So when Canadian courts say "gerrymander" isn't their legal vocabulary, they are not saying the underlying concept does not apply here. They are saying the test is different — effective representation, not mathematical equality. Whether the minority proposal meets that test is exactly the question this audit has measured the geometry against, and exactly the question only a judge can answer definitively. The <em>Saskatchewan Reference</em> reasoning in full, the contrast with other provinces, the standing question, and the available reform pathways are treated in <a href="#references">the references section below</a>.`},chrome:{back_to_top:`Back to top`,license_title:`Creative Commons Attribution-NonCommercial-ShareAlike 4.0`,license_alt:`CC BY-NC-SA 4.0`,license_aria:`Creative Commons BY-NC-SA 4.0`,back_to_stakes:`↑ Back to Stakes`,back_to_picture:`↑ Back to the picture`,lightbox:{fig_aria:`Figure enlarged view`,fig_close_aria:`Close enlarged figure (Esc)`,map_aria:`Map zoom viewer`,map_close_aria:`Close map viewer`,close_title:`Close (Esc)`},participation:{heading:`Help us refine MapExplorer`,body:`As you explore, we track which maps and districts you visit and periodically send the data to our research database. Sharing a view also saves where you ended up. The goal: understand what's useful and make the tool better.`,no_collect:`We never collect your name, IP address, or precise location. Everything is anonymized in your browser before it leaves. We couldn't identify you from the data even if ordered to.`,dnt:`Your browser has Do Not Track enabled. No is pre-selected on your behalf. You can still choose Yes.`,no_thanks:`No thanks`,yes_help:`Yes, I'll help`,privacy_policy:`Privacy policy`},share:{button:`Share`,button_title:`Share or load a map configuration`,dialog_aria:`Share map configuration`,close_aria:`Close share panel`,share_label:`Share this configuration`,share_hint:`Type this code into any browser running the audit to load this configuration. The code is never placed in a URL.`,load_label:`Load a configuration`,load_btn:`Load`,load_placeholder:`alpine-eagle-banff`,copy:`Copy`,copied:`Copied!`,copy_failed:`Failed`,unrecognised:`Unrecognised code — check spelling.`},map:{minority:`Minority`,majority:`Majority`,current:`Current`,wasted:`Wasted`,wasted_title:`Efficiency-gap contribution per district`,partisan:`Partisan`,partisan_title:`Colour each district by partisan outcome (UCP blue / NDP orange)`,borders:`Borders`,flagged:`Flagged`,flagged_title:`All 7 configurations flagged by commission chair Justice Miller — switches to minority map automatically`,help_aria:`Map help`,help_title:`How to use the map`,pin_aria:`Pin Map`,pin_title:`Pin Map — prevent auto-pan on district click`,search_aria:`Find an electoral district`,search_placeholder:`Find district…`,zoom_aria:`Map zoom`,clear_aria:`Clear district selection`,clear_title:`Clear selection`,va_hint:`Click within this district to see polling station results`,va_close_aria:`Close polling station detail`,va_close_title:`Close`,object_title:`Alberta electoral district map — full resolution`,ea_credit:`Map data:`,cc_title:`Text content: CC BY-NC-SA 4.0`,cc_alt:`Creative Commons BY-NC-SA 4.0`,votes_suffix:`votes`,total_votes_suffix:`total votes`,pop_prefix:`Pop.`,voting_areas_suffix:`voting areas`,other_maps:`Other maps`,unique_boundary:`Boundary unique to this map`,in_person_votes:`in-person votes (excl. Vote Anywhere)`,load_error_generic:`Could not load the boundary map. Try reloading the page.`,load_error_map:`Could not load the {key} map — check your connection.`,context_minority:`2026 minority proposal · 2023 election results`,context_majority:`2026 majority proposal · 2023 election results`,context_2019:`2019 enacted boundaries · 2023 election results`,tag_min:`Min`,tag_maj:`Maj`,tag_2019:`2019`,dev_notice:`Map Explorer is under continuous live development and may sometimes break. If something looks wrong, come back in a few days — the issue will likely be resolved. Suggestions are welcome: %s.`,dev_notice_email_label:`email me`,dev_notice_dismiss:`Dismiss development notice`,skel_1:`Loading Map Explorer…`,skel_2:`drawing Alberta…`,skel_3:`crunching the numbers…`,skel_4:`counting every vote…`,skel_5:`plotting the boundaries…`,skel_6:`almost there…`},map_intro:{heading:`How to use the map`,click_district:`Click any district`,click_district_desc:`see 2023 election results and snap to it`,click_within:`Click within a selected district`,click_within_desc:`see individual polling station results (colour = vote split)`,dblclick:`Double-click a district`,dblclick_desc:`zoom to fill screen; double-click empty space to zoom out`,layers_primary:`Minority / Majority / Current`,layers_primary_desc:`switch the active boundary map`,layers_data:`Partisan / Wasted / Borders`,layers_data_desc:`toggle data layers`,search:`Find district`,search_desc:`jump by name; arrow keys pan, + / − zoom`,escape:`Escape`,escape_desc:`close this viewer`,s4_tip:`In §4, click <em>Show flagged districts on map</em> to highlight the Airdrie split and NE/central Calgary zone.`,got_it:`Got it`},footer:{title:`Alberta Electoral Boundary Audit — May 2026`,copyright:`© Will Conner 2026 —`,text_label:`Text:`,code_label:`Code:`,translation_label:`Translations:`,translation_credit:`Anthropic Fable 5 (AI) — awaiting native-speaker review`,data_credit:`Map data: secondary highways from the National Road Network, © Statistics Canada (Open Government Licence – Canada); other roads & water © OpenStreetMap contributors (ODbL); boundaries & results © Elections Alberta.`}},explorer:{controls:{panel_title:`Map controls`,close_aria:`Close map`,map_version_hdr:`Map version`,map_version_hint:`· click to toggle`,map_toggle_title:`Toggle this map on/off`,map_minority:`Minority`,map_majority:`Majority`,map_2019:`Official`,map_minority_short:`Min`,map_majority_short:`Maj`,map_2019_short:`Offic`,search_placeholder:`Search a district…`,search_aria:`Search districts`,search_clear_aria:`Clear search`,search_in:`in {ed}`,zoom_aria:`Zoom`,res_prefix:`1 pixel ≈`,zoom_official:`(Official)`,zoom_computed:`(Computed)`,overlays_hdr:`Community Interest Overlays`,layer_highways:`Highways`,layer_water:`Rivers & lakes`,layer_annotations:`EBC '26 Annotations`,mobile_map_version_aria:`Map version`,mobile_search_aria:`Search districts`,mobile_layers_aria:`Map layers`,mobile_info_aria:`About the boundary lines`,mobile_share_aria:`Share this view`,mobile_close_aria:`Close map`,lang_aria:`Change language`,lang_hdr:`Language`,lines_note_title:`Reading the lines`,lines_note_lead:`Every odd shape or split line is a`,lines_note_emphasis:`deliberate choice by the committee`,lines_note_tail:`— not a data error. Lines follow the edges of polling areas; where two maps agree they sit on the same line, where they split apart the proposals genuinely disagree.`},share:{button:`Share this view`,heading:`Share this view`,copy:`Copy link`,copied:`Copied`,help:`This link captures your current map, overlays, and view.`,open_heading:`Open a shared link`,open_placeholder:`Paste a share link…`,open_btn:`Open`,err_empty:`Paste a share link`,err_invalid:`Not a valid share link`},tip:{total_votes:`total votes`,inperson_votes:`in-person votes`,ed_total:`District total: {n} votes`,ed_total_eday:`District total: {n} (election-day)`,poll:`Poll #{id}`,ucp_pct:`UCP {u}%`,ndp_pct:`NDP {n}%`,unassigned:`(unassigned)`,where_in:`in {community}`,where_near:`near {community}`,note_sparse:`A sparsely populated area — with few votes cast here, the colour stays close to the map's neutral baseline.`,note_no_votes:`No votes were recorded here, so this area shows the map's neutral baseline tone.`,no_one_title:`No one votes here`,no_one_body:`No polling division covers this spot — nobody is recorded living or voting here, so it stays the map's neutral tone.`,flag_link:`Click to zoom in`},miller:{locked_hint:`Nothing inside this outline moves under Recommendation 5.`,title:`Recommendation 5(d): the rural seat to restore`,body:`Justice Dallas Miller, the commission’s chair, wrote that if the Legislature would not accept losing two rural ridings, it should go from 89 seats to 91 and restore them. This is the one place he named for a restored seat: a riding made mostly of Clearwater County and western Mountain View County, with s. 15(2) status (the rule that lets a large, remote riding have far fewer people than average). He asked that it be considered, not required. The outline is approximate: Clearwater County plus the part of Mountain View County that sat in the 2019 Rimbey-Rocky Mountain House-Sundre riding. It lies wholly north of Airdrie and takes no land from any riding conditions (a) or (b) protect. He named no place for the second seat.`,a:{title:`Recommendation 5(a): no change from Airdrie south`,body:`The chair’s Recommendation 5 says restoring the two rural seats should not touch any riding in Airdrie, or with land south of Airdrie’s southern city limit, except Drumheller-Stettler. That is {n} ridings, every Calgary seat among them, that should match the majority map line for line. Airdrie and Calgary are where the commission split most sharply; this condition keeps them as the majority drew them.`},b:{title:`Recommendation 5(b): no change in north Edmonton`,body:`Recommendation 5 says restoring the two rural seats should not touch any Edmonton riding north of the North Saskatchewan River. That is {n} ridings that should match the majority map. Beverly-Clareview crosses the river; about two-thirds of it is on the north bank, so it is counted here.`},c:{title:`Recommendation 5(c): south Edmonton goes back to the draft`,body:`Recommendation 5 says every Edmonton riding south of the North Saskatchewan River should return to the commission’s October 2025 interim map, the draft it published for comment before the final split. One option is allowed: adding Nisku to Edmonton-South East, to put Leduc and Beaumont back in one riding. This outline marks the {n} majority-map ridings that would change. It does not show the interim lines themselves.`}},flags:{"banff-town":{title:`Banff — the town carved out of the park`,body:`Banff sits inside a federal national park, as a small municipal island. The minority groups the townsite with Canmore — the next town down the Bow Valley — in “Canmore-Kananaskis,” and leaves the uninhabited park as the riding that carries Banff's name. The boundary hugs the town because it's the only populated spot for miles. It looks like a mistake, but it follows real geography.`},"banff-park":{title:`North of Banff — “Rocky Mountain House–Banff Park”`,body:`“Rocky Mountain House–Banff Park” is one of the minority's proposed ridings, made up largely of uninhabited national park; the town of Banff sits in a neighbouring riding to the south. The minority applied the Electoral Boundaries Commission Act's smaller-population provision to this riding — a choice the commission's chair addressed in the final report.`},"airdrie-split":{title:`Airdrie — split four ways`,body:`Airdrie's growth and its commute to Calgary (about 76% of out-commuters) could have anchored a single new Airdrie-area seat — the kind the data supports. The minority instead splits the city across four ridings; the population math doesn't require it, and no submission proposed it. On the audit's cracking-signature test this four-way split meets every criterion — outside Airdrie East, which holds more than half the city, Airdrie's residents end up a minority — where the majority's two-way split shows none. This is a community split, invisible to the partisan-fairness tests; the audit measures the structural effect, not intent. (Academic §5.3.2.)`},"nolan-hill-cochrane":{title:`Calgary-Nolan Hill–Cochrane`,body:`Cochrane's commute to Calgary could have justified pairing it with the city — but the 2021 journey-to-work data spreads that flow city-wide (about a third of workers; half work within Cochrane) and doesn't point to Nolan Hill. The minority's narrow corridor to the Nolan Hill ward — the shape the chair called a lasso — reaches further than the data, and no submission proposed it. The audit reads this as cracking-adjacent: it thins Cochrane's voice, but Cochrane (about 34,000) is too small for a seat of its own, so it stops short of a formal cracking sign. (Academic §5.3.2.)`},"olds-airdrie-reach":{title:`Olds–Three Hills–Didsbury — the Airdrie reach`,body:`A rural riding keeping the Highway 2 towns — Olds, Didsbury, Three Hills — together is well supported; Beiseker-area residents wrote in favour of it. It could have stayed within those communities. The minority's version instead reaches south into the northern edge of Airdrie, an extension the population math doesn't require. The reach is part of how the four-way Airdrie split works — a thinly settled strip of the city, about 350 people, absorbed into a larger rural seat — which the audit reads as part of the cracking pattern. (Academic §5.3.2.)`},chestermere:{title:`Chestermere — split between two ridings`,body:`Chestermere's heavy commute to Calgary (86% of out-commuters) could have supported keeping it whole and near the city — which residents who opposed a Calgary merger also wanted. The minority instead slices a southern piece into a specific Calgary district it shares no schools or transit with, and that slice fails the population test. The audit reads the bleed into a Calgary district as cracking-adjacent — a community-of-interest split that thins Chestermere's voice without rising to a formal cracking signature. (Academic §5.3.2, §5.8.4.)`},"red-deer":{title:`Red Deer — the hybrid ridings`,body:`Red Deer's regional ties to Blackfalds, Sylvan Lake, Lacombe and Innisfail could have grouped those towns together — a city councillor and residents proposed similar hybrids. The minority's version instead folds parts of the city itself into town-led ridings, thinning urban Red Deer's vote; its “shared schools” rationale also doesn't hold (different school divisions). Folding a city into town-led ridings is the pattern the audit calls hybridization — consistent with cracking, achieving the partisan effect inside the hybrid ridings rather than across them. (Academic §5.3.5.)`},"st-albert":{title:`St. Albert — competing configurations`,body:`Either map's version of St. Albert could rest on a reasonable basis. The audit simply found no submission backing the minority's specific alternative — and since citizens rarely name a commission's exact boundaries, it treats the evidence here as thin, not clearly for or against.`},"calgary-zone-a-packing":{title:`Calgary north & east — a packing signature`,body:`The commission chair didn't flag this one — the audit's own math does. Across Calgary's north and east (the audit's “Zone A,” north and east of the Bow River), the minority map's districts run about 11.5% larger than the provincial average, against 2.8% on the majority map. Packing means concentrating one side's voters into fewer, larger districts, so each of their ballots weighs a little less; Zone A is NDP-competitive, and 13 of its 17 districts were NDP-won in 2023. The audit measures the structural effect, not intent. (Academic §5.3.1.)`}},text:{page_title:`Text version — Alberta Electoral Boundary Audit map`,intro:`This is the text version of the audit’s interactive map. It carries the same information as the visual map, written out so it can be read with a screen reader. It leads with the boundaries the audit flagged, then lists every district and which of the three maps includes it.`,link_map:`Open the interactive map`,link_report:`Read the full report`,link_to_text:`Open the accessible text version of this map`,toc_heading:`On this page`,toc_summary:`Short summary`,toc_flagged:`Flagged boundaries`,toc_r5:`Recommendation 5 areas`,toc_directory:`District directory`,summary_heading:`Short summary`,summary_p1:`The audit compares three maps of Alberta’s electoral districts: the commission’s minority proposal, its majority proposal, and the 2019 enacted map that is in force today.`,summary_p2:`On the audit’s pre-registered structural tests, which use geometry alone, the majority map crosses none of the five thresholds and the minority map crosses four of the five. The separate statistical results, which compare each map against a large set of computer-drawn neutral maps, are preliminary and are pending independent expert review.`,summary_p3:`The sections below explain nine specific boundaries the audit flagged, then list every district. This page describes the statistical and structural position only. It does not reach a legal conclusion about any map.`,flagged_heading:`Flagged boundaries`,flagged_lead:`The audit flagged nine boundaries. Some look unusual but faithfully follow real geography; others match a packing or cracking pattern in the audit’s own measurements. Each is explained below, with a section reference to the academic report where it applies.`,r5_heading:`Recommendation 5 areas`,r5_lead:`The government cited the commission chair’s Recommendation 5 when it handed the map to an MLA committee. The recommendation sets four conditions for a 91-seat map, three of them tied to districts on the majority map. Each area the map draws is described below, with the majority-map districts it covers.`,r5_districts:`Majority-map districts in this area:`,directory_heading:`District directory`,directory_lead:`This table lists every district name that appears on any of the three maps, in alphabetical order. For each name it shows whether that name is part of the minority proposal, the majority proposal, and the 2019 enacted map. District names differ between the maps, so some rows appear on only one or two of them. The table holds names and map membership only — for vote totals, population figures, and test results, see the full report.`,directory_totals_note:`Each figure is the district’s in-person (election-day) vote total on that map — the sum of its polls. Advance and special ballots are not attributed per voting area, so they are not included here; for full results see the report. A dash (—) means the district name does not appear on that map.`,col_district:`District`,col_minority:`Minority proposal`,col_majority:`Majority proposal`,col_2019:`Official map`,present_yes:`Yes`,present_no:`No`,methodology_note:`This page is a static, text-only equivalent of the interactive map. It is built from the same district data and the same boundary annotations. The statistical (neutral-ensemble) findings referenced here are preliminary and pending independent expert review.`,skip_to_main:`Skip to main content`,back_to_map:`Back to the interactive map`}},feedback:{nav_link:`Send feedback`,page_title:`Send feedback`,meta_description:`Share a correction, question, or suggestion about the Alberta Electoral Boundary Audit.`,heading:`Send feedback`,intro:`Spotted an error, have a question, or want to suggest an improvement? This goes straight to the author. Name and email are optional — leave an email only if you would like a reply.`,name_label:`Name`,name_optional:`optional`,name_placeholder:`Your name`,email_label:`Email`,email_optional:`optional`,email_placeholder:`you@example.com`,email_hint:`Only used to reply to you. Never shared, never added to any list.`,message_label:`Message`,message_required:`required`,message_placeholder:`What would you like to tell us?`,submit:`Send feedback`,submitting:`Sending…`,success_title:`Thank you`,success_body:`Your feedback has been received. If you left an email address and your message calls for a reply, you will hear back.`,send_another:`Send another`,error_empty:`Please enter a message before sending.`,error_rate:`You have sent several messages recently. Please try again in a little while.`,error_generic:`Something went wrong sending your feedback. Please try again in a moment.`,privacy_note:`Your message is stored securely in Canada and used only to improve this audit. See the {privacy} for details.`,privacy_link_text:`privacy policy`,back_to_report:`Back to the report`,back_to_map:`Back to the map explorer`}};function S(e){return e===`en`?x:g(e)}function C(e,t){let n=e;for(let e of t.split(`.`))if(n&&typeof n==`object`&&e in n)n=n[e];else return;return n}function w(e,t){h();let n=C(S(e),t);if(typeof n==`string`)return n;let r=C(x,t);return typeof r==`string`?r:`[missing:${t}]`}export{b as a,a as i,x as n,y as o,o as r,w as t};